var import_urijs13 = __toESM(require_URI(), 1);
describe("Core/buildModuleUrl", function() {
  it("produces an absolute URL for a module", function() {
    const url2 = buildModuleUrl_default("Workers/transferTypedArrayTest.js");
    expect(url2).toMatch(/Workers\/transferTypedArrayTest.js$/);
    const uri = new import_urijs13.default(url2);
    expect(uri.scheme().length).toBeGreaterThan(0);
    expect(uri.fragment().length).toEqual(0);
    return Resource_default.fetchText(url2);
  });
  it("matches the expected forms of URLs to Cesium.js", function() {
    const r2 = buildModuleUrl_default._cesiumScriptRegex;
    expect(r2.exec("Cesium.js")[1]).toEqual("");
    expect(r2.exec("Cesium.js?v=1.7")[1]).toEqual("");
    expect(r2.exec("assets/foo/Cesium.js")[1]).toEqual("assets/foo/");
    expect(r2.exec("assets/foo/Cesium.js?v=1.7")[1]).toEqual("assets/foo/");
    expect(
      r2.exec("http://example.invalid/Cesium/assets/foo/Cesium.js")[1]
    ).toEqual("http://example.invalid/Cesium/assets/foo/");
    expect(
      r2.exec("http://example.invalid/Cesium/assets/foo/Cesium.js?v=1.7")[1]
    ).toEqual("http://example.invalid/Cesium/assets/foo/");
    expect(r2.exec("cesium.js")).toBeNull();
    expect(r2.exec("Cesium.js%20")).toBeNull();
    expect(r2.exec("Cesium.min.js")).toBeNull();
    expect(r2.exec("CesiumSomething.js")).toBeNull();
    expect(r2.exec("CesiumSomething.js?v=1.7")).toBeNull();
    expect(r2.exec("assets/foo/bar.cesium.js")).toBeNull();
    expect(r2.exec("assets/foo/bar.cesium.js?v=1.7")).toBeNull();
    expect(r2.exec("assets/foo/CesiumSomething.js")).toBeNull();
    expect(r2.exec("assets/foo/CesiumSomething.js?v=1.7")).toBeNull();
  });
  it("CESIUM_BASE_URL works with trailing slash", function() {
    const oldCESIUM_BASE_URL = window.CESIUM_BASE_URL;
    window.CESIUM_BASE_URL = "http://test.com/source/";
    buildModuleUrl_default._clearBaseResource();
    const url2 = buildModuleUrl_default._buildModuleUrlFromBaseUrl("Core/Cartesian3.js");
    expect(url2).toEqual("http://test.com/source/Core/Cartesian3.js");
    window.CESIUM_BASE_URL = oldCESIUM_BASE_URL;
    buildModuleUrl_default._clearBaseResource();
  });
  it("CESIUM_BASE_URL works without trailing slash", function() {
    const oldCESIUM_BASE_URL = window.CESIUM_BASE_URL;
    window.CESIUM_BASE_URL = "http://test.com/source";
    buildModuleUrl_default._clearBaseResource();
    const url2 = buildModuleUrl_default._buildModuleUrlFromBaseUrl("Core/Cartesian3.js");
    expect(url2).toEqual("http://test.com/source/Core/Cartesian3.js");
    window.CESIUM_BASE_URL = oldCESIUM_BASE_URL;
    buildModuleUrl_default._clearBaseResource();
  });
});

// packages/engine/Specs/Core/CartographicGeocoderServiceSpec.js
describe("Core/CartographicGeocoderService", function() {
  const service = new CartographicGeocoderService_default();
  it("conforms to GeocoderService interface", function() {
    expect(CartographicGeocoderService_default).toConformToInterface(GeocoderService_default);
  });
  it("returns cartesian with matching coordinates for NS/EW input", function() {
    const query = "35N 75W";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(1);
      expect(results[0].destination).toEqual(
        Cartesian3_default.fromDegrees(-75, 35, 300)
      );
    });
  });
  it("returns cartesian with matching coordinates for EW/NS input", function() {
    const query = "75W 35N";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(1);
      expect(results[0].destination).toEqual(
        Cartesian3_default.fromDegrees(-75, 35, 300)
      );
    });
  });
  it("returns cartesian with matching coordinates for long/lat/height input", function() {
    const query = " 1.0, 2.0, 3.0 ";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(1);
      expect(results[0].destination).toEqual(
        Cartesian3_default.fromDegrees(1, 2, 3)
      );
    });
  });
  it("returns cartesian with matching coordinates for long/lat input", function() {
    const query = " 1.0, 2.0 ";
    const defaultHeight = 300;
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(1);
      expect(results[0].destination).toEqual(
        Cartesian3_default.fromDegrees(1, 2, defaultHeight)
      );
    });
  });
  it("returns empty array for input with only longitudinal coordinates", function() {
    const query = " 1e 1e ";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(0);
    });
  });
  it("returns empty array for input with only one NSEW coordinate", function() {
    const query = " 1e 1 ";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(0);
    });
  });
  it("returns empty array for input with only one number", function() {
    const query = " 2.0 ";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(0);
    });
  });
  it("returns empty array for with string", function() {
    const query = " aoeu ";
    return service.geocode(query).then(function(results) {
      expect(results.length).toEqual(0);
    });
  });
});

