// packages/engine/Specs/Core/FullscreenSpec.js
describe("Core/Fullscreen", function() {
  it("can tell if fullscreen is supported", function() {
    expect(Fullscreen_default.supportsFullscreen()).toBeDefined();
  });
  it("can tell if fullscreen is enabled", function() {
    if (Fullscreen_default.supportsFullscreen()) {
      expect(Fullscreen_default.enabled).toBeDefined();
    } else {
      expect(Fullscreen_default.enabled).toBeUndefined();
    }
  });
  it("can get fullscreen element", function() {
    if (Fullscreen_default.supportsFullscreen()) {
      expect(Fullscreen_default.element).toBeNull();
    } else {
      expect(Fullscreen_default.element).toBeUndefined();
    }
  });
  it("can tell if the browser is in fullscreen", function() {
    if (Fullscreen_default.supportsFullscreen()) {
      expect(Fullscreen_default.fullscreen).toEqual(false);
    } else {
      expect(Fullscreen_default.fullscreen).toBeUndefined();
    }
  });
  it("can request fullscreen", function() {
    if (Fullscreen_default.supportsFullscreen()) {
      spyOn(document.body, Fullscreen_default._names.requestFullscreen);
      spyOn(document, Fullscreen_default._names.exitFullscreen);
      Fullscreen_default.requestFullscreen(document.body);
      expect(
        document.body[Fullscreen_default._names.requestFullscreen]
      ).toHaveBeenCalled();
      Fullscreen_default.exitFullscreen();
      expect(document[Fullscreen_default._names.exitFullscreen]).toHaveBeenCalled();
    } else {
      Fullscreen_default.requestFullscreen(document.body);
      Fullscreen_default.exitFullscreen();
    }
  });
  it("can get the fullscreen change event name", function() {
    if (Fullscreen_default.supportsFullscreen()) {
      expect(document[`on${Fullscreen_default.changeEventName}`]).toBeDefined();
    } else {
      expect(Fullscreen_default.changeEventName).toBeUndefined();
    }
  });
  it("can get the fullscreen error event name", function() {
    if (Fullscreen_default.supportsFullscreen()) {
      expect(document[`on${Fullscreen_default.errorEventName}`]).toBeDefined();
    } else {
      expect(Fullscreen_default.errorEventName).toBeUndefined();
    }
  });
});

