    expect(provider.negativeAltitudeThreshold).toBe(Math_default.EPSILON12);
    expect(provider.negativeAltitudeExponentBias).toBe(32);
    expect(provider.providers).toEqual({});
    const tileInfo = provider._tileInfo["0"];
