// packages/engine/Specs/Core/GoogleEarthEnterpriseTerrainDataSpec.js
describe("Core/GoogleEarthEnterpriseTerrainData", function() {
  const sizeOfUint8 = Uint8Array.BYTES_PER_ELEMENT;
  const sizeOfUint162 = Uint16Array.BYTES_PER_ELEMENT;
  const sizeOfInt322 = Int32Array.BYTES_PER_ELEMENT;
  const sizeOfUint329 = Uint32Array.BYTES_PER_ELEMENT;
  const sizeOfFloat2 = Float32Array.BYTES_PER_ELEMENT;
  const sizeOfDouble2 = Float64Array.BYTES_PER_ELEMENT;
  const toEarthRadii = 1 / 6371010;
  function getBuffer(tilingScheme3, x, y, level) {
    const rectangle = tilingScheme3.tileXYToRectangle(x, y, level);
    const center = Rectangle_default.center(rectangle);
    const southwest = Rectangle_default.southwest(rectangle);
    const stepX = Math_default.toDegrees(rectangle.width / 2) / 180;
    const stepY = Math_default.toDegrees(rectangle.height / 2) / 180;
    const pointSize = 2 * sizeOfUint8 + sizeOfFloat2;
    const faceSize = 3 * sizeOfUint162;
    const quadSize = 4 * sizeOfDouble2 + 3 * sizeOfInt322 + 4 * pointSize + 2 * faceSize;
    const totalSize = 4 * (quadSize + sizeOfUint329);
    const buf = new ArrayBuffer(totalSize);
    const dv = new DataView(buf);
    let altitudeStart;
    let offset = 0;
    for (let i = 0; i < 4; ++i) {
      altitudeStart = 0;
      dv.setUint32(offset, quadSize, true);
      offset += sizeOfUint329;
      let xOrigin = southwest.longitude;
      let yOrigin = southwest.latitude;
      if ((i & 2) !== 0) {
        if ((i & 1) === 0) {
          xOrigin = center.longitude;
          altitudeStart = 10;
        }
        yOrigin = center.latitude;
      } else if ((i & 1) !== 0) {
        xOrigin = center.longitude;
        altitudeStart = 10;
      }
      dv.setFloat64(offset, Math_default.toDegrees(xOrigin) / 180, true);
      offset += sizeOfDouble2;
      dv.setFloat64(offset, Math_default.toDegrees(yOrigin) / 180, true);
      offset += sizeOfDouble2;
      dv.setFloat64(offset, stepX, true);
      offset += sizeOfDouble2;
      dv.setFloat64(offset, stepY, true);
      offset += sizeOfDouble2;
      dv.setInt32(offset, 4, true);
      offset += sizeOfInt322;
      dv.setInt32(offset, 2, true);
      offset += sizeOfInt322;
      dv.setInt32(offset, 0, true);
      offset += sizeOfInt322;
      let j;
      for (j = 0; j < 4; ++j) {
        let xPos = 0;
        let yPos = 0;
        let altitude = altitudeStart;
        if (j & 1) {
          ++xPos;
          altitude += 10;
        }
        if (j & 2) {
          ++yPos;
        }
        dv.setUint8(offset++, xPos);
        dv.setUint8(offset++, yPos);
        dv.setFloat32(offset, altitude * toEarthRadii, true);
        offset += sizeOfFloat2;
      }
      const indices = [0, 1, 2, 1, 3, 2];
      for (j = 0; j < indices.length; ++j) {
        dv.setUint16(offset, indices[j], true);
        offset += sizeOfUint162;
      }
    }
    return buf;
  }
  it("conforms to TerrainData interface", function() {
    expect(GoogleEarthEnterpriseTerrainData_default).toConformToInterface(TerrainData_default);
  });
  describe("upsample", function() {
    it("works for all four children of a simple quad", function() {
      const maxShort3 = 32767;
      let tilingScheme3 = new GeographicTilingScheme_default();
      const buffer3 = getBuffer(tilingScheme3, 0, 0, 0);
      const data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: buffer3,
        childTileMask: 15,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
      tilingScheme3 = new GeographicTilingScheme_default();
      const childRectangles = [
        tilingScheme3.tileXYToRectangle(0, 0, 1),
        tilingScheme3.tileXYToRectangle(1, 0, 1),
        tilingScheme3.tileXYToRectangle(0, 1, 1),
        tilingScheme3.tileXYToRectangle(1, 1, 1)
      ];
      return Promise.resolve(
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: 0,
          y: 0,
          level: 0
        })
      ).then(function() {
        const swPromise = data.upsample(tilingScheme3, 0, 0, 0, 0, 0, 1);
        const sePromise = data.upsample(tilingScheme3, 0, 0, 0, 1, 0, 1);
        const nwPromise = data.upsample(tilingScheme3, 0, 0, 0, 0, 1, 1);
        const nePromise = data.upsample(tilingScheme3, 0, 0, 0, 1, 1, 1);
        return Promise.all([swPromise, sePromise, nwPromise, nePromise]);
      }).then(function(upsampleResults) {
        expect(upsampleResults.length).toBe(4);
        for (let i = 0; i < upsampleResults.length; ++i) {
          const upsampled = upsampleResults[i];
          expect(upsampled).toBeDefined();
          const uBuffer = upsampled._uValues;
          const vBuffer = upsampled._vValues;
          const ib = upsampled._indices;
          const heights = upsampled._heightValues;
          expect(uBuffer.length).toBe(4);
          expect(vBuffer.length).toBe(4);
          expect(heights.length).toBe(4);
          expect(ib.length).toBe(6);
          const rectangle = childRectangles[i];
          let north = 0;
          let south = 0;
          let east = 0;
          let west = 0;
          let index, u3, v3;
          for (let j = 0; j < ib.length; ++j) {
            index = ib[j];
            u3 = uBuffer[index] / maxShort3 * rectangle.width + rectangle.west;
            v3 = vBuffer[index] / maxShort3 * rectangle.height + rectangle.south;
            if (Math_default.equalsEpsilon(u3, rectangle.west, Math_default.EPSILON7)) {
              ++west;
            } else if (Math_default.equalsEpsilon(u3, rectangle.east, Math_default.EPSILON7)) {
              ++east;
            }
            if (Math_default.equalsEpsilon(
              v3,
              rectangle.south,
              Math_default.EPSILON7
            )) {
              ++south;
            } else if (Math_default.equalsEpsilon(
              v3,
              rectangle.north,
              Math_default.EPSILON7
            )) {
              ++north;
            }
          }
          expect(north).toEqual(3);
          expect(south).toEqual(3);
          expect(east).toEqual(3);
          expect(west).toEqual(3);
          expect(upsampled._westIndices.length).toEqual(2);
          expect(upsampled._southIndices.length).toEqual(2);
          expect(upsampled._eastIndices.length).toEqual(2);
          expect(upsampled._northIndices.length).toEqual(2);
        }
      });
    });
  });
  describe("createMesh", function() {
    let data;
    let tilingScheme3;
    let buffer3;
    beforeEach(function() {
      tilingScheme3 = new GeographicTilingScheme_default();
      buffer3 = getBuffer(tilingScheme3, 0, 0, 0);
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: buffer3,
        childTileMask: 15,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
    });
    it("requires tilingScheme", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: void 0,
          x: 0,
          y: 0,
          level: 0
        });
      }).toThrowDeveloperError();
    });
    it("requires x", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: void 0,
          y: 0,
          level: 0
        });
      }).toThrowDeveloperError();
    });
    it("requires y", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: 0,
          y: void 0,
          level: 0
        });
      }).toThrowDeveloperError();
    });
    it("requires level", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: 0,
          y: 0,
          level: void 0
        });
      }).toThrowDeveloperError();
    });
    it("creates specified vertices plus skirt vertices", function() {
      const rectangle = tilingScheme3.tileXYToRectangle(0, 0, 0);
      const wgs84 = Ellipsoid_default.WGS84;
      return data.createMesh({
        tilingScheme: tilingScheme3,
        x: 0,
        y: 0,
        level: 0
      }).then(function(mesh) {
        expect(mesh).toBeInstanceOf(TerrainMesh_default);
        expect(mesh.vertices.length).toBe(17 * mesh.encoding.stride);
        expect(mesh.indices.length).toBe(4 * 6 * 3);
        expect(mesh.minimumHeight).toBe(0);
        expect(mesh.maximumHeight).toBeCloseTo(20, 5);
        const encoding = mesh.encoding;
        const cartesian16 = new Cartesian3_default();
        const cartographic2 = new Cartographic_default();
        const count = mesh.vertices.length / mesh.encoding.stride;
        for (let i = 0; i < count; ++i) {
          const height = encoding.decodeHeight(mesh.vertices, i);
          if (i < 9) {
            expect(height).toBeBetween(0, 20);
            encoding.decodePosition(mesh.vertices, i, cartesian16);
            wgs84.cartesianToCartographic(cartesian16, cartographic2);
            cartographic2.longitude = Math_default.convertLongitudeRange(
              cartographic2.longitude
            );
            expect(Rectangle_default.contains(rectangle, cartographic2)).toBe(true);
          } else {
            expect(height).toBeBetween(-1e3, -980);
          }
        }
      });
    });
    it("exaggerates mesh", function() {
      return data.createMesh({
        tilingScheme: tilingScheme3,
        x: 0,
        y: 0,
        level: 0,
        exaggeration: 2
      }).then(function(mesh) {
        expect(mesh).toBeInstanceOf(TerrainMesh_default);
        expect(mesh.vertices.length).toBe(17 * mesh.encoding.stride);
        expect(mesh.indices.length).toBe(4 * 6 * 3);
        expect(mesh.minimumHeight).toBe(0);
        expect(mesh.maximumHeight).toBeCloseTo(20, 5);
        expect(mesh.encoding.exaggeration).toBe(2);
        const encoding = mesh.encoding;
        const count = mesh.vertices.length / mesh.encoding.stride;
        for (let i = 0; i < count; ++i) {
          const height = encoding.decodeHeight(mesh.vertices, i);
          if (i < 9) {
            expect(height).toBeBetween(0, 40);
          } else {
            expect(height).toBeBetween(-1e3, -960);
          }
        }
      });
    });
  });
  describe("interpolateHeight", function() {
    let tilingScheme3;
    let rectangle;
    let mesh;
    beforeEach(function() {
      tilingScheme3 = new GeographicTilingScheme_default();
      rectangle = tilingScheme3.tileXYToRectangle(7, 6, 5);
      const buffer3 = getBuffer(tilingScheme3, 7, 6, 5);
      mesh = new GoogleEarthEnterpriseTerrainData_default({
        buffer: buffer3,
        childTileMask: 15,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
    });
    it("clamps coordinates if given a position outside the mesh", function() {
      expect(mesh.interpolateHeight(rectangle, 0, 0)).toBe(
        mesh.interpolateHeight(rectangle, rectangle.east, rectangle.south)
      );
    });
    it("returns a height interpolated from the correct triangle", function() {
      let longitude = rectangle.west + (rectangle.east - rectangle.west) * 0.25;
      let latitude = rectangle.south + (rectangle.north - rectangle.south) * 0.75;
      let result = mesh.interpolateHeight(rectangle, longitude, latitude);
      expect(result).toBeBetween(0, 10);
      longitude = rectangle.west + (rectangle.east - rectangle.west) * 0.75;
      latitude = rectangle.south + (rectangle.north - rectangle.south) * 0.25;
      result = mesh.interpolateHeight(rectangle, longitude, latitude);
      expect(result).toBeBetween(10, 20);
      longitude = rectangle.west + (rectangle.east - rectangle.west) * 0.5;
      latitude = rectangle.south + (rectangle.north - rectangle.south) * 0.5;
      result = mesh.interpolateHeight(rectangle, longitude, latitude);
      expect(result).toEqualEpsilon(10, 1e-6);
    });
  });
  describe("isChildAvailable", function() {
    let data;
    beforeEach(function() {
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 15,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
    });
    it("requires thisX", function() {
      expect(function() {
        data.isChildAvailable(void 0, 0, 0, 0);
      }).toThrowDeveloperError();
    });
    it("requires thisY", function() {
      expect(function() {
        data.isChildAvailable(0, void 0, 0, 0);
      }).toThrowDeveloperError();
    });
    it("requires childX", function() {
      expect(function() {
        data.isChildAvailable(0, 0, void 0, 0);
      }).toThrowDeveloperError();
    });
    it("requires childY", function() {
      expect(function() {
        data.isChildAvailable(0, 0, 0, void 0);
      }).toThrowDeveloperError();
    });
    it("returns true for all children when child mask is not explicitly specified", function() {
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
      expect(data.isChildAvailable(10, 20, 20, 40)).toBe(true);
      expect(data.isChildAvailable(10, 20, 21, 40)).toBe(true);
      expect(data.isChildAvailable(10, 20, 20, 41)).toBe(true);
      expect(data.isChildAvailable(10, 20, 21, 41)).toBe(true);
    });
    it("works when only southwest child is available", function() {
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 1,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
      expect(data.isChildAvailable(10, 20, 20, 40)).toBe(false);
      expect(data.isChildAvailable(10, 20, 21, 40)).toBe(false);
      expect(data.isChildAvailable(10, 20, 20, 41)).toBe(true);
      expect(data.isChildAvailable(10, 20, 21, 41)).toBe(false);
    });
    it("works when only southeast child is available", function() {
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 2,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
      expect(data.isChildAvailable(10, 20, 20, 40)).toBe(false);
      expect(data.isChildAvailable(10, 20, 21, 40)).toBe(false);
      expect(data.isChildAvailable(10, 20, 20, 41)).toBe(false);
      expect(data.isChildAvailable(10, 20, 21, 41)).toBe(true);
    });
    it("works when only northeast child is available", function() {
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 4,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
      expect(data.isChildAvailable(10, 20, 20, 40)).toBe(false);
      expect(data.isChildAvailable(10, 20, 21, 40)).toBe(true);
      expect(data.isChildAvailable(10, 20, 20, 41)).toBe(false);
      expect(data.isChildAvailable(10, 20, 21, 41)).toBe(false);
    });
    it("works when only northwest child is available", function() {
      data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 8,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
      expect(data.isChildAvailable(10, 20, 20, 40)).toBe(true);
      expect(data.isChildAvailable(10, 20, 21, 40)).toBe(false);
      expect(data.isChildAvailable(10, 20, 20, 41)).toBe(false);
      expect(data.isChildAvailable(10, 20, 21, 41)).toBe(false);
    });
  });
  it("requires buffer", function() {
    expect(function() {
      const data = new GoogleEarthEnterpriseTerrainData_default({
        childTileMask: 8,
        negativeAltitudeExponentBias: 32,
        negativeElevationThreshold: Math_default.EPSILON12
      });
    }).toThrowDeveloperError();
  });
  it("requires negativeAltitudeExponentBias", function() {
    expect(function() {
      const data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 8,
        negativeElevationThreshold: Math_default.EPSILON12
      });
    }).toThrowDeveloperError();
  });
  it("requires negativeElevationThreshold", function() {
    expect(function() {
      const data = new GoogleEarthEnterpriseTerrainData_default({
        buffer: new ArrayBuffer(1),
        childTileMask: 8,
        negativeAltitudeExponentBias: 32
      });
    }).toThrowDeveloperError();
  });
});

// packages/engine/Specs/Core/GoogleEarthEnterpriseTerrainProviderSpec.js
describe("Core/GoogleEarthEnterpriseTerrainProvider", function() {
  function installMockGetQuadTreePacket() {
    spyOn(
      GoogleEarthEnterpriseMetadata_default.prototype,
      "getQuadTreePacket"
    ).and.callFake(function(quadKey, version2) {
      quadKey = quadKey ?? "";
      let t2 = new GoogleEarthEnterpriseTileInformation_default(255, 1, 1, 1);
      t2.ancestorHasTerrain = true;
      this._tileInfo[`${quadKey}0`] = t2;
      t2 = new GoogleEarthEnterpriseTileInformation_default(255, 1, 1, 1);
      t2.ancestorHasTerrain = true;
      this._tileInfo[`${quadKey}1`] = t2;
      t2 = new GoogleEarthEnterpriseTileInformation_default(255, 1, 1, 1);
      t2.ancestorHasTerrain = true;
      this._tileInfo[`${quadKey}2`] = t2;
      t2 = new GoogleEarthEnterpriseTileInformation_default(255, 1, 1, 1);
      t2.ancestorHasTerrain = true;
      this._tileInfo[`${quadKey}3`] = t2;
      return Promise.resolve();
    });
  }
  let terrainProvider;
  async function waitForTile(level, x, y, f2) {
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    return pollToPromise_default(function() {
      return terrainProvider.getTileDataAvailable(x, y, level);
    }).then(function() {
      const promise = terrainProvider.requestTileGeometry(level, x, y);
      return Promise.resolve(promise, f2, function(error) {
        expect("requestTileGeometry").toBe("returning a tile.");
      });
    });
  }
  function createRequest() {
    return new Request_default({
      throttleByServer: true
    });
  }
  beforeEach(function() {
    RequestScheduler_default.clearForSpecs();
  });
  afterEach(function() {
    Resource_default._Implementations.loadWithXhr = Resource_default._DefaultImplementations.loadWithXhr;
  });
  it("conforms to TerrainProvider interface", function() {
    expect(GoogleEarthEnterpriseTerrainProvider_default).toConformToInterface(
      TerrainProvider_default
    );
  });
  it("fromMetadata throws without metadata", function() {
    installMockGetQuadTreePacket();
    expect(
      () => GoogleEarthEnterpriseTerrainProvider_default.fromMetadata()
    ).toThrowDeveloperError("metadata is required, actual value was undefined");
  });
  it("fromMetadata throws if there isn't terrain", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    metadata.terrainPresent = false;
    expect(
      () => GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata)
    ).toThrowError(
      RuntimeError_default,
      "The server made/up/url/ doesn't have terrain"
    );
  });
  it("uses geographic tiling scheme by default", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    expect(terrainProvider.tilingScheme).toBeInstanceOf(GeographicTilingScheme_default);
  });
  it("can use a custom ellipsoid", async function() {
    installMockGetQuadTreePacket();
    const ellipsoid = new Ellipsoid_default(1, 2, 3);
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(
      metadata,
      {
        ellipsoid
      }
    );
    expect(terrainProvider.tilingScheme.ellipsoid).toEqual(ellipsoid);
  });
  it("has error event", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    expect(terrainProvider.errorEvent).toBeDefined();
    expect(terrainProvider.errorEvent).toBe(terrainProvider.errorEvent);
  });
  it("returns reasonable geometric error for various levels", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    expect(terrainProvider.getLevelMaximumGeometricError(0)).toBeGreaterThan(
      0
    );
    expect(terrainProvider.getLevelMaximumGeometricError(0)).toEqualEpsilon(
      terrainProvider.getLevelMaximumGeometricError(1) * 2,
      Math_default.EPSILON10
    );
    expect(terrainProvider.getLevelMaximumGeometricError(1)).toEqualEpsilon(
      terrainProvider.getLevelMaximumGeometricError(2) * 2,
      Math_default.EPSILON10
    );
  });
  it("credit is undefined if credit is not provided", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    expect(terrainProvider.credit).toBeUndefined();
  });
  it("logo is defined if credit is provided", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(
      metadata,
      {
        credit: "thanks to our awesome made up contributors!"
      }
    );
    expect(terrainProvider.credit).toBeDefined();
  });
  it("has a water mask is false", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    expect(terrainProvider.hasWaterMask).toBe(false);
  });
  it("has vertex normals is false", async function() {
    installMockGetQuadTreePacket();
    const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
    terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
    expect(terrainProvider.hasVertexNormals).toBe(false);
  });
  describe("requestTileGeometry", function() {
    it("provides GoogleEarthEnterpriseTerrainData", function() {
      installMockGetQuadTreePacket();
      Resource_default._Implementations.loadWithXhr = function(url2, responseType, method, data, headers, deferred, overrideMimeType) {
        Resource_default._DefaultImplementations.loadWithXhr(
          "Data/GoogleEarthEnterprise/gee.terrain",
          responseType,
          method,
          data,
          headers,
          deferred
        );
      };
      return waitForTile(0, 0, 0, function(loadedData) {
        expect(loadedData).toBeInstanceOf(GoogleEarthEnterpriseTerrainData_default);
      });
    });
    it("provides GoogleEarthEnterpriseTerrainData with fromMetadata", async function() {
      installMockGetQuadTreePacket();
      Resource_default._Implementations.loadWithXhr = function(url2, responseType, method, data, headers, deferred, overrideMimeType) {
        Resource_default._DefaultImplementations.loadWithXhr(
          "Data/GoogleEarthEnterprise/gee.terrain",
          responseType,
          method,
          data,
          headers,
          deferred
        );
      };
      const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl("made/up/url");
      terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
      await pollToPromise_default(function() {
        return terrainProvider.getTileDataAvailable(0, 0, 0);
      });
      const loadedData = await terrainProvider.requestTileGeometry(0, 0, 0);
      expect(loadedData).toBeInstanceOf(GoogleEarthEnterpriseTerrainData_default);
    });
    it("returns undefined if too many requests are already in progress", async function() {
      installMockGetQuadTreePacket();
      const baseUrl2 = "made/up/url";
      const deferreds = [];
      let loadRealTile = true;
      Resource_default._Implementations.loadWithXhr = function(url2, responseType, method, data, headers, deferred, overrideMimeType) {
        if (url2.indexOf("dbRoot.v5") !== -1) {
          return deferred.reject();
        }
        if (loadRealTile) {
          loadRealTile = false;
          return Resource_default._DefaultImplementations.loadWithXhr(
            "Data/GoogleEarthEnterprise/gee.terrain",
            responseType,
            method,
            data,
            headers,
            deferred
          );
        }
        deferreds.push(deferred);
      };
      const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl(baseUrl2);
      terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
      const promises = [];
      return pollToPromise_default(function() {
        let b2 = true;
        for (let i = 0; i < RequestScheduler_default.maximumRequestsPerServer + 2; ++i) {
          b2 = b2 && terrainProvider.getTileDataAvailable(i, i, i);
        }
        return b2 && terrainProvider.getTileDataAvailable(1, 2, 3);
      }).then(function() {
        let promise;
        for (let i = 0; i < RequestScheduler_default.maximumRequestsPerServer; ++i) {
          const request = new Request_default({
            throttle: true,
            throttleByServer: true
          });
          promise = terrainProvider.requestTileGeometry(i, i, i, request);
          promises.push(promise);
        }
        RequestScheduler_default.update();
        expect(promise).toBeDefined();
        return terrainProvider.requestTileGeometry(1, 2, 3, createRequest());
      }).then(function(terrainData) {
        expect(terrainData).toBeUndefined();
        for (let i = 0; i < deferreds.length; ++i) {
          deferreds[i].resolve();
        }
        return Promise.all(promises).catch(function() {
          loadRealTile = true;
          return terrainProvider.requestTileGeometry(1, 2, 3);
        });
      }).then(function(terrainData) {
        expect(terrainData).toBeDefined();
      });
    });
    it("supports getTileDataAvailable()", async function() {
      installMockGetQuadTreePacket();
      const baseUrl2 = "made/up/url";
      Resource_default._Implementations.loadWithXhr = function(url2, responseType, method, data, headers, deferred, overrideMimeType) {
        Resource_default._DefaultImplementations.loadWithXhr(
          "Data/CesiumTerrainTileJson/tile.terrain",
          responseType,
          method,
          data,
          headers,
          deferred
        );
      };
      const metadata = await GoogleEarthEnterpriseMetadata_default.fromUrl(baseUrl2);
      terrainProvider = GoogleEarthEnterpriseTerrainProvider_default.fromMetadata(metadata);
      const tileInfo = terrainProvider._metadata._tileInfo;
      const info = tileInfo[GoogleEarthEnterpriseMetadata_default.tileXYToQuadKey(0, 1, 0)];
      info._bits = 127;
      info.terrainState = 1;
      info.ancestorHasTerrain = true;
      expect(terrainProvider.getTileDataAvailable(0, 0, 0)).toBe(true);
      expect(terrainProvider.getTileDataAvailable(0, 1, 0)).toBe(false);
      expect(terrainProvider.getTileDataAvailable(1, 0, 0)).toBe(true);
      expect(terrainProvider.getTileDataAvailable(1, 1, 0)).toBe(true);
      expect(terrainProvider.getTileDataAvailable(0, 0, 2)).toBe(false);
    });
  });
});

