// packages/engine/Specs/Core/HeapSpec.js
describe("Core/Heap", function() {
  const length3 = 100;
  function expectTrailingReferenceToBeRemoved(heap) {
    const array = heap._array;
    const length4 = heap._length;
    const reservedLength = array.length;
    for (let i = length4; i < reservedLength; ++i) {
      expect(array[i]).toBeUndefined();
    }
  }
  function checkHeap(heap, comparator2) {
    const array = heap.internalArray;
    let pass = true;
    const length4 = heap.length;
    for (let i = 0; i < length4; ++i) {
      const left = 2 * (i + 1) - 1;
      const right = 2 * (i + 1);
      if (left < heap.length) {
        pass = pass && comparator2(array[i], array[left]) <= 0;
      }
      if (right < heap.length) {
        pass = pass && comparator2(array[i], array[right]) <= 0;
      }
    }
    return pass;
  }
  function comparator(a3, b2) {
    return a3 - b2;
  }
  it("maintains heap property on insert", function() {
    const heap = new Heap_default({
      comparator
    });
    let pass = true;
    for (let i = 0; i < length3; ++i) {
      heap.insert(Math.random());
      pass = pass && checkHeap(heap, comparator);
    }
    expect(pass).toBe(true);
  });
  it("maintains heap property on pop", function() {
    const heap = new Heap_default({
      comparator
    });
    let i;
    for (i = 0; i < length3; ++i) {
      heap.insert(Math.random());
    }
    let pass = true;
    for (i = 0; i < length3; ++i) {
      heap.pop();
      pass = pass && checkHeap(heap, comparator);
    }
    expect(pass).toBe(true);
  });
  it("limited by maximum length", function() {
    const heap = new Heap_default({
      comparator
    });
    heap.maximumLength = length3 / 2;
    let pass = true;
    for (let i = 0; i < length3; ++i) {
      heap.insert(Math.random());
      pass = pass && checkHeap(heap, comparator);
    }
    expect(pass).toBe(true);
    expect(heap.length).toBeLessThanOrEqual(heap.maximumLength);
    expect(heap.internalArray.length).toBeLessThanOrEqual(
      heap.maximumLength + 1
    );
  });
  it("pops in sorted order", function() {
    const heap = new Heap_default({
      comparator
    });
    let i;
    for (i = 0; i < length3; ++i) {
      heap.insert(Math.random());
    }
    let curr = heap.pop();
    let pass = true;
    for (i = 0; i < length3 - 1; ++i) {
      const next = heap.pop();
      pass = pass && comparator(curr, next) <= 0;
      curr = next;
    }
    expect(pass).toBe(true);
  });
  it("pop removes trailing references", function() {
    const heap = new Heap_default({
      comparator
    });
    for (let i = 0; i < 10; ++i) {
      heap.insert(Math.random());
    }
    heap.pop();
    heap.pop();
    expectTrailingReferenceToBeRemoved(heap);
  });
  it("setting maximum length less than current length removes trailing references", function() {
    const heap = new Heap_default({
      comparator
    });
    for (let i = 0; i < 10; ++i) {
      heap.insert(Math.random());
    }
    heap.maximumLength = 5;
    expectTrailingReferenceToBeRemoved(heap);
  });
  it("insert returns the removed element when maximumLength is set", function() {
    const heap = new Heap_default({
      comparator
    });
    heap.maximumLength = length3;
    let i;
    let max3 = 0;
    let min3 = 1;
    const values = new Array(length3);
    for (i = 0; i < length3; ++i) {
      const value = Math.random();
      max3 = Math.max(max3, value);
      min3 = Math.min(min3, value);
      values[i] = value;
    }
    for (i = 0; i < length3 - 1; ++i) {
      heap.insert(values[i]);
    }
    let removed = heap.insert(values[length3 - 1]);
    expect(removed).toBeUndefined();
    removed = heap.insert(max3 - 0.1);
    expect(removed).toBeDefined();
    removed = heap.insert(max3 + 0.1);
    expect(removed).toBe(max3 + 0.1);
  });
  it("resort", function() {
    function comparator2(a3, b2) {
      return a3.distance - b2.distance;
    }
    let i;
    const heap = new Heap_default({
      comparator: comparator2
    });
    for (i = 0; i < length3; ++i) {
      heap.insert({
        distance: i / (length3 - 1),
        id: i
      });
    }
    let element;
    const elements = [];
    let currentId2 = 0;
    while (heap.length > 0) {
      element = heap.pop();
      elements.push(element);
      expect(element.id).toBeGreaterThanOrEqual(currentId2);
      currentId2 = element.id;
    }
    for (i = 0; i < length3; ++i) {
      heap.insert(elements[i]);
    }
    for (i = 0; i < length3; ++i) {
      elements[i].distance = 1 - elements[i].distance;
    }
    heap.resort();
    while (heap.length > 0) {
      element = heap.pop();
      expect(element.id).toBeLessThanOrEqual(currentId2);
      currentId2 = element.id;
    }
  });
  it("maximumLength setter throws if length is less than 0", function() {
    const heap = new Heap_default({
      comparator
    });
    expect(function() {
      heap.maximumLength = -1;
    }).toThrowDeveloperError();
  });
});

