// packages/engine/Specs/Core/isBlobUriSpec.js
describe("Core/isBlobUri", function() {
  it("Throws if url is undefined", function() {
    expect(function() {
      isBlobUri_default(void 0);
    }).toThrowDeveloperError();
  });
  it("Determines that a uri is not a blob uri", function() {
    expect(isBlobUri_default("http://cesiumjs.org/")).toEqual(false);
  });
  it("Determines that a uri is a blob uri", function() {
    const uint8Array = new Uint8Array(4);
    const blob = new Blob([uint8Array], {
      type: "application/octet-stream"
    });
    const blobUrl = window.URL.createObjectURL(blob);
    expect(isBlobUri_default(blobUrl)).toEqual(true);
  });
});

// packages/engine/Specs/Core/isCrossOriginUrlSpec.js
var import_urijs14 = __toESM(require_URI(), 1);
describe("Core/isCrossOriginUrl", function() {
  it("returns false for relative urls", function() {
    expect(isCrossOriginUrl_default("/some/url.jpg")).toEqual(false);
    expect(isCrossOriginUrl_default("some/url.jpg")).toEqual(false);
  });
  it("returns false for absolute urls that are not cross-origin", function() {
    let absoluteUrl = getAbsoluteUri_default("/some/url.jpg");
    expect(isCrossOriginUrl_default(absoluteUrl)).toEqual(false);
    absoluteUrl = getAbsoluteUri_default("some/url.jpg");
    expect(isCrossOriginUrl_default(absoluteUrl)).toEqual(false);
  });
  it("returns true for absolute urls that are cross-origin", function() {
    expect(isCrossOriginUrl_default("http://example.invalid/some/url.jpg")).toEqual(
      true
    );
    let pageUri2 = new import_urijs14.default(location.href);
    pageUri2.scheme(location.protocol === "https:" ? "http" : "https");
    let absoluteUrl = pageUri2.toString();
    expect(isCrossOriginUrl_default(absoluteUrl)).toEqual(true);
    pageUri2 = new import_urijs14.default(location.href);
    pageUri2.authority(`${location.hostname}:${+location.port + 1}`);
    absoluteUrl = pageUri2.toString();
    expect(isCrossOriginUrl_default(absoluteUrl)).toEqual(true);
  });
});

