  describe("createMesh", function() {
    let data;
    let tilingScheme3;
    function createSampleTerrainData() {
      return new QuantizedMeshTerrainData_default({
        minimumHeight: 0,
        maximumHeight: 4,
        quantizedVertices: new Uint16Array([
          // order is sw nw se ne
          // u
          0,
          0,
          32767,
          32767,
          // v
          0,
          32767,
          0,
          32767,
          // heights
          32767 / 4,
          2 * 32767 / 4,
          3 * 32767 / 4,
          32767
        ]),
        indices: new Uint16Array([0, 3, 1, 0, 2, 3]),
        boundingSphere: new BoundingSphere_default(),
        horizonOcclusionPoint: new Cartesian3_default(),
        westIndices: [0, 1],
        southIndices: [0, 1],
        eastIndices: [2, 3],
        northIndices: [1, 3],
        westSkirtHeight: 1,
        southSkirtHeight: 1,
        eastSkirtHeight: 1,
        northSkirtHeight: 1,
        childTileMask: 15
      });
    }
    beforeEach(function() {
      tilingScheme3 = new GeographicTilingScheme_default();
      data = createSampleTerrainData();
    });
    it("requires tilingScheme", function() {
      expect(function() {
        data.createMesh({ tilingScheme: void 0, x: 0, y: 0, level: 0 });
      }).toThrowDeveloperError();
    });
    it("requires x", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: void 0,
          y: 0,
          level: 0
        });
      }).toThrowDeveloperError();
    });
    it("requires y", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: 0,
          y: void 0,
          level: 0
        });
      }).toThrowDeveloperError();
    });
    it("requires level", function() {
      expect(function() {
        data.createMesh({
          tilingScheme: tilingScheme3,
          x: 0,
          y: 0,
          level: void 0
        });
      }).toThrowDeveloperError();
    });
    it("creates specified vertices plus skirt vertices", function() {
      return data.createMesh({ tilingScheme: tilingScheme3, x: 0, y: 0, level: 0 }).then(function(mesh) {
        expect(mesh).toBeInstanceOf(TerrainMesh_default);
        expect(mesh.vertices.length).toBe(12 * mesh.encoding.stride);
        expect(mesh.indices.length).toBe(10 * 3);
        expect(mesh.minimumHeight).toBe(data._minimumHeight);
        expect(mesh.maximumHeight).toBe(data._maximumHeight);
        expect(mesh.boundingSphere3D).toEqual(data._boundingSphere);
      });
    });
    it("exaggerates mesh", function() {
      return data.createMesh({
        tilingScheme: tilingScheme3,
        x: 0,
        y: 0,
        level: 0,
        exaggeration: 2
      }).then(function(mesh) {
        expect(mesh).toBeInstanceOf(TerrainMesh_default);
        expect(mesh.vertices.length).toBe(12 * mesh.encoding.stride);
        expect(mesh.indices.length).toBe(10 * 3);
        expect(mesh.minimumHeight).toBe(data._minimumHeight);
        expect(mesh.maximumHeight).toBe(data._maximumHeight);
        expect(mesh.boundingSphere3D.radius).toBe(
          data._boundingSphere.radius
        );
        expect(mesh.encoding.exaggeration).toBe(2);
      });
    });
    it("requires 32bit indices for large meshes", function() {
      const tilingScheme4 = new GeographicTilingScheme_default();
      const quantizedVertices = [];
      let i;
      for (i = 0; i < 65 * 1024; i++) {
        quantizedVertices.push(i % 32767);
      }
      for (i = 0; i < 65 * 1024; i++) {
        quantizedVertices.push(Math.floor(i / 32767));
      }
      for (i = 0; i < 65 * 1024; i++) {
        quantizedVertices.push(0);
      }
      const data2 = new QuantizedMeshTerrainData_default({
        minimumHeight: 0,
        maximumHeight: 4,
        quantizedVertices: new Uint16Array(quantizedVertices),
        indices: new Uint32Array([0, 3, 1, 0, 2, 3, 65e3, 65002, 65003]),
        boundingSphere: new BoundingSphere_default(),
        horizonOcclusionPoint: new Cartesian3_default(),
        westIndices: [0, 1],
        southIndices: [0, 1],
        eastIndices: [2, 3],
        northIndices: [1, 3],
        westSkirtHeight: 1,
        southSkirtHeight: 1,
        eastSkirtHeight: 1,
        northSkirtHeight: 1,
        childTileMask: 15
      });
      return data2.createMesh({ tilingScheme: tilingScheme4, x: 0, y: 0, level: 0 }).then(function(mesh) {
        expect(mesh).toBeInstanceOf(TerrainMesh_default);
        expect(mesh.indices.BYTES_PER_ELEMENT).toBe(4);
      });
    });
    it("enables throttling for asynchronous tasks", function() {
      const options = {
        tilingScheme: tilingScheme3,
        x: 0,
        y: 0,
        level: 0,
        throttle: true
      };
      const taskCount = TerrainData_default.maximumAsynchronousTasks + 1;
      const promises = new Array();
      for (let i = 0; i < taskCount; i++) {
        const tempData = createSampleTerrainData();
        const promise = tempData.createMesh(options);
        if (defined_default(promise)) {
          promises.push(promise);
        }
      }
      expect(promises.length).toBe(TerrainData_default.maximumAsynchronousTasks);
      return Promise.all(promises);
    });
    it("disables throttling for asynchronous tasks", function() {
      const options = {
        tilingScheme: tilingScheme3,
        x: 0,
        y: 0,
        level: 0,
        throttle: false
      };
      const taskCount = TerrainData_default.maximumAsynchronousTasks + 1;
      const promises = new Array();
      for (let i = 0; i < taskCount; i++) {
        const tempData = createSampleTerrainData();
        const promise = tempData.createMesh(options);
        if (defined_default(promise)) {
          promises.push(promise);
        }
      }
      expect(promises.length).toBe(taskCount);
      return Promise.all(promises);
    });
  });
  describe("interpolateHeight", function() {
    let tilingScheme3;
    let rectangle;
    beforeEach(function() {
      tilingScheme3 = new GeographicTilingScheme_default();
      rectangle = tilingScheme3.tileXYToRectangle(7, 6, 5);
    });
    it("clamps coordinates if given a position outside the mesh", function() {
      const mesh = new QuantizedMeshTerrainData_default({
        minimumHeight: 0,
        maximumHeight: 4,
        quantizedVertices: new Uint16Array([
          // order is sw nw se ne
          // u
          0,
          0,
          32767,
          32767,
          // v
          0,
          32767,
          0,
          32767,
          // heights
          32767 / 4,
          2 * 32767 / 4,
          3 * 32767 / 4,
          32767
        ]),
        indices: new Uint16Array([0, 3, 1, 0, 2, 3]),
        boundingSphere: new BoundingSphere_default(),
        horizonOcclusionPoint: new Cartesian3_default(),
        westIndices: [0, 1],
        southIndices: [0, 1],
        eastIndices: [2, 3],
        northIndices: [1, 3],
        westSkirtHeight: 1,
        southSkirtHeight: 1,
        eastSkirtHeight: 1,
        northSkirtHeight: 1,
        childTileMask: 15
      });
      expect(mesh.interpolateHeight(rectangle, 0, 0)).toBe(
        mesh.interpolateHeight(rectangle, rectangle.east, rectangle.south)
      );
    });
    it("returns a height interpolated from the correct triangle", function() {
      const mesh = new QuantizedMeshTerrainData_default({
        minimumHeight: -16384,
        maximumHeight: 16383,
        quantizedVertices: new Uint16Array([
          // order is sw nw se ne
          // u
          0,
          0,
          32767,
          32767,
          // v
          0,
          32767,
          0,
          32767,
          // heights
          16384,
          0,
          32767,
          16384
        ]),
        indices: new Uint16Array([0, 3, 1, 0, 2, 3]),
        boundingSphere: new BoundingSphere_default(),
        horizonOcclusionPoint: new Cartesian3_default(),
        westIndices: [0, 1],
        southIndices: [0, 1],
        eastIndices: [2, 3],
        northIndices: [1, 3],
        westSkirtHeight: 1,
        southSkirtHeight: 1,
        eastSkirtHeight: 1,
        northSkirtHeight: 1,
        childTileMask: 15
      });
      let longitude = rectangle.west + (rectangle.east - rectangle.west) * 0.25;
      let latitude = rectangle.south + (rectangle.north - rectangle.south) * 0.75;
      let result = mesh.interpolateHeight(rectangle, longitude, latitude);
      expect(result).toBeLessThan(0);
      longitude = rectangle.west + (rectangle.east - rectangle.west) * 0.75;
      latitude = rectangle.south + (rectangle.north - rectangle.south) * 0.25;
      result = mesh.interpolateHeight(rectangle, longitude, latitude);
      expect(result).toBeGreaterThan(0);
      longitude = rectangle.west + (rectangle.east - rectangle.west) * 0.5;
      latitude = rectangle.south + (rectangle.north - rectangle.south) * 0.5;
      result = mesh.interpolateHeight(rectangle, longitude, latitude);
      expect(result).toEqualEpsilon(0, 1e-10);
    });
  });
