describe("Core/Request", function() {
  it("sets correct properties in constructor", function() {
    const options = Object.freeze({
      url: "https://www.example.com",
      requestFunction: Promise.resolve(),
      cancelFunction: () => void 0,
      priorityFunction: () => 1,
      priority: 1,
      throttle: true,
      throttleByServer: true,
      type: RequestType_default.IMAGERY,
      serverKey: "customKey"
    });
    const request = new Request_default(options);
    expect(request.url).toBe(options.url);
    expect(request.requestFunction).toBe(options.requestFunction);
    expect(request.cancelFunction).toBe(options.cancelFunction);
    expect(request.priorityFunction).toBe(options.priorityFunction);
    expect(request.priority).toBe(options.priority);
    expect(request.throttle).toBe(options.throttle);
    expect(request.throttleByServer).toBe(options.throttleByServer);
    expect(request.type).toBe(options.type);
    expect(request.serverKey).toBe(options.serverKey);
    expect(request.state).toBe(RequestState_default.UNISSUED);
  });
  it("cancels", function() {
    const request = new Request_default();
    expect(request.cancelled).toBe(false);
    request.cancel();
    expect(request.cancelled).toBe(true);
  });
  it("cloning without options creates a request with the same properties", function() {
    const initialOptions = Object.freeze({
      url: "https://www.example.com",
      requestFunction: Promise.resolve(),
      cancelFunction: () => void 0,
      priorityFunction: () => 1,
      priority: 1,
      throttle: true,
      throttleByServer: true,
      type: RequestType_default.IMAGERY,
      serverKey: "customKey"
    });
    const request = new Request_default(initialOptions);
    const clone3 = request.clone();
    expect(clone3.url).toBe(initialOptions.url);
    expect(clone3.requestFunction).toBe(initialOptions.requestFunction);
    expect(clone3.cancelFunction).toBe(initialOptions.cancelFunction);
    expect(clone3.priorityFunction).toBe(initialOptions.priorityFunction);
    expect(clone3.priority).toBe(initialOptions.priority);
    expect(clone3.throttle).toBe(initialOptions.throttle);
    expect(clone3.throttleByServer).toBe(initialOptions.throttleByServer);
    expect(clone3.type).toBe(initialOptions.type);
    expect(clone3.serverKey).toBe(initialOptions.serverKey);
  });
  it("cloning with a result parameter updates the properties of the result", function() {
    const options1 = Object.freeze({
      url: "https://www.example.com",
      requestFunction: Promise.resolve(),
      cancelFunction: () => void 0,
      priorityFunction: () => 1,
      priority: 1,
      throttle: true,
      throttleByServer: true,
      type: RequestType_default.IMAGERY,
      serverKey: "customKey"
    });
    const options2 = Object.freeze({
      url: "http://example.com",
      requestFunction: fetch,
      cancelFunction: () => "cancelled",
      priorityFunction: () => 2,
      priority: 2,
      throttle: false,
      throttleByServer: false,
      type: RequestType_default.TERRAIN,
      serverKey: "updatedKey"
    });
    const request1 = new Request_default(options1);
    const request2 = new Request_default(options2);
    const clone3 = request2.clone(request1);
    expect(clone3.url).toBe(options2.url);
    expect(clone3.requestFunction).toBe(options2.requestFunction);
    expect(clone3.cancelFunction).toBe(options2.cancelFunction);
    expect(clone3.priorityFunction).toBe(options2.priorityFunction);
    expect(clone3.priority).toBe(options2.priority);
    expect(clone3.throttle).toBe(options2.throttle);
    expect(clone3.throttleByServer).toBe(options2.throttleByServer);
    expect(clone3.type).toBe(options2.type);
    expect(clone3.serverKey).toBe(options2.serverKey);
  });
});

// packages/engine/Specs/Core/resizeImageToNextPowerOfTwoSpec.js
describe("Core/resizeImageToNextPowerOfTwo", function() {
  const canvas = document.createElement("canvas");
  it("resizes an image so its width is a power of two", function() {
    canvas.width = 3;
    canvas.height = 2;
    const resizedImage = resizeImageToNextPowerOfTwo_default(canvas);
    expect(resizedImage.width).toBe(4);
    expect(resizedImage.height).toBe(2);
  });
  it("resizes an image so its height is a power of two", function() {
    canvas.width = 4;
    canvas.height = 3;
    const resizedImage = resizeImageToNextPowerOfTwo_default(canvas);
    expect(resizedImage.width).toBe(4);
    expect(resizedImage.height).toBe(4);
  });
  it("keeps original image size if both dimensions are already powers of two", function() {
    canvas.width = 8;
    canvas.height = 8;
    const resizedImage = resizeImageToNextPowerOfTwo_default(canvas);
    expect(resizedImage.width).toBe(8);
    expect(resizedImage.height).toBe(8);
  });
});

