describe("Core/Simon1994PlanetaryPositions", function() {
  it("computes correct sun position", function() {
    let date = new JulianDate_default(2451545, 0, TimeStandard_default.TAI);
    let sun = Simon1994PlanetaryPositions_default.computeSunPositionInEarthInertialFrame(date);
    let X = 26500268539790234e-6;
    let Y = -13275644725327325e-5;
    let Z = -57556483362533806e-6;
    expect(X).toEqualEpsilon(sun.x, Math_default.EPSILON2);
    expect(Y).toEqualEpsilon(sun.y, Math_default.EPSILON2);
    expect(Z).toEqualEpsilon(sun.z, Math_default.EPSILON2);
    date = new JulianDate_default(24564015e-1, 0, TimeStandard_default.TAI);
    sun = Simon1994PlanetaryPositions_default.computeSunPositionInEarthInertialFrame(date);
    X = 13151238894033589e-5;
    Y = 6666134266794993e-5;
    Z = 2889797560790526e-5;
    expect(X).toEqualEpsilon(sun.x, Math_default.EPSILON3);
    expect(Y).toEqualEpsilon(sun.y, Math_default.EPSILON3);
    expect(Z).toEqualEpsilon(sun.z, Math_default.EPSILON3);
    date = new JulianDate_default(2455998591667e-6, 0, TimeStandard_default.TAI);
    sun = Simon1994PlanetaryPositions_default.computeSunPositionInEarthInertialFrame(date);
    X = 14710998995619534e-5;
    Y = -1959999688121758e-5;
    Z = -8497578102769646e-6;
    expect(X).toEqualEpsilon(sun.x, Math_default.EPSILON3);
    expect(Y).toEqualEpsilon(sun.y, Math_default.EPSILON3);
    expect(Z).toEqualEpsilon(sun.z, Math_default.EPSILON3);
  });
  it("computes correct moon position", function() {
    let date = new JulianDate_default(2451545, 0, TimeStandard_default.TAI);
    let moon = Simon1994PlanetaryPositions_default.computeMoonPositionInEarthInertialFrame(date);
    let X = -29163241061232185e-8;
    let Y = -2665221463682163e-7;
    let Z = -7599451808104315e-8;
    expect(X).toEqualEpsilon(moon.x, Math_default.EPSILON4);
    expect(Y).toEqualEpsilon(moon.y, Math_default.EPSILON4);
    expect(Z).toEqualEpsilon(moon.z, Math_default.EPSILON4);
    date = new JulianDate_default(24564015e-1, 0, TimeStandard_default.TAI);
    moon = Simon1994PlanetaryPositions_default.computeMoonPositionInEarthInertialFrame(date);
    X = -2237929744736526e-7;
    Y = 3157724353449064e-7;
    Z = 9791301123611277e-8;
    expect(X).toEqualEpsilon(moon.x, Math_default.EPSILON4);
    expect(Y).toEqualEpsilon(moon.y, Math_default.EPSILON4);
    expect(Z).toEqualEpsilon(moon.z, Math_default.EPSILON4);
    date = new JulianDate_default(2455998591667e-6, 0, TimeStandard_default.TAI);
    moon = Simon1994PlanetaryPositions_default.computeMoonPositionInEarthInertialFrame(date);
    X = -26842611700202647e-8;
    Y = -22046886173998192e-8;
    Z = -11067016458446842e-8;
    expect(X).toEqualEpsilon(moon.x, Math_default.EPSILON4);
    expect(Y).toEqualEpsilon(moon.y, Math_default.EPSILON4);
    expect(Z).toEqualEpsilon(moon.z, Math_default.EPSILON4);
  });
  it("has the sun rising in the east and setting in the west", function() {
    let transformMatrix2 = new Matrix3_default();
    const timesOfDay = [];
    let i;
    for (i = 1; i < 25; i++) {
      const date = /* @__PURE__ */ new Date("July 6, 2011");
      date.setUTCHours(i, 0, 0, 0);
      timesOfDay.push(JulianDate_default.fromDate(date));
    }
    const angles = [];
    for (i = 0; i < 24; i++) {
      transformMatrix2 = CelestialFrameTransforms_default.computeIcrfToCentralBodyFixedMatrix(
        timesOfDay[i],
        transformMatrix2
      );
      const position = Simon1994PlanetaryPositions_default.computeSunPositionInEarthInertialFrame(
        timesOfDay[i]
      );
      Matrix3_default.multiplyByVector(transformMatrix2, position, position);
      angles.push(
        Math_default.convertLongitudeRange(Math.atan2(position.y, position.x))
      );
    }
    for (i = 1; i < 24; i++) {
      expect(angles[i]).toBeLessThan(angles[i - 1]);
    }
  });
  it("works without a time", function() {
    Simon1994PlanetaryPositions_default.computeSunPositionInEarthInertialFrame(void 0);
  });
});

