// packages/engine/Specs/Core/VideoSynchronizerSpec.js
describe("Core/VideoSynchronizer", function() {
  function loadVideo() {
    const element = document.createElement("video");
    let source = document.createElement("source");
    source.setAttribute("src", "Data/Videos/big-buck-bunny-trailer-small.webm");
    source.setAttribute("type", "video/webm");
    element.appendChild(source);
    source = document.createElement("source");
    source.setAttribute("src", "Data/Videos/big-buck-bunny-trailer-small.mp4");
    source.setAttribute("type", "video/mp4");
    element.appendChild(source);
    source = document.createElement("source");
    source.setAttribute("src", "Data/Videos/big-buck-bunny-trailer-small.mov");
    source.setAttribute("type", "video/quicktime");
    element.appendChild(source);
    return element;
  }
  it("Can default construct", function() {
    const videoSynchronizer = new VideoSynchronizer_default();
    expect(videoSynchronizer.clock).not.toBeDefined();
    expect(videoSynchronizer.element).not.toBeDefined();
    expect(videoSynchronizer.epoch).toBe(Iso8601_default.MINIMUM_VALUE);
    expect(videoSynchronizer.tolerance).toBe(1);
    expect(videoSynchronizer.isDestroyed()).toBe(false);
    expect(videoSynchronizer.destroy()).not.toBeDefined();
    expect(videoSynchronizer.isDestroyed()).toBe(true);
  });
  it("Can construct with options", function() {
    const clock = new Clock_default();
    const element = document.createElement("video");
    const epoch2 = new JulianDate_default();
    const tolerance = 0.15;
    const videoSynchronizer = new VideoSynchronizer_default({
      clock,
      element,
      epoch: epoch2,
      tolerance
    });
    expect(videoSynchronizer.clock).toBe(clock);
    expect(videoSynchronizer.element).toBe(element);
    expect(videoSynchronizer.epoch).toBe(epoch2);
    expect(videoSynchronizer.tolerance).toBe(tolerance);
    expect(videoSynchronizer.isDestroyed()).toBe(false);
    expect(videoSynchronizer.destroy()).not.toBeDefined();
    expect(videoSynchronizer.isDestroyed()).toBe(true);
  });
  it("Syncs time when looping", function() {
    const epoch2 = JulianDate_default.fromIso8601("2015-11-01T00:00:00Z");
    const clock = new Clock_default();
    clock.shouldAnimate = false;
    clock.currentTime = epoch2.clone();
    const element = loadVideo();
    element.loop = true;
    const videoSynchronizer = new VideoSynchronizer_default({
      clock,
      element,
      epoch: epoch2
    });
    return pollToPromise_default(function() {
      clock.tick();
      return element.currentTime === 0;
    }).then(function() {
      clock.currentTime = JulianDate_default.addSeconds(epoch2, 10, clock.currentTime);
      return pollToPromise_default(function() {
        clock.tick();
        return element.currentTime === 10;
      });
    }).then(function() {
      clock.currentTime = JulianDate_default.addSeconds(epoch2, 60, clock.currentTime);
      return pollToPromise_default(function() {
        clock.tick();
        return Math_default.equalsEpsilon(
          element.currentTime,
          60 - element.duration,
          Math_default.EPSILON3
        );
      });
    }).then(function() {
      clock.currentTime = JulianDate_default.addSeconds(epoch2, -1, clock.currentTime);
      return pollToPromise_default(function() {
        clock.tick();
        return Math_default.equalsEpsilon(
          element.currentTime,
          element.duration - 1,
          Math_default.EPSILON1
        );
      });
    }).then(function() {
      videoSynchronizer.destroy();
    });
  });
  it("Syncs time when not looping", function() {
    const epoch2 = JulianDate_default.fromIso8601("2015-11-01T00:00:00Z");
    const clock = new Clock_default();
    clock.shouldAnimate = false;
    clock.currentTime = epoch2.clone();
    const element = loadVideo();
    const videoSynchronizer = new VideoSynchronizer_default({
      clock,
      element,
      epoch: epoch2
    });
    return pollToPromise_default(function() {
      clock.tick();
      return element.currentTime === 0;
    }).then(function() {
      clock.currentTime = JulianDate_default.addSeconds(epoch2, 10, clock.currentTime);
      return pollToPromise_default(function() {
        clock.tick();
        return element.currentTime === 10;
      });
    }).then(function() {
      clock.currentTime = JulianDate_default.addSeconds(epoch2, 60, clock.currentTime);
      return pollToPromise_default(function() {
        clock.tick();
        return Math_default.equalsEpsilon(
          element.currentTime,
          element.duration,
          Math_default.EPSILON3
        );
      });
    }).then(function() {
      clock.currentTime = JulianDate_default.addSeconds(epoch2, -1, clock.currentTime);
      return pollToPromise_default(function() {
        clock.tick();
        return element.currentTime === 0;
      });
    }).then(function() {
      videoSynchronizer.destroy();
    });
  });
  it("Plays/pauses video based on clock", function() {
    const epoch2 = JulianDate_default.fromIso8601("2015-11-01T00:00:00Z");
    const clock = new Clock_default();
    const element = jasmine.createSpyObj("MockVideoElement", [
      "addEventListener",
      "removeEventListener",
      "play",
      "pause"
    ]);
    element.paused = false;
    element.play.and.callFake(function() {
      this.paused = false;
    });
    element.pause.and.callFake(function() {
      this.paused = true;
    });
    const videoSynchronizer = new VideoSynchronizer_default({
      clock,
      element,
      epoch: epoch2
    });
    clock.shouldAnimate = false;
    clock.tick();
    expect(element.pause.calls.count()).toEqual(1);
    clock.shouldAnimate = true;
    clock.tick();
    expect(element.play.calls.count()).toEqual(1);
    clock.shouldAnimate = false;
    clock.tick();
    expect(element.pause.calls.count()).toEqual(2);
    videoSynchronizer.destroy();
  });
});

// packages/engine/Specs/Core/VRTheWorldTerrainProviderSpec.js
describe("Core/VRTheWorldTerrainProvider", function() {
  const imageUrl = "Data/Images/Red16x16.png";
  function patchXHRLoad() {
    Resource_default._Implementations.loadWithXhr = function(url2, responseType, method, data, headers, deferred, overrideMimeType) {
      if (url2 === imageUrl) {
        Resource_default._DefaultImplementations.loadWithXhr(
          url2,
          responseType,
          method,
          data,
          headers,
          deferred,
          overrideMimeType
        );
        return;
      }
      setTimeout(function() {
        const parser3 = new DOMParser();
        const xmlString = '<TileMap version="1.0.0" tilemapservice="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/"><!--  Additional data: tms_type is default  --><Title>Hawaii World elev</Title><Abstract>layer to make cesium work right</Abstract><SRS>EPSG:4326</SRS><BoundingBox minx="-180.000000" miny="-90.000000" maxx="180.000000" maxy="90.000000"/><Origin x="-180.000000" y="-90.000000"/><TileFormat width="32" height="32" mime-type="image/tif" extension="tif"/><TileSets><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/0" units-per-pixel="5.62500000000000000000" order="0"/><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/1" units-per-pixel="2.81250000000000000000" order="1"/><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/2" units-per-pixel="1.40625000000000000000" order="2"/><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/3" units-per-pixel="0.70312500000000000000" order="3"/></TileSets><DataExtents><DataExtent minx="-180.000000" miny="-90.000000" maxx="180.000000" maxy="90.000000" minlevel="0" maxlevel="9"/><DataExtent minx="24.999584" miny="-0.000417" maxx="30.000417" maxy="5.000417" minlevel="0" maxlevel="13"/></DataExtents></TileMap>';
        const xml2 = parser3.parseFromString(xmlString, "text/xml");
        deferred.resolve(xml2);
      }, 1);
    };
  }
  let originalRequestersPerServer;
  beforeEach(function() {
    RequestScheduler_default.clearForSpecs();
    originalRequestersPerServer = RequestScheduler_default.maximumRequestsPerServer;
  });
  afterEach(function() {
    Resource_default._Implementations.createImage = Resource_default._DefaultImplementations.createImage;
    Resource_default._Implementations.loadWithXhr = Resource_default._DefaultImplementations.loadWithXhr;
    RequestScheduler_default.maximumRequestsPerServer = originalRequestersPerServer;
  });
  function createRequest() {
    return new Request_default({
      throttleByServer: true
    });
  }
  it("conforms to TerrainProvider interface", function() {
    expect(VRTheWorldTerrainProvider_default).toConformToInterface(TerrainProvider_default);
  });
  it("fromUrl rejects without url", async function() {
    await expectAsync(
      VRTheWorldTerrainProvider_default.fromUrl()
    ).toBeRejectedWithDeveloperError(
      "url is required, actual value was undefined"
    );
  });
  it("fromUrl resolves to new VRTheWorldTerrainProvider", async function() {
    patchXHRLoad();
    const provider = await VRTheWorldTerrainProvider_default.fromUrl("made/up/url");
    expect(provider).toBeInstanceOf(VRTheWorldTerrainProvider_default);
  });
  it("fromUrl with Resource resolves to new VRTheWorldTerrainProvider", async function() {
    patchXHRLoad();
    const resource = new Resource_default({
      url: "made/up/url"
    });
    const provider = await VRTheWorldTerrainProvider_default.fromUrl(resource);
    expect(provider).toBeInstanceOf(VRTheWorldTerrainProvider_default);
  });
  it("has error event", async function() {
    patchXHRLoad();
    const provider = await VRTheWorldTerrainProvider_default.fromUrl("made/up/url");
    expect(provider.errorEvent).toBeDefined();
    expect(provider.errorEvent).toBe(provider.errorEvent);
  });
  it("returns reasonable geometric error for various levels", async function() {
    patchXHRLoad();
    const provider = await VRTheWorldTerrainProvider_default.fromUrl("made/up/url");
    expect(provider.getLevelMaximumGeometricError(0)).toBeGreaterThan(0);
    expect(provider.getLevelMaximumGeometricError(0)).toEqualEpsilon(
      provider.getLevelMaximumGeometricError(1) * 2,
      Math_default.EPSILON10
    );
    expect(provider.getLevelMaximumGeometricError(1)).toEqualEpsilon(
      provider.getLevelMaximumGeometricError(2) * 2,
      Math_default.EPSILON10
    );
  });
  it("credit is undefined if credit option is not provided", async function() {
    patchXHRLoad();
    const provider = await VRTheWorldTerrainProvider_default.fromUrl("made/up/url");
    expect(provider.credit).toBeUndefined();
  });
  it("credit is defined if credit option is provided", async function() {
    patchXHRLoad();
    const provider = await VRTheWorldTerrainProvider_default.fromUrl("made/up/url", {
      credit: "thanks to our awesome made up contributors!"
    });
    expect(provider.credit).toBeDefined();
  });
  it("does not have a water mask", async function() {
    patchXHRLoad();
    const provider = await VRTheWorldTerrainProvider_default.fromUrl("made/up/url");
    expect(provider.hasWaterMask).toBe(false);
  });
  it("fromUrl throws if the SRS is not supported", async function() {
    patchXHRLoad();
    Resource_default._Implementations.loadWithXhr = function(url2, responseType, method, data, headers, deferred, overrideMimeType) {
      setTimeout(function() {
        const parser3 = new DOMParser();
        const xmlString = '<TileMap version="1.0.0" tilemapservice="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/"><!--  Additional data: tms_type is default  --><Title>Hawaii World elev</Title><Abstract>layer to make cesium work right</Abstract><SRS>EPSG:foo</SRS><BoundingBox minx="-180.000000" miny="-90.000000" maxx="180.000000" maxy="90.000000"/><Origin x="-180.000000" y="-90.000000"/><TileFormat width="32" height="32" mime-type="image/tif" extension="tif"/><TileSets><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/0" units-per-pixel="5.62500000000000000000" order="0"/><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/1" units-per-pixel="2.81250000000000000000" order="1"/><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/2" units-per-pixel="1.40625000000000000000" order="2"/><TileSet href="http://www.vr-theworld.com/vr-theworld/tiles/1.0.0/73/3" units-per-pixel="0.70312500000000000000" order="3"/></TileSets><DataExtents><DataExtent minx="-180.000000" miny="-90.000000" maxx="180.000000" maxy="90.000000" minlevel="0" maxlevel="9"/><DataExtent minx="24.999584" miny="-0.000417" maxx="30.000417" maxy="5.000417" minlevel="0" maxlevel="13"/></DataExtents></TileMap>';
        const xml2 = parser3.parseFromString(xmlString, "text/xml");
        deferred.resolve(xml2);
      }, 1);
    };
    await expectAsync(
      VRTheWorldTerrainProvider_default.fromUrl("made/up/url")
    ).toBeRejectedWithError(
      RuntimeError_default,
      "An error occurred while accessing made/up/url: SRS EPSG:foo is not supported"
    );
  });
  describe("requestTileGeometry", function() {
    it("provides HeightmapTerrainData", async function() {
      patchXHRLoad();
      const baseUrl2 = "made/up/url";
      Resource_default._Implementations.createImage = function(request, crossOrigin, deferred) {
        expect(request.url.indexOf(".tif?cesium=true")).toBeGreaterThanOrEqual(
          0
        );
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: imageUrl }),
          crossOrigin,
          deferred
        );
      };
      const terrainProvider = await VRTheWorldTerrainProvider_default.fromUrl(baseUrl2);
      expect(terrainProvider.tilingScheme).toBeInstanceOf(
        GeographicTilingScheme_default
      );
      const loadedData = await terrainProvider.requestTileGeometry(0, 0, 0);
      expect(loadedData).toBeInstanceOf(HeightmapTerrainData_default);
    });
    it("returns undefined if too many requests are already in progress", async function() {
      patchXHRLoad();
      const baseUrl2 = "made/up/url";
      const terrainProvider = await VRTheWorldTerrainProvider_default.fromUrl(baseUrl2);
      RequestScheduler_default.maximumRequestsPerServer = 0;
      expect(
        terrainProvider.requestTileGeometry(0, 0, 0, createRequest())
      ).toBeUndefined();
    });
  });
});

// packages/engine/Specs/Core/WebMercatorTilingSchemeSpec.js
describe("Core/WebMercatorTilingScheme", function() {
  let tilingScheme3;
  beforeEach(function() {
    tilingScheme3 = new WebMercatorTilingScheme_default();
  });
  it("conforms to TilingScheme interface.", function() {
    expect(WebMercatorTilingScheme_default).toConformToInterface(TilingScheme_default);
  });
  it("default constructing uses WGS84 ellipsoid", function() {
    const tilingScheme4 = new WebMercatorTilingScheme_default();
    expect(tilingScheme4.ellipsoid).toEqual(Ellipsoid_default.WGS84);
  });
  it("uses specified ellipsoid", function() {
    const tilingScheme4 = new WebMercatorTilingScheme_default({
      ellipsoid: Ellipsoid_default.UNIT_SPHERE
    });
    expect(tilingScheme4.ellipsoid).toEqual(Ellipsoid_default.UNIT_SPHERE);
  });
  describe("Conversions from tile indices to cartographic rectangles", function() {
    it("tileXYToRectangle returns full rectangle for single root tile.", function() {
      const rectangle = tilingScheme3.tileXYToRectangle(0, 0, 0);
      const tilingSchemeRectangle = tilingScheme3.rectangle;
      expect(rectangle.west).toEqualEpsilon(
        tilingSchemeRectangle.west,
        Math_default.EPSILON10
      );
      expect(rectangle.south).toEqualEpsilon(
        tilingSchemeRectangle.south,
        Math_default.EPSILON10
      );
      expect(rectangle.east).toEqualEpsilon(
        tilingSchemeRectangle.east,
        Math_default.EPSILON10
      );
      expect(rectangle.north).toEqualEpsilon(
        tilingSchemeRectangle.north,
        Math_default.EPSILON10
      );
    });
    it("tileXYToRectangle uses result parameter if provided", function() {
      const tilingSchemeRectangle = tilingScheme3.rectangle;
      const result = new Rectangle_default(0, 0, 0);
      const rectangle = tilingScheme3.tileXYToRectangle(0, 0, 0, result);
      expect(result).toEqual(rectangle);
      expect(rectangle.west).toEqualEpsilon(
        tilingSchemeRectangle.west,
        Math_default.EPSILON10
      );
      expect(rectangle.south).toEqualEpsilon(
        tilingSchemeRectangle.south,
        Math_default.EPSILON10
      );
      expect(rectangle.east).toEqualEpsilon(
        tilingSchemeRectangle.east,
        Math_default.EPSILON10
      );
      expect(rectangle.north).toEqualEpsilon(
        tilingSchemeRectangle.north,
        Math_default.EPSILON10
      );
    });
    it("tiles are numbered from the northwest corner.", function() {
      const northwest = tilingScheme3.tileXYToRectangle(0, 0, 1);
      const northeast = tilingScheme3.tileXYToRectangle(1, 0, 1);
      const southeast = tilingScheme3.tileXYToRectangle(1, 1, 1);
      const southwest = tilingScheme3.tileXYToRectangle(0, 1, 1);
      expect(northeast.north).toEqual(northwest.north);
      expect(northeast.south).toEqual(northwest.south);
      expect(southeast.north).toEqual(southwest.north);
      expect(southeast.south).toEqual(southwest.south);
      expect(northwest.west).toEqual(southwest.west);
      expect(northwest.east).toEqual(southwest.east);
      expect(northeast.west).toEqual(southeast.west);
      expect(northeast.east).toEqual(southeast.east);
      expect(northeast.north).toBeGreaterThan(southeast.north);
      expect(northeast.south).toBeGreaterThan(southeast.south);
      expect(northwest.north).toBeGreaterThan(southwest.north);
      expect(northwest.south).toBeGreaterThan(southwest.south);
      expect(northeast.east).toBeGreaterThan(northwest.east);
      expect(northeast.west).toBeGreaterThan(northwest.west);
      expect(southeast.east).toBeGreaterThan(southwest.east);
      expect(southeast.west).toBeGreaterThan(southwest.west);
    });
    it("adjacent tiles have overlapping coordinates", function() {
      const northwest = tilingScheme3.tileXYToRectangle(0, 0, 1);
      const northeast = tilingScheme3.tileXYToRectangle(1, 0, 1);
      const southeast = tilingScheme3.tileXYToRectangle(1, 1, 1);
      const southwest = tilingScheme3.tileXYToRectangle(0, 1, 1);
      expect(northeast.south).toEqualEpsilon(
        southeast.north,
        Math_default.EPSILON15
      );
      expect(northwest.south).toEqualEpsilon(
        southwest.north,
        Math_default.EPSILON15
      );
      expect(northeast.west).toEqualEpsilon(
        northwest.east,
        Math_default.EPSILON15
      );
      expect(southeast.west).toEqualEpsilon(
        southwest.east,
        Math_default.EPSILON15
      );
    });
  });
  describe("Conversions from cartographic positions to tile indices", function() {
    it("calculates correct tile indices for 4 corners at level 0", function() {
      let coordinates;
      const tilingSchemeRectangle = tilingScheme3.rectangle;
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.southwest(tilingSchemeRectangle),
        0
      );
      expect(coordinates.x).toEqual(0);
      expect(coordinates.y).toEqual(0);
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.northwest(tilingSchemeRectangle),
        0
      );
      expect(coordinates.x).toEqual(0);
      expect(coordinates.y).toEqual(0);
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.northeast(tilingSchemeRectangle),
        0
      );
      expect(coordinates.x).toEqual(0);
      expect(coordinates.y).toEqual(0);
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.southeast(tilingSchemeRectangle),
        0
      );
      expect(coordinates.x).toEqual(0);
      expect(coordinates.y).toEqual(0);
    });
    it("calculates correct tile indices for 4 corners at level 1", function() {
      let coordinates;
      const tilingSchemeRectangle = tilingScheme3.rectangle;
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.southwest(tilingSchemeRectangle),
        1
      );
      expect(coordinates.x).toEqual(0);
      expect(coordinates.y).toEqual(1);
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.northwest(tilingSchemeRectangle),
        1
      );
      expect(coordinates.x).toEqual(0);
      expect(coordinates.y).toEqual(0);
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.northeast(tilingSchemeRectangle),
        1
      );
      expect(coordinates.x).toEqual(1);
      expect(coordinates.y).toEqual(0);
      coordinates = tilingScheme3.positionToTileXY(
        Rectangle_default.southeast(tilingSchemeRectangle),
        1
      );
      expect(coordinates.x).toEqual(1);
      expect(coordinates.y).toEqual(1);
    });
    it("calculates correct tile indices for the center at level 1", function() {
      const coordinates = tilingScheme3.positionToTileXY(
        new Cartographic_default(0, 0),
        1
      );
      expect(coordinates.x).toEqual(1);
      expect(coordinates.y).toEqual(1);
    });
    it("calculates correct tile indices for the center at level 2", function() {
      const coordinates = tilingScheme3.positionToTileXY(
        new Cartographic_default(0, 0),
        2
      );
      expect(coordinates.x).toEqual(2);
      expect(coordinates.y).toEqual(2);
    });
    it("calculates correct tile indices around the center at level 2", function() {
      let coordinates;
      coordinates = tilingScheme3.positionToTileXY(
        new Cartographic_default(-0.05, -0.05),
        2
      );
      expect(coordinates.x).toEqual(1);
      expect(coordinates.y).toEqual(2);
      coordinates = tilingScheme3.positionToTileXY(
        new Cartographic_default(-0.05, 0.05),
        2
      );
      expect(coordinates.x).toEqual(1);
      expect(coordinates.y).toEqual(1);
      coordinates = tilingScheme3.positionToTileXY(
        new Cartographic_default(0.05, 0.05),
        2
      );
      expect(coordinates.x).toEqual(2);
      expect(coordinates.y).toEqual(1);
      coordinates = tilingScheme3.positionToTileXY(
        new Cartographic_default(0.05, -0.05),
        2
      );
      expect(coordinates.x).toEqual(2);
      expect(coordinates.y).toEqual(2);
    });
  });
  it("uses a WebMercatorProjection", function() {
    const tilingScheme4 = new WebMercatorTilingScheme_default();
    expect(tilingScheme4.projection).toBeInstanceOf(WebMercatorProjection_default);
  });
  describe("rectangleToNativeRectangle", function() {
    it("converts radians to web mercator meters", function() {
      const tilingScheme4 = new WebMercatorTilingScheme_default();
      const rectangleInRadians = new Rectangle_default(0.1, 0.2, 0.3, 0.4);
      const nativeRectangle = tilingScheme4.rectangleToNativeRectangle(rectangleInRadians);
      const projection = new WebMercatorProjection_default();
      const expectedSouthwest = projection.project(
        Rectangle_default.southwest(rectangleInRadians)
      );
      const expectedNortheast = projection.project(
        Rectangle_default.northeast(rectangleInRadians)
      );
      expect(nativeRectangle.west).toEqualEpsilon(
        expectedSouthwest.x,
        Math_default.EPSILON13
      );
      expect(nativeRectangle.south).toEqualEpsilon(
        expectedSouthwest.y,
        Math_default.EPSILON13
      );
      expect(nativeRectangle.east).toEqualEpsilon(
        expectedNortheast.x,
        Math_default.EPSILON13
      );
      expect(nativeRectangle.north).toEqualEpsilon(
        expectedNortheast.y,
        Math_default.EPSILON13
      );
    });
    it("uses result parameter if provided", function() {
      const tilingScheme4 = new WebMercatorTilingScheme_default();
      const rectangleInRadians = new Rectangle_default(0.1, 0.2, 0.3, 0.4);
      const projection = new WebMercatorProjection_default();
      const expectedSouthwest = projection.project(
        Rectangle_default.southwest(rectangleInRadians)
      );
      const expectedNortheast = projection.project(
        Rectangle_default.northeast(rectangleInRadians)
      );
      const resultRectangle = new Rectangle_default(0, 0, 0, 0);
      const outputRectangle = tilingScheme4.rectangleToNativeRectangle(
        rectangleInRadians,
        resultRectangle
      );
      expect(outputRectangle).toEqual(resultRectangle);
      expect(resultRectangle.west).toEqualEpsilon(
        expectedSouthwest.x,
        Math_default.EPSILON13
      );
      expect(resultRectangle.south).toEqualEpsilon(
        expectedSouthwest.y,
        Math_default.EPSILON13
      );
      expect(resultRectangle.east).toEqualEpsilon(
        expectedNortheast.x,
        Math_default.EPSILON13
      );
      expect(resultRectangle.north).toEqualEpsilon(
        expectedNortheast.y,
        Math_default.EPSILON13
      );
    });
  });
  describe("positionToTileXY", function() {
    it("returns undefined when outside rectangle", function() {
      const projection = new WebMercatorProjection_default();
      const rectangleInRadians = new Rectangle_default(0.1, 0.2, 0.3, 0.4);
      const tilingScheme4 = new WebMercatorTilingScheme_default({
        rectangleSouthwestInMeters: projection.project(
          Rectangle_default.southwest(rectangleInRadians)
        ),
        rectangleNortheastInMeters: projection.project(
          Rectangle_default.northeast(rectangleInRadians)
        )
      });
      const tooFarWest = new Cartographic_default(0.05, 0.3);
      expect(tilingScheme4.positionToTileXY(tooFarWest, 0)).toBeUndefined();
      const tooFarSouth = new Cartographic_default(0.2, 0.1);
      expect(tilingScheme4.positionToTileXY(tooFarSouth, 0)).toBeUndefined();
      const tooFarEast = new Cartographic_default(0.4, 0.3);
      expect(tilingScheme4.positionToTileXY(tooFarEast, 0)).toBeUndefined();
      const tooFarNorth = new Cartographic_default(0.2, 0.5);
      expect(tilingScheme4.positionToTileXY(tooFarNorth, 0)).toBeUndefined();
    });
    it("returns correct tile for position in center of tile", function() {
      const tilingScheme4 = new WebMercatorTilingScheme_default();
      const centerOfSouthwesternChild = new Cartographic_default(
        -Math.PI / 2,
        -Math.PI / 4
      );
      expect(
        tilingScheme4.positionToTileXY(centerOfSouthwesternChild, 1)
      ).toEqual(new Cartesian2_default(0, 1));
      const centerOfNortheasternChild = new Cartographic_default(
        Math.PI / 2,
        Math.PI / 4
      );
      expect(
        tilingScheme4.positionToTileXY(centerOfNortheasternChild, 1)
      ).toEqual(new Cartesian2_default(1, 0));
    });
    it("returns Southeast tile when on the boundary between tiles", function() {
      const tilingScheme4 = new WebMercatorTilingScheme_default();
      const centerOfMap = new Cartographic_default(0, 0);
      expect(tilingScheme4.positionToTileXY(centerOfMap, 1)).toEqual(
        new Cartesian2_default(1, 1)
      );
    });
    it("does not return tile outside valid range", function() {
      const tilingScheme4 = new WebMercatorTilingScheme_default();
      const southeastCorner = Rectangle_default.southeast(tilingScheme4.rectangle);
      expect(tilingScheme4.positionToTileXY(southeastCorner, 1)).toEqual(
        new Cartesian2_default(1, 1)
      );
    });
    it("uses result parameter if supplied", function() {
      const tilingScheme4 = new WebMercatorTilingScheme_default();
      const centerOfNortheasternChild = new Cartographic_default(
        Math.PI / 2,
        Math.PI / 4
      );
      const resultParameter = new Cartesian2_default(0, 0);
      const returnedResult = tilingScheme4.positionToTileXY(
        centerOfNortheasternChild,
        1,
        resultParameter
      );
      expect(resultParameter).toEqual(returnedResult);
      expect(resultParameter).toEqual(new Cartesian2_default(1, 0));
    });
  });
});

// packages/engine/Specs/Core/WireframeIndexGeneratorSpec.js
describe("Core/WireframeIndexGenerator", function() {
  const createWireframeIndices = WireframeIndexGenerator_default.createWireframeIndices;
  const getWireframeIndicesCount = WireframeIndexGenerator_default.getWireframeIndicesCount;
  it("createWireframeIndices returns undefined for non-triangles", function() {
    let result = createWireframeIndices(PrimitiveType_default.POINTS, 6);
    expect(result).toBeUndefined();
    result = createWireframeIndices(PrimitiveType_default.LINES, 6);
    expect(result).toBeUndefined();
    result = createWireframeIndices(PrimitiveType_default.LINE_STRIP, 6);
    expect(result).toBeUndefined();
    result = createWireframeIndices(PrimitiveType_default.LINE_LOOP, 6);
    expect(result).toBeUndefined();
  });
  it("createWireframeIndices works for triangles", function() {
    const expected = [
      0,
      1,
      1,
      2,
      2,
      0,
      // First triangle
      3,
      4,
      4,
      5,
      5,
      3
    ];
    const result = createWireframeIndices(PrimitiveType_default.TRIANGLES, 6);
    expect(result).toEqual(expected);
  });
  it("createWireframeIndices works for triangles from indices", function() {
    const indices = [1, 0, 2, 4, 5, 3];
    const expected = [
      1,
      0,
      0,
      2,
      2,
      1,
      // First triangle
      4,
      5,
      5,
      3,
      3,
      4
    ];
    const result = createWireframeIndices(PrimitiveType_default.TRIANGLES, 6, indices);
    expect(result).toEqual(expected);
  });
  it("createWireframeIndices works for triangle strip", function() {
    const expected = [
      0,
      1,
      // First edge of the strip
      1,
      2,
      2,
      0,
      // The next two edges of the first triangle
      2,
      3,
      3,
      1,
      // The next two edges of the third triangle
      3,
      4,
      4,
      2,
      // And so on...
      4,
      5,
      5,
      3
    ];
    const result = createWireframeIndices(PrimitiveType_default.TRIANGLE_STRIP, 6);
    expect(result).toEqual(expected);
  });
  it("createWireframeIndices works for triangle strip from indices", function() {
    const indices = [1, 0, 2, 4, 5, 3];
    const expected = [
      1,
      0,
      // First edge of the strip
      0,
      2,
      2,
      1,
      // The next two edges of the first triangle
      2,
      4,
      4,
      0,
      // The next two edges of the third triangle
      4,
      5,
      5,
      2,
      // And so on...
      5,
      3,
      3,
      4
    ];
    const result = createWireframeIndices(
      PrimitiveType_default.TRIANGLE_STRIP,
      6,
      indices
    );
    expect(result).toEqual(expected);
  });
  it("createWireframeIndices works for triangle fan", function() {
    const expected = [
      0,
      1,
      // First edge of the fan
      1,
      2,
      2,
      0,
      // The next two edges of the first triangle
      2,
      3,
      3,
      0,
      // The next two edges of the third triangle
      3,
      4,
      4,
      0,
      // And so on...
      4,
      5,
      5,
      0
    ];
    const result = createWireframeIndices(PrimitiveType_default.TRIANGLE_FAN, 6);
    expect(result).toEqual(expected);
  });
  it("createWireframeIndices works for triangle fan from indices", function() {
    const indices = [1, 0, 2, 4, 5, 3];
    const expected = [
      1,
      0,
      // First edge of the fan
      0,
      2,
      2,
      1,
      // The next two edges of the first triangle
      2,
      4,
      4,
      1,
      // The next two edges of the third triangle
      4,
      5,
      5,
      1,
      // And so on...
      5,
      3,
      3,
      1
    ];
    const result = createWireframeIndices(
      PrimitiveType_default.TRIANGLE_FAN,
      6,
      indices
    );
    expect(result).toEqual(expected);
  });
  it("getWireframeIndicesCount returns original count for non-triangles", function() {
    const originalCount = 6;
    let result = getWireframeIndicesCount(PrimitiveType_default.POINTS, originalCount);
    expect(result).toEqual(originalCount);
    result = getWireframeIndicesCount(PrimitiveType_default.LINES, originalCount);
    expect(result).toEqual(originalCount);
    result = getWireframeIndicesCount(PrimitiveType_default.LINE_STRIP, originalCount);
    expect(result).toEqual(originalCount);
    result = getWireframeIndicesCount(PrimitiveType_default.LINE_LOOP, originalCount);
    expect(result).toEqual(originalCount);
  });
  it("getWireframeIndicesCount works", function() {
    const originalCount = 6;
    let result = getWireframeIndicesCount(
      PrimitiveType_default.TRIANGLES,
      originalCount
    );
    expect(result).toEqual(12);
    result = getWireframeIndicesCount(
      PrimitiveType_default.TRIANGLE_STRIP,
      originalCount
    );
    expect(result).toEqual(18);
    result = getWireframeIndicesCount(
      PrimitiveType_default.TRIANGLE_FAN,
      originalCount
    );
    expect(result).toEqual(18);
  });
});

// packages/engine/Specs/Core/writeTextToCanvasSpec.js
describe("Core/writeTextToCanvas", function() {
  it("returns undefined when text is blank", function() {
    const canvas = writeTextToCanvas_default("");
    expect(canvas).toBeUndefined();
  });
  it("throws when text is undefined", function() {
    expect(function() {
      writeTextToCanvas_default();
    }).toThrowDeveloperError();
  });
  it("sizes the canvas to fit the text", function() {
    const canvas1 = writeTextToCanvas_default("m");
    const canvas2 = writeTextToCanvas_default("mm");
    expect(canvas1.width).not.toEqual(canvas2.width);
    expect(canvas1.height).toEqual(canvas2.height);
  });
  it("allows the text to be either stroked or filled", function() {
    const row = 20;
    function getColorChangeCount(canvas) {
      let colorChangeCount = 0;
      const context = canvas.getContext("2d");
      let pixel = context.getImageData(0, row, 1, 1).data;
      let lastRed = pixel[0];
      let lastGreen = pixel[1];
      let lastBlue = pixel[2];
      for (let column = 0; column < canvas.width; ++column) {
        pixel = context.getImageData(column, row, 1, 1).data;
        let red = pixel[0];
        let green = pixel[1];
        let blue = pixel[2];
        if (red > 0 && red !== 255) {
          red = 255;
        }
        if (green > 0 && green !== 255) {
          green = 255;
        }
        if (blue > 0 && blue !== 255) {
          blue = 255;
        }
        if (red !== lastRed || green !== lastGreen || blue !== lastBlue) {
          ++colorChangeCount;
        }
        lastRed = red;
        lastGreen = green;
        lastBlue = blue;
      }
      return colorChangeCount;
    }
    const canvas1 = writeTextToCanvas_default("I", {
      font: '90px "Open Sans"',
      fill: true,
      fillColor: Color_default.RED,
      stroke: false
    });
    let count = getColorChangeCount(canvas1);
    expect(count === 1 || count === 2).toEqual(true);
    const canvas2 = writeTextToCanvas_default("I", {
      font: '90px "Open Sans"',
      fill: false,
      stroke: true,
      strokeColor: Color_default.BLUE
    });
    count = getColorChangeCount(canvas2);
    expect(count === 3 || count === 4).toEqual(true);
  });
  it("background color defaults to transparent", function() {
    const canvas = writeTextToCanvas_default("a", {
      font: '90px "Open Sans"'
    });
    const context = canvas.getContext("2d");
    const pixel = context.getImageData(0, 0, 1, 1).data;
    expect(pixel).toEqual([0, 0, 0, 0]);
  });
  it("background can be set", function() {
    const canvas = writeTextToCanvas_default("a", {
      font: '90px "Open Sans"',
      backgroundColor: Color_default.RED
    });
    const context = canvas.getContext("2d");
    const pixel = context.getImageData(0, 0, 1, 1).data;
    expect(pixel).toEqual([255, 0, 0, 255]);
  });
  it("border can be set", function() {
    const canvas1 = writeTextToCanvas_default("a", {
      font: '90px "Open Sans"',
      backgroundColor: Color_default.RED
    });
    const canvas2 = writeTextToCanvas_default("a", {
      font: '90px "Open Sans"',
      backgroundColor: Color_default.RED,
      padding: 2
    });
    expect(canvas2.width).toEqual(canvas1.width + 4);
    expect(canvas2.height).toEqual(canvas1.height + 4);
  });
});

