describe("DataSources/CallbackPositionProperty", function() {
  let time2;
  beforeEach(function() {
    time2 = JulianDate_default.now();
  });
  it("constructor throws with undefined isConstant", function() {
    expect(function() {
      return new CallbackPositionProperty_default(function() {
      }, void 0);
    }).toThrowDeveloperError();
  });
  it("constructor throws with undefined callback", function() {
    expect(function() {
      return new CallbackPositionProperty_default(void 0, true);
    }).toThrowDeveloperError();
  });
  it("constructor sets expected defaults", function() {
    const callback = jasmine.createSpy("callback");
    let property = new CallbackPositionProperty_default(callback, true);
    expect(property.referenceFrame).toBe(ReferenceFrame_default.FIXED);
    property = new CallbackPositionProperty_default(
      callback,
      true,
      ReferenceFrame_default.INERTIAL
    );
    expect(property.referenceFrame).toBe(ReferenceFrame_default.INERTIAL);
  });
  it("callback received proper parameters", function() {
    const result = {};
    const callback = jasmine.createSpy("callback");
    const property = new CallbackPositionProperty_default(callback, true);
    property.getValue(time2, result);
    expect(callback).toHaveBeenCalledWith(time2, result);
  });
  it("getValue returns callback result", function() {
    const value = new Cartesian3_default(1, 2, 3);
    const callback = function(_time, result2) {
      return value.clone(result2);
    };
    const property = new CallbackPositionProperty_default(callback, true);
    const result = property.getValue(time2);
    expect(result).not.toBe(value);
    expect(result).toEqual(value);
    const value2 = new Cartesian3_default();
    expect(property.getValue(time2, value2)).toBe(value2);
  });
  it("getValue returns in fixed frame", function() {
    const valueInertial = new Cartesian3_default(1, 2, 3);
    const valueFixed = PositionProperty_default.convertToReferenceFrame(
      time2,
      valueInertial,
      ReferenceFrame_default.INERTIAL,
      ReferenceFrame_default.FIXED
    );
    const callback = function(_time, result2) {
      return valueInertial.clone(result2);
    };
    const property = new CallbackPositionProperty_default(
      callback,
      true,
      ReferenceFrame_default.INERTIAL
    );
    const result = property.getValue(time2);
    expect(result).toEqual(valueFixed);
  });
  it("getValue uses JulianDate.now() if time parameter is undefined", function() {
    spyOn(JulianDate_default, "now").and.callThrough();
    const value = new Cartesian3_default(1, 2, 3);
    const callback = function(_time, result) {
      return value.clone(result);
    };
    const property = new CallbackPositionProperty_default(callback, true);
    const actualResult = property.getValue();
    expect(JulianDate_default.now).toHaveBeenCalled();
    expect(actualResult).toEqual(value);
  });
  it("getValueInReferenceFrame works without a result parameter", function() {
    const value = new Cartesian3_default(1, 2, 3);
    const callback = function(_time, result2) {
      return value.clone(result2);
    };
    const property = new CallbackPositionProperty_default(callback, true);
    const result = property.getValueInReferenceFrame(
      time2,
      ReferenceFrame_default.INERTIAL
    );
    expect(result).not.toBe(value);
    expect(result).toEqual(
      PositionProperty_default.convertToReferenceFrame(
        time2,
        value,
        ReferenceFrame_default.FIXED,
        ReferenceFrame_default.INERTIAL
      )
    );
  });
  it("getValueInReferenceFrame works with a result parameter", function() {
    const value = new Cartesian3_default(1, 2, 3);
    const callback = function(_time, result2) {
      return value.clone(result2);
    };
    const property = new CallbackPositionProperty_default(
      callback,
      true,
      ReferenceFrame_default.INERTIAL
    );
    const expected = new Cartesian3_default();
    const result = property.getValueInReferenceFrame(
      time2,
      ReferenceFrame_default.FIXED,
      expected
    );
    expect(result).toBe(expected);
    expect(expected).toEqual(
      PositionProperty_default.convertToReferenceFrame(
        time2,
        value,
        ReferenceFrame_default.INERTIAL,
        ReferenceFrame_default.FIXED
      )
    );
  });
  it("getValueInReferenceFrame throws with undefined time", function() {
    const property = new CallbackPositionProperty_default(function() {
    }, true);
    expect(function() {
      property.getValueInReferenceFrame(void 0, ReferenceFrame_default.FIXED);
    }).toThrowDeveloperError();
  });
  it("getValueInReferenceFrame throws with undefined reference frame", function() {
    const property = new CallbackPositionProperty_default(function() {
    }, true);
    expect(function() {
      property.getValueInReferenceFrame(time2, void 0);
    }).toThrowDeveloperError();
  });
  it("isConstant returns correct value", function() {
    const property = new CallbackPositionProperty_default(function() {
    }, true);
    expect(property.isConstant).toBe(true);
    property.setCallback(function() {
    }, false);
    expect(property.isConstant).toBe(false);
  });
  it("setCallback raises definitionChanged event", function() {
    const property = new CallbackPositionProperty_default(function() {
    }, true);
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    property.setCallback(function() {
    }, false);
    expect(listener).toHaveBeenCalledWith(property);
  });
  it("equals works", function() {
    const callback = function() {
    };
    const left = new CallbackPositionProperty_default(callback, true);
    let right = new CallbackPositionProperty_default(callback, true);
    expect(left.equals(right)).toEqual(true);
    right.setCallback(callback, false);
    expect(left.equals(right)).toEqual(false);
    right.setCallback(function() {
      return void 0;
    }, true);
    expect(left.equals(right)).toEqual(false);
    right = new CallbackPositionProperty_default(
      callback,
      true,
      ReferenceFrame_default.INERTIAL
    );
    expect(left.equals(right)).toEqual(false);
  });
});

