// packages/engine/Specs/DataSources/CompositeMaterialPropertySpec.js
describe("DataSources/CompositeMaterialProperty", function() {
  it("default constructor has expected values", function() {
    const property = new CompositeMaterialProperty_default();
    expect(property.intervals).toBeInstanceOf(TimeIntervalCollection_default);
    expect(property.isConstant).toBe(true);
    expect(property.getType(JulianDate_default.now())).toBeUndefined();
    expect(property.getValue(JulianDate_default.now())).toBeUndefined();
  });
  it("works without a result parameter", function() {
    const interval1 = new TimeInterval_default({
      start: new JulianDate_default(10, 0),
      stop: new JulianDate_default(12, 0),
      data: new ColorMaterialProperty_default()
    });
    const interval2 = new TimeInterval_default({
      start: new JulianDate_default(12, 0),
      stop: new JulianDate_default(14, 0),
      isStartIncluded: false,
      data: new GridMaterialProperty_default()
    });
    const property = new CompositeMaterialProperty_default();
    property.intervals.addInterval(interval1);
    property.intervals.addInterval(interval2);
    expect(property.isConstant).toBe(false);
    const result1 = property.getValue(interval1.start);
    expect(property.getType(interval1.start)).toEqual("Color");
    expect(result1).not.toBe(interval1.data.getValue(interval1.start));
    expect(result1).toEqual(interval1.data.getValue(interval1.start));
    const result2 = property.getValue(interval2.stop);
    expect(property.getType(interval2.stop)).toEqual("Grid");
    expect(result2).not.toBe(interval2.data.getValue(interval2.stop));
    expect(result2).toEqual(interval2.data.getValue(interval2.stop));
  });
  it("works with a result parameter", function() {
    const interval1 = new TimeInterval_default({
      start: new JulianDate_default(10, 0),
      stop: new JulianDate_default(12, 0),
      data: new ColorMaterialProperty_default()
    });
    const interval2 = new TimeInterval_default({
      start: new JulianDate_default(12, 0),
      stop: new JulianDate_default(14, 0),
      isStartIncluded: false,
      data: new GridMaterialProperty_default()
    });
    const property = new CompositeMaterialProperty_default();
    property.intervals.addInterval(interval1);
    property.intervals.addInterval(interval2);
    expect(property.isConstant).toBe(false);
    const expected = {};
    const result1 = property.getValue(interval1.start, expected);
    expect(result1).toBe(expected);
    expect(result1).toEqual(interval1.data.getValue(interval1.start));
    const result2 = property.getValue(interval2.stop, expected);
    expect(result2).toBe(expected);
    expect(result2).toEqual(interval2.data.getValue(interval2.stop));
  });
  it("equals works", function() {
    const interval1 = new TimeInterval_default({
      start: new JulianDate_default(10, 0),
      stop: new JulianDate_default(12, 0),
      data: new ColorMaterialProperty_default()
    });
    const interval2 = new TimeInterval_default({
      start: new JulianDate_default(12, 0),
      stop: new JulianDate_default(14, 0),
      isStartIncluded: false,
      data: new GridMaterialProperty_default()
    });
    const left = new CompositeMaterialProperty_default();
    left.intervals.addInterval(interval1);
    left.intervals.addInterval(interval2);
    const right = new CompositeMaterialProperty_default();
    right.intervals.addInterval(interval1);
    expect(left.equals(right)).toEqual(false);
    right.intervals.addInterval(interval2);
    expect(left.equals(right)).toEqual(true);
  });
  it("raises definitionChanged event in all cases", function() {
    const interval1 = new TimeInterval_default({
      start: new JulianDate_default(10, 0),
      stop: new JulianDate_default(12, 0),
      data: new ColorMaterialProperty_default(Color_default.RED)
    });
    const interval2 = new TimeInterval_default({
      start: new JulianDate_default(12, 0),
      stop: new JulianDate_default(14, 0),
      isStartIncluded: false,
      data: new ColorMaterialProperty_default(Color_default.YELLOW)
    });
    const property = new CompositeMaterialProperty_default();
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    property.intervals.addInterval(interval1);
    expect(listener).toHaveBeenCalledWith(property);
    listener.calls.reset();
    property.intervals.addInterval(interval2);
    expect(listener).toHaveBeenCalledWith(property);
    listener.calls.reset();
    property.intervals.removeInterval(interval2);
    expect(listener).toHaveBeenCalledWith(property);
    listener.calls.reset();
    interval1.data.color.setValue(Color_default.BLUE);
    expect(listener).toHaveBeenCalledWith(property);
    listener.calls.reset();
    property.intervals.removeAll();
    expect(listener).toHaveBeenCalledWith(property);
    listener.calls.reset();
  });
  it("does not raise definitionChanged for an overwritten interval", function() {
    const interval1 = new TimeInterval_default({
      start: new JulianDate_default(11, 0),
      stop: new JulianDate_default(13, 0),
      data: new ColorMaterialProperty_default(Color_default.RED)
    });
    const interval2 = new TimeInterval_default({
      start: new JulianDate_default(10, 0),
      stop: new JulianDate_default(14, 0),
      isStartIncluded: false,
      data: new ColorMaterialProperty_default(Color_default.YELLOW)
    });
    const property = new CompositeMaterialProperty_default();
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    property.intervals.addInterval(interval1);
    property.intervals.addInterval(interval2);
    expect(listener.calls.count()).toBe(2);
    interval1.data.color.setValue(Color_default.BLUE);
    expect(listener.calls.count()).toBe(2);
  });
  it("getValue uses JulianDate.now() if time parameter is undefined", function() {
    spyOn(JulianDate_default, "now").and.callThrough();
    const property = new CompositeMaterialProperty_default();
    property.getValue();
    expect(JulianDate_default.now).toHaveBeenCalled();
  });
  it("getType throws with no time parameter", function() {
    const property = new CompositeMaterialProperty_default();
    expect(function() {
      property.getType(void 0);
    }).toThrowDeveloperError();
  });
});

