  it("can handle aligned axis expressed as a velocity reference", function() {
    const packet = {
      position: {
        epoch: "2016-06-17T12:00:00Z",
        cartesian: [0, 1, 2, 3, 60, 61, 122, 183]
      },
      billboard: {
        alignedAxis: {
          velocityReference: "#position"
        }
      }
    };
    return CzmlDataSource_default.load(makeDocument(packet)).then(
      function(dataSource) {
        const entity = dataSource.entities.values[0];
        const property = entity.billboard.alignedAxis;
        const expectedVelocity = new Cartesian3_default(1, 2, 3);
        const expectedVelocityDirection = Cartesian3_default.normalize(
          expectedVelocity,
          new Cartesian3_default()
        );
        expect(
          property.getValue(JulianDate_default.fromIso8601("2016-06-17T12:00:00Z"))
        ).toEqualEpsilon(expectedVelocityDirection, Math_default.EPSILON15);
        expect(
          property.getValue(JulianDate_default.fromIso8601("2016-06-17T12:00:30Z"))
        ).toEqualEpsilon(expectedVelocityDirection, Math_default.EPSILON15);
      }
    );
  });
