  it("can convert a sampled position property to a composite by sending intervals in a subsequent packet", function() {
    const sampledPacket = {
      id: "a",
      position: {
        cartographicDegrees: [
          "2010-01-01T00:00:00Z",
          34,
          117,
          1e4,
          "2010-01-01T01:00:00Z",
          34,
          117,
          2e4
        ]
      }
    };
    const intervalPacket = {
      id: "a",
      position: [
        {
          interval: "2010-01-01T00:20:00Z/2010-01-01T00:22:00Z",
          cartographicDegrees: [
            "2010-01-01T00:20:00Z",
            40,
            100,
            1e4,
            "2010-01-01T00:22:00Z",
            40,
            100,
            2e4
          ]
        }
      ]
    };
    return CzmlDataSource_default.load(makeDocument(sampledPacket)).then(function(dataSource) {
      return dataSource.process(intervalPacket);
    }).then(function(dataSource) {
      const entity = dataSource.entities.getById("a");
      expect(entity.position).toBeDefined();
      expect(entity.position).toBeInstanceOf(CompositePositionProperty_default);
      expect(
        entity.position.getValue(
          JulianDate_default.fromIso8601("2010-01-01T00:00:00Z")
        )
      ).toEqual(Cartesian3_default.fromDegrees(34, 117, 1e4));
      expect(
        entity.position.getValue(
          JulianDate_default.fromIso8601("2010-01-01T00:20:00Z")
        )
      ).toEqual(Cartesian3_default.fromDegrees(40, 100, 1e4));
      expect(
        entity.position.getValue(
          JulianDate_default.fromIso8601("2010-01-01T00:21:00Z")
        )
      ).toEqualEpsilon(
        Cartesian3_default.fromDegrees(40, 100, 15e3),
        Math_default.EPSILON10
      );
      expect(
        entity.position.getValue(
          JulianDate_default.fromIso8601("2010-01-01T00:22:00Z")
        )
      ).toEqual(Cartesian3_default.fromDegrees(40, 100, 2e4));
      expect(
        entity.position.getValue(
          JulianDate_default.fromIso8601("2010-01-01T01:00:00Z")
        )
      ).toEqual(Cartesian3_default.fromDegrees(34, 117, 2e4));
    });
  });
