  it("normalizes sampled orientation on load", function() {
    const time1 = "2000-01-01T00:00:00Z";
    const time2 = "2000-01-01T00:00:01Z";
    const packet = {
      orientation: {
        unitQuaternion: [
          time1,
          0,
          0,
          0.7071067,
          0.7071067,
          time2,
          0.7071067,
          0.7071067,
          0,
          0
        ]
      }
    };
    const expected1 = Quaternion_default.unpack(packet.orientation.unitQuaternion, 1);
    Quaternion_default.normalize(expected1, expected1);
    const expected2 = Quaternion_default.unpack(packet.orientation.unitQuaternion, 6);
    Quaternion_default.normalize(expected2, expected2);
    return CzmlDataSource_default.load(makeDocument(packet)).then(
      function(dataSource) {
        const entity = dataSource.entities.values[0];
        expect(
          entity.orientation.getValue(JulianDate_default.fromIso8601(time1))
        ).toEqual(expected1);
        expect(
          entity.orientation.getValue(JulianDate_default.fromIso8601(time2))
        ).toEqual(expected2);
      }
    );
  });
  it("can handle orientation expressed as a velocity reference", function() {
    const packet = {
      position: {
        epoch: "2016-06-17T12:00:00Z",
        cartesian: [0, 1, 2, 3, 60, 61, 122, 183]
      },
      orientation: {
        velocityReference: "#position"
      }
    };
    return CzmlDataSource_default.load(makeDocument(packet)).then(
      function(dataSource) {
        const entity = dataSource.entities.values[0];
        const property = entity.orientation;
        const expectedVelocity = new Cartesian3_default(1, 2, 3);
        const expectedVelocityDirection = Cartesian3_default.normalize(
          expectedVelocity,
          new Cartesian3_default()
        );
        const expectedPosition = new Cartesian3_default(1, 2, 3);
        const expectedRotation = FixedFrameTransforms_default.rotationMatrixFromPositionVelocity(
          expectedPosition,
          expectedVelocityDirection
        );
        const expectedOrientation = Quaternion_default.fromRotationMatrix(expectedRotation);
        expect(
          property.getValue(JulianDate_default.fromIso8601("2016-06-17T12:00:00Z"))
        ).toEqualEpsilon(expectedOrientation, Math_default.EPSILON15);
        expect(
          property.getValue(JulianDate_default.fromIso8601("2016-06-17T12:00:30Z"))
        ).toEqualEpsilon(expectedOrientation, Math_default.EPSILON15);
      }
    );
  });
