  it("can delete an entire property", function() {
    function createDataSource() {
      return CzmlDataSource_default.load([
        {
          id: "document",
          version: "1.0"
        },
        {
          id: "test-constant",
          billboard: {
            scale: 1
          }
        },
        {
          id: "test-interval",
          billboard: {
            scale: [
              {
                interval: "2012-03-15T10:00:00Z/2012-03-16T10:00:00Z",
                number: 1
              }
            ]
          }
        },
        {
          id: "test-sampled",
          billboard: {
            scale: {
              number: ["2012-03-15T10:00:00Z", 1]
            }
          }
        }
      ]);
    }
    const deletePackets = [
      {
        id: "test-constant",
        billboard: {
          scale: {
            delete: true
          }
        }
      },
      {
        id: "test-interval",
        billboard: {
          scale: {
            delete: true
          }
        }
      },
      {
        id: "test-sampled",
        billboard: {
          scale: {
            delete: true
          }
        }
      }
    ];
    const deleteMaxIntervalPackets = [
      {
        id: "test-constant",
        billboard: {
          scale: {
            interval: TimeInterval_default.toIso8601(Iso8601_default.MAXIMUM_INTERVAL),
            delete: true
          }
        }
      },
      {
        id: "test-interval",
        billboard: {
          scale: {
            interval: TimeInterval_default.toIso8601(Iso8601_default.MAXIMUM_INTERVAL),
            delete: true
          }
        }
      },
      {
        id: "test-sampled",
        billboard: {
          scale: {
            interval: TimeInterval_default.toIso8601(Iso8601_default.MAXIMUM_INTERVAL),
            delete: true
          }
        }
      }
    ];
    function expectPropertiesToBeDefined(dataSource) {
      let entity = dataSource.entities.getById("test-constant");
      expect(entity.billboard.scale).toBeInstanceOf(ConstantProperty_default);
      entity = dataSource.entities.getById("test-interval");
      expect(entity.billboard.scale).toBeInstanceOf(
        TimeIntervalCollectionProperty_default
      );
      entity = dataSource.entities.getById("test-sampled");
      expect(entity.billboard.scale).toBeInstanceOf(SampledProperty_default);
      return dataSource;
    }
    function expectPropertiesToBeUndefined(dataSource) {
      let entity = dataSource.entities.getById("test-constant");
      expect(entity.billboard.scale).toBeUndefined();
      entity = dataSource.entities.getById("test-interval");
      expect(entity.billboard.scale).toBeUndefined();
      entity = dataSource.entities.getById("test-sampled");
      expect(entity.billboard.scale).toBeUndefined();
      return dataSource;
    }
    return createDataSource().then(expectPropertiesToBeDefined).then(function(dataSource) {
      return dataSource.process(deletePackets);
    }).then(expectPropertiesToBeUndefined).then(function(dataSource) {
      return dataSource.process(deletePackets);
    }).then(expectPropertiesToBeUndefined).then(createDataSource).then(function(dataSource) {
      return dataSource.process(deleteMaxIntervalPackets);
    }).then(expectPropertiesToBeUndefined).then(function(dataSource) {
      return dataSource.process(deleteMaxIntervalPackets);
    }).then(expectPropertiesToBeUndefined);
  });
