  it("can load custom properties in a way that allows CompositeEntityCollection to work", function() {
    const testObject1 = {
      foo: 4,
      bar: {
        name: "bar"
      }
    };
    const testArray1 = [2, 4, 16, "test"];
    const packet1 = {
      id: "test",
      properties: {
        constant_name: "ABC",
        constant_height: 8,
        constant_object: {
          value: testObject1
        },
        constant_array: {
          value: testArray1
        }
      }
    };
    const dataSource1 = new CzmlDataSource_default();
    const dataSource2 = new CzmlDataSource_default();
    const time2 = Iso8601_default.MINIMUM_VALUE;
    const packet2 = {
      id: "test",
      properties: {
        constant_name: "DEF"
      }
    };
    const testObject3 = {
      some: "value"
    };
    const testArray3 = ["not", "the", "same", 4];
    const packet3 = {
      id: "test",
      properties: {
        constant_height: 9,
        constant_object: {
          value: testObject3
        },
        constant_array: {
          value: testArray3
        }
      }
    };
    let entity, composite;
    return dataSource1.load(makeDocument(packet1)).then(function() {
      composite = new CompositeEntityCollection_default([
        dataSource1.entities,
        dataSource2.entities
      ]);
      entity = composite.values[0];
      expect(entity.properties.constant_name.getValue(time2)).toEqual(
        packet1.properties.constant_name
      );
      expect(entity.properties.constant_height.getValue(time2)).toEqual(
        packet1.properties.constant_height
      );
      expect(entity.properties.constant_object.getValue(time2)).toEqual(
        testObject1
      );
      expect(entity.properties.constant_array.getValue(time2)).toEqual(
        testArray1
      );
      return dataSource2.load(makeDocument(packet2));
    }).then(function() {
      entity = composite.values[0];
      expect(entity.properties.constant_name.getValue(time2)).toEqual(
        packet2.properties.constant_name
      );
      expect(entity.properties.constant_height.getValue(time2)).toEqual(
        packet1.properties.constant_height
      );
      expect(entity.properties.constant_object.getValue(time2)).toEqual(
        testObject1
      );
      expect(entity.properties.constant_array.getValue(time2)).toEqual(
        testArray1
      );
      return dataSource2.process(packet3);
    }).then(function() {
      entity = composite.values[0];
      expect(entity.properties.constant_name.getValue(time2)).toEqual(
        packet2.properties.constant_name
      );
      expect(entity.properties.constant_height.getValue(time2)).toEqual(
        packet3.properties.constant_height
      );
      expect(entity.properties.constant_object.getValue(time2)).toEqual(
        testObject3
      );
      expect(entity.properties.constant_array.getValue(time2)).toEqual(
        testArray3
      );
    });
  });
