  function printInterval(startTime, stopTime) {
    return TimeInterval_default.toIso8601(
      new TimeInterval_default({
        start: startTime,
        stop: stopTime
      })
    );
  }
  it("can load materials specified with composite interval", function() {
    const beforeTime = JulianDate_default.fromIso8601("2012-03-15T09:23:59Z");
    const solidTime = JulianDate_default.fromIso8601("2012-03-15T10:00:00Z");
    const gridTime1 = JulianDate_default.fromIso8601("2012-03-15T11:00:00Z");
    const gridTime2 = JulianDate_default.fromIso8601("2012-03-15T12:00:00Z");
    const afterTime = JulianDate_default.fromIso8601("2012-03-15T12:00:01Z");
    const packet = {
      id: "obj",
      polygon: {
        material: [
          {
            interval: printInterval(solidTime, gridTime1),
            solidColor: {
              color: {
                rgba: [240, 0, 0, 0]
              }
            }
          },
          {
            interval: printInterval(gridTime1, gridTime2),
            grid: {
              color: {
                rgba: [240, 255, 255, 255]
              },
              cellAlpha: 0,
              lineCount: {
                cartesian2: [36, 9]
              },
              lineThickness: {
                cartesian2: [1, 1]
              },
              lineOffset: {
                cartesian2: [0.5, 0.5]
              }
            }
          }
        ]
      }
    };
    let secondPacket;
    return CzmlDataSource_default.load(makeDocument(packet)).then(function(dataSource) {
      const entity = dataSource.entities.getById("obj");
      expect(entity.polygon.material).toBeInstanceOf(
        CompositeMaterialProperty_default
      );
      expect(entity.polygon.material.getType(solidTime)).toEqual("Color");
      expect(entity.polygon.material.getValue(solidTime).color).toEqual(
        Color_default.unpack(
          packet.polygon.material[0].solidColor.color.rgba.map(
            Color_default.byteToFloat
          )
        )
      );
      function assertValuesForGridMaterial(time2) {
        expect(entity.polygon.material.getValue(time2).color).toEqual(
          Color_default.unpack(
            packet.polygon.material[1].grid.color.rgba.map(Color_default.byteToFloat)
          )
        );
        expect(entity.polygon.material.getValue(time2).cellAlpha).toEqual(
          packet.polygon.material[1].grid.cellAlpha
        );
        expect(entity.polygon.material.getValue(time2).lineCount).toEqual(
          Cartesian2_default.unpack(
            packet.polygon.material[1].grid.lineCount.cartesian2
          )
        );
        expect(entity.polygon.material.getValue(time2).lineThickness).toEqual(
          Cartesian2_default.unpack(
            packet.polygon.material[1].grid.lineThickness.cartesian2
          )
        );
        expect(entity.polygon.material.getValue(time2).lineOffset).toEqual(
          Cartesian2_default.unpack(
            packet.polygon.material[1].grid.lineOffset.cartesian2
          )
        );
      }
      expect(entity.polygon.material.getType(gridTime1)).toEqual("Grid");
      assertValuesForGridMaterial(gridTime1);
      expect(entity.polygon.material.getType(gridTime2)).toEqual("Grid");
      assertValuesForGridMaterial(gridTime2);
      expect(entity.polygon.material.getType(beforeTime)).toBeUndefined();
      expect(entity.polygon.material.getType(afterTime)).toBeUndefined();
      return dataSource;
    }).then(function(dataSource) {
      secondPacket = {
        id: "obj",
        polygon: {
          material: [
            {
              interval: printInterval(solidTime, gridTime1),
              solidColor: {
                color: {
                  rgba: [200, 100, 50, 255]
                }
              }
            }
          ]
        }
      };
      return dataSource.process(secondPacket);
    }).then(function(dataSource) {
      const entity = dataSource.entities.getById("obj");
      expect(entity.polygon.material).toBeInstanceOf(
        CompositeMaterialProperty_default
      );
      expect(entity.polygon.material.getType(solidTime)).toEqual("Color");
      expect(entity.polygon.material.getValue(solidTime).color).toEqual(
        Color_default.unpack(
          secondPacket.polygon.material[0].solidColor.color.rgba.map(
            Color_default.byteToFloat
          )
        )
      );
    });
  });
