  it("can handle sampled rectangle coordinates.", function() {
    const epoch2 = JulianDate_default.now();
    const packet = {
      rectangle: {
        coordinates: {
          epoch: JulianDate_default.toIso8601(epoch2),
          wsen: [0, 1, 2, 3, 4, 1, 3, 4, 5, 6]
        }
      }
    };
    return CzmlDataSource_default.load(makeDocument(packet)).then(
      function(dataSource) {
        const entity = dataSource.entities.values[0];
        expect(entity.rectangle).toBeDefined();
        const date1 = epoch2;
        const date2 = JulianDate_default.addSeconds(epoch2, 0.5, new JulianDate_default());
        const date3 = JulianDate_default.addSeconds(epoch2, 1, new JulianDate_default());
        expect(entity.rectangle.coordinates.getValue(date1)).toEqual(
          new Rectangle_default(1, 2, 3, 4)
        );
        expect(entity.rectangle.coordinates.getValue(date2)).toEqual(
          new Rectangle_default(2, 3, 4, 5)
        );
        expect(entity.rectangle.coordinates.getValue(date3)).toEqual(
          new Rectangle_default(3, 4, 5, 6)
        );
      }
    );
  });
