  it("converts followSurface to arcType for backwards compatibility", function() {
    const packets = [
      {
        id: "document",
        version: "1.0"
      },
      {
        id: "followSurface-false",
        polyline: {
          followSurface: false
        }
      },
      {
        id: "followSurface-true",
        polyline: {
          followSurface: true
        }
      },
      {
        id: "followSurface-time-varying",
        polyline: {
          followSurface: [
            {
              interval: "2013-01-01T00:00:00Z/2013-01-01T01:00:00Z",
              boolean: true
            },
            {
              interval: "2013-01-01T01:00:00Z/2013-01-01T02:00:00Z",
              boolean: false
            }
          ]
        }
      },
      {
        id: "arcType-overrides-followSurface",
        polyline: {
          followSurface: true,
          arcType: "RHUMB"
        }
      }
    ];
    return CzmlDataSource_default.load(packets).then(function(dataSource) {
      const date = JulianDate_default.now();
      let entity = dataSource.entities.getById("followSurface-false");
      expect(entity.polyline.arcType.isConstant).toEqual(true);
      expect(entity.polyline.arcType.getValue(date)).toEqual(ArcType_default.NONE);
      entity = dataSource.entities.getById("followSurface-true");
      expect(entity.polyline.arcType.isConstant).toEqual(true);
      expect(entity.polyline.arcType.getValue(date)).toEqual(ArcType_default.GEODESIC);
      entity = dataSource.entities.getById("followSurface-time-varying");
      expect(entity.polyline.arcType.isConstant).toEqual(false);
      expect(
        entity.polyline.arcType.getValue(
          JulianDate_default.fromIso8601("2013-01-01T00:00:00Z")
        )
      ).toEqual(ArcType_default.GEODESIC);
      expect(
        entity.polyline.arcType.getValue(
          JulianDate_default.fromIso8601("2013-01-01T01:00:00Z")
        )
      ).toEqual(ArcType_default.NONE);
      entity = dataSource.entities.getById("arcType-overrides-followSurface");
      expect(entity.polyline.arcType.isConstant).toEqual(true);
      expect(entity.polyline.arcType.getValue(date)).toEqual(ArcType_default.RHUMB);
    });
  });
