      expect(e2.properties.custom_wsen.getValue(documentStopDate)).toEqual(new Rectangle_default(1.19133054275098, 0.9154648059314, 0.71347968461712, 1.32750822775441));
      expect(e2.properties.custom_wsenDegrees.getValue(documentStartDate)).toEqual(Rectangle_default.fromDegrees(29, 11, 17, 36));
      expect(e2.properties.custom_wsenDegrees.getValue(documentStopDate)).toEqual(Rectangle_default.fromDegrees(37, 16, 25, 23));
