  it("load does deferred loading", function() {
    const kml = '<?xml version="1.0" encoding="UTF-8"?>        <Document xmlns="http://www.opengis.net/kml/2.2"                  xmlns:gx="http://www.google.com/kml/ext/2.2">            <Placemark id="Bob">            </Placemark>            <Placemark id="Bob2">            </Placemark>        </Document>';
    jasmine.clock().install();
    jasmine.clock().mockDate(/* @__PURE__ */ new Date());
    spyOn(KmlDataSource_default, "_getTimestamp").and.callFake(function() {
      return Date.now();
    });
    const OrigDeferredLoading = KmlDataSource_default._DeferredLoading;
    let deferredLoading;
    spyOn(KmlDataSource_default, "_DeferredLoading").and.callFake(
      function(datasource) {
        deferredLoading = new OrigDeferredLoading(datasource);
        const process3 = deferredLoading._process.bind(deferredLoading);
        spyOn(deferredLoading, "_process").and.callFake(function(isFirst) {
          jasmine.clock().tick(1001);
          return process3(isFirst);
        });
        const giveUpTime = deferredLoading._giveUpTime.bind(deferredLoading);
        spyOn(deferredLoading, "_giveUpTime").and.callFake(function() {
          giveUpTime();
          jasmine.clock().tick(1);
        });
        return deferredLoading;
      }
    );
    const dataSource = new KmlDataSource_default(options);
    return dataSource.load(parser3.parseFromString(kml, "text/xml"), options).then(function(source) {
      expect(deferredLoading._process.calls.count()).toEqual(3);
      jasmine.clock().uninstall();
    });
  });
