  it("sets DatasourceClock based on feature availability", function() {
    const beginDate = JulianDate_default.fromIso8601("2000-01-01");
    const endDate = JulianDate_default.fromIso8601("2000-01-04");
    let kml = '<?xml version="1.0" encoding="UTF-8"?>        <Document xmlns="http://www.opengis.net/kml/2.2"                  xmlns:gx="http://www.google.com/kml/ext/2.2">          <GroundOverlay>            <TimeSpan>              <begin>2000-01-01</begin>              <end>2000-01-03</end>            </TimeSpan>          </GroundOverlay>          <Placemark>            <gx:Track>              <when>2000-01-02</when>              <gx:coord>1 2 3</gx:coord>              <when>2000-01-04</when>              <gx:coord>4 5 6</gx:coord>            </gx:Track>          </Placemark>        </Document>';
    return KmlDataSource_default.load(parser3.parseFromString(kml, "text/xml"), options).then(function(dataSource) {
      const clock = dataSource.clock;
      expect(dataSource.clock).toBeDefined();
      expect(clock.startTime).toEqual(beginDate);
      expect(clock.stopTime).toEqual(endDate);
      expect(clock.currentTime).toEqual(beginDate);
      expect(clock.clockRange).toEqual(ClockRange_default.LOOP_STOP);
      expect(clock.clockStep).toEqual(ClockStep_default.SYSTEM_CLOCK_MULTIPLIER);
      expect(clock.multiplier).toEqual(
        JulianDate_default.secondsDifference(endDate, beginDate) / 60
      );
      return dataSource;
    }).then(function(dataSource) {
      kml = '<?xml version="1.0" encoding="UTF-8"?>                <Document xmlns="http://www.opengis.net/kml/2.2"                          xmlns:gx="http://www.google.com/kml/ext/2.2">                  <GroundOverlay>                  </GroundOverlay>                </Document>';
      return dataSource.load(
        parser3.parseFromString(kml, "text/xml"),
        options
      );
    }).then(function(dataSource) {
      expect(dataSource.clock).toBeUndefined();
    });
  });
