  it("Geometry Polygon: with holes", function() {
    const kml = '<?xml version="1.0" encoding="UTF-8"?>          <Placemark>            <Polygon>            <outerBoundaryIs>            <LinearRing>              <coordinates>                1,2,3                4,5,6                7,8,9             </coordinates>            </LinearRing>            </outerBoundaryIs>            <innerBoundaryIs>            <LinearRing>              <coordinates>                1.1,2.1,3.1                4.1,5.1,6.1                7.1,8.1,9.1             </coordinates>            </LinearRing>            </innerBoundaryIs>            <innerBoundaryIs>            <LinearRing>              <coordinates>                1.2,2.2,3.2                4.2,5.2,6.2                7.2,8.2,9.2             </coordinates>            </LinearRing>            </innerBoundaryIs>            </Polygon>          </Placemark>';
    return KmlDataSource_default.load(
      parser3.parseFromString(kml, "text/xml"),
      options
    ).then(function(dataSource) {
      const entity = dataSource.entities.values[0];
      const coordinates = [
        Cartesian3_default.fromDegrees(1, 2, 3),
        Cartesian3_default.fromDegrees(4, 5, 6),
        Cartesian3_default.fromDegrees(7, 8, 9)
      ];
      const holeCoordinates = [
        Cartesian3_default.fromDegrees(1.1, 2.1, 3.1),
        Cartesian3_default.fromDegrees(4.1, 5.1, 6.1),
        Cartesian3_default.fromDegrees(7.1, 8.1, 9.1)
      ];
      const holeCoordinates2 = [
        Cartesian3_default.fromDegrees(1.2, 2.2, 3.2),
        Cartesian3_default.fromDegrees(4.2, 5.2, 6.2),
        Cartesian3_default.fromDegrees(7.2, 8.2, 9.2)
      ];
      const hierarchy = entity.polygon.hierarchy.getValue();
      expect(hierarchy.positions).toEqual(coordinates);
      expect(hierarchy.holes.length).toEqual(2);
      expect(hierarchy.holes[0].positions).toEqual(holeCoordinates);
      expect(hierarchy.holes[0].holes).toEqual([]);
      expect(hierarchy.holes[1].positions).toEqual(holeCoordinates2);
      expect(hierarchy.holes[1].holes).toEqual([]);
    });
  });
