    it("computeVvlhTransform returns a matrix for moving position properties", function() {
      const property = new SampledPositionProperty_default();
      const start = new JulianDate_default(0, 0);
      const stop = new JulianDate_default(0, 10);
      property.addSample(start, new Cartesian3_default(7e6, 0, 0));
      property.addSample(stop, new Cartesian3_default(7e6, 10, 0));
      const result = PathVisualizer_default._computeVvlhTransform(
        start,
        property,
        new Matrix4_default()
      );
      const rotation = Matrix4_default.getMatrix3(result, new Matrix3_default());
      const xAxis = Matrix3_default.getColumn(rotation, 0, new Cartesian3_default());
      const yAxis = Matrix3_default.getColumn(rotation, 1, new Cartesian3_default());
      const zAxis = Matrix3_default.getColumn(rotation, 2, new Cartesian3_default());
      const expectedZAxis = Cartesian3_default.normalize(
        property.getValue(start, new Cartesian3_default()),
        new Cartesian3_default()
      );
      const expectedXAxis = Cartesian3_default.normalize(
        Cartesian3_default.cross(yAxis, zAxis, new Cartesian3_default()),
        new Cartesian3_default()
      );
      expect(result).toBeDefined();
      expect(Matrix4_default.getTranslation(result, new Cartesian3_default())).toEqual(
        property.getValue(start)
      );
      expect(zAxis).toEqualEpsilon(expectedZAxis, Math_default.EPSILON14);
      expect(xAxis).toEqualEpsilon(expectedXAxis, Math_default.EPSILON14);
    });
