// packages/engine/Specs/DataSources/PlaneGeometryUpdaterSpec.js
describe(
  "DataSources/PlaneGeometryUpdater",
  function() {
    let scene2;
    beforeAll(function() {
      scene2 = createScene_default();
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    function createBasicPlane() {
      const planeGraphics = new PlaneGraphics_default();
      planeGraphics.plane = new ConstantProperty_default(
        new Plane_default(Cartesian3_default.UNIT_X, 0)
      );
      planeGraphics.dimensions = new ConstantProperty_default(new Cartesian2_default(1, 2));
      const entity = new Entity_default();
      entity.position = new ConstantPositionProperty_default(
        Cartesian3_default.fromDegrees(0, 0, 0)
      );
      entity.plane = planeGraphics;
      return entity;
    }
    function createDynamicPlane() {
      const entity = createBasicPlane();
      entity.plane.plane = createDynamicProperty_default(
        new Plane_default(Cartesian3_default.UNIT_X, 0)
      );
      entity.plane.dimensions = createDynamicProperty_default(new Cartesian2_default(1, 2));
      return entity;
    }
    it("A time-varying plane causes geometry to be dynamic", function() {
      const entity = createBasicPlane();
      const updater = new PlaneGeometryUpdater_default(entity, scene2);
      entity.plane.plane = createDynamicProperty_default();
      updater._onEntityPropertyChanged(entity, "plane");
      expect(updater.isDynamic).toBe(true);
    });
    it("A time-varying dimensions causes geometry to be dynamic", function() {
      const entity = createBasicPlane();
      const updater = new PlaneGeometryUpdater_default(entity, scene2);
      entity.plane.dimensions = createDynamicProperty_default();
      updater._onEntityPropertyChanged(entity, "plane");
      expect(updater.isDynamic).toBe(true);
    });
    it("dynamic updater sets properties", function() {
      const entity = createDynamicPlane();
      const updater = new PlaneGeometryUpdater_default(entity, scene2);
      const dynamicUpdater = updater.createDynamicUpdater(
        new PrimitiveCollection_default(),
        new PrimitiveCollection_default()
      );
      dynamicUpdater.update(JulianDate_default.now());
      const options = dynamicUpdater._options;
      expect(options.plane).toEqual(entity.plane.plane.getValue());
      expect(options.dimensions).toEqual(entity.plane.dimensions.getValue());
    });
    it("geometryChanged event is raised when expected", function() {
      const entity = createBasicPlane();
      const updater = new PlaneGeometryUpdater_default(entity, scene2);
      const listener = jasmine.createSpy("listener");
      updater.geometryChanged.addEventListener(listener);
      entity.plane.dimensions = new ConstantProperty_default();
      updater._onEntityPropertyChanged(entity, "plane");
      expect(listener.calls.count()).toEqual(1);
      entity.availability = new TimeIntervalCollection_default();
      updater._onEntityPropertyChanged(entity, "availability");
      expect(listener.calls.count()).toEqual(2);
      entity.plane.dimensions = void 0;
      updater._onEntityPropertyChanged(entity, "plane");
      expect(listener.calls.count()).toEqual(3);
      entity.plane.height = void 0;
      updater._onEntityPropertyChanged(entity, "plane");
      entity.viewFrom = new ConstantProperty_default(Cartesian3_default.UNIT_X);
      updater._onEntityPropertyChanged(entity, "viewFrom");
      expect(listener.calls.count()).toEqual(3);
    });
    function getScene() {
      return scene2;
    }
    createGeometryUpdaterSpecs_default(
      PlaneGeometryUpdater_default,
      "plane",
      createBasicPlane,
      getScene
    );
    createDynamicGeometryUpdaterSpecs_default(
      PlaneGeometryUpdater_default,
      "plane",
      createDynamicPlane,
      getScene
    );
  },
  "WebGL"
);

