// packages/engine/Specs/DataSources/PolylineArrowMaterialPropertySpec.js
describe("DataSources/PolylineArrowMaterialProperty", function() {
  it("constructor provides the expected defaults", function() {
    let property = new PolylineArrowMaterialProperty_default();
    expect(property.color).toBeUndefined();
    expect(property.getType()).toEqual("PolylineArrow");
    expect(property.isConstant).toBe(true);
    const result = property.getValue();
    expect(result.color).toEqual(Color_default.WHITE);
    const colorProperty = new ConstantProperty_default(Color_default.BLUE);
    property = new PolylineArrowMaterialProperty_default(colorProperty);
    expect(property.color).toBe(colorProperty);
    property = new PolylineArrowMaterialProperty_default(Color_default.BLUE);
    expect(property.color).toBeInstanceOf(ConstantProperty_default);
    expect(property.color.getValue()).toEqual(Color_default.BLUE);
  });
  it("works with constant values", function() {
    const property = new PolylineArrowMaterialProperty_default();
    property.color = new ConstantProperty_default(Color_default.RED);
    const result = property.getValue(JulianDate_default.now());
    expect(result.color).toEqual(Color_default.RED);
  });
  it("works with dynamic values", function() {
    const property = new PolylineArrowMaterialProperty_default();
    property.color = new TimeIntervalCollectionProperty_default();
    const start = new JulianDate_default(1, 0);
    const stop = new JulianDate_default(2, 0);
    property.color.intervals.addInterval(
      new TimeInterval_default({
        start,
        stop,
        data: Color_default.BLUE
      })
    );
    expect(property.isConstant).toBe(false);
    const result = property.getValue(start);
    expect(result.color).toEqual(Color_default.BLUE);
  });
  it("works with a result parameter", function() {
    const property = new PolylineArrowMaterialProperty_default();
    property.color = new ConstantProperty_default(Color_default.RED);
    const result = {
      color: Color_default.BLUE.clone()
    };
    const returnedResult = property.getValue(JulianDate_default.now(), result);
    expect(returnedResult).toBe(result);
    expect(result.color).toEqual(Color_default.RED);
  });
  it("equals works", function() {
    const left = new PolylineArrowMaterialProperty_default();
    left.color = new ConstantProperty_default(Color_default.WHITE);
    const right = new PolylineArrowMaterialProperty_default();
    right.color = new ConstantProperty_default(Color_default.WHITE);
    expect(left.equals(right)).toEqual(true);
    right.color = new ConstantProperty_default(Color_default.BLACK);
    expect(left.equals(right)).toEqual(false);
  });
  it("raises definitionChanged when a color property is assigned or modified", function() {
    const property = new PolylineArrowMaterialProperty_default();
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    const oldValue = property.color;
    property.color = new ConstantProperty_default(Color_default.WHITE);
    expect(listener).toHaveBeenCalledWith(
      property,
      "color",
      property.color,
      oldValue
    );
    listener.calls.reset();
    property.color.setValue(Color_default.BLACK);
    expect(listener).toHaveBeenCalledWith(
      property,
      "color",
      property.color,
      property.color
    );
    listener.calls.reset();
    property.color = property.color;
    expect(listener.calls.count()).toEqual(0);
  });
});

