    function validateGeometryInstance(options) {
      const entity = createBasicPolyline();
      const clampToGround = options.clampToGround;
      const polyline4 = entity.polyline;
      polyline4.show = new ConstantProperty_default(options.show);
      polyline4.material = options.material;
      polyline4.depthFailMaterial = options.depthFailMaterial;
      polyline4.width = new ConstantProperty_default(options.width);
      polyline4.granularity = new ConstantProperty_default(options.granularity);
      polyline4.distanceDisplayCondition = options.distanceDisplayCondition;
      polyline4.clampToGround = new ConstantProperty_default(clampToGround);
      polyline4.arcType = new ConstantProperty_default(options.arcType);
      const updater = new PolylineGeometryUpdater_default(entity, scene2);
      const instance = updater.createFillGeometryInstance(time2);
      const geometry = instance.geometry;
      const attributes = instance.attributes;
      if (clampToGround) {
        expect(geometry.width).toEqual(options.width);
      } else {
        expect(geometry._width).toEqual(options.width);
        if (defined_default(options.arcType)) {
          expect(geometry._arcType).toEqual(options.arcType);
        }
        expect(geometry._granularity).toEqual(options.granularity);
        if (options.depthFailMaterial && options.depthFailMaterial instanceof ColorMaterialProperty_default) {
          expect(attributes.depthFailColor.value).toEqual(
            ColorGeometryInstanceAttribute_default.toValue(
              options.depthFailMaterial.color.getValue(time2)
            )
          );
        } else {
          expect(attributes.depthFailColor).toBeUndefined();
        }
      }
      if (options.material instanceof ColorMaterialProperty_default) {
        expect(attributes.color.value).toEqual(
          ColorGeometryInstanceAttribute_default.toValue(
            options.material.color.getValue(time2)
          )
        );
      } else {
        expect(attributes.color).toBeUndefined();
      }
      expect(attributes.show.value).toEqual(
        ShowGeometryInstanceAttribute_default.toValue(options.show)
      );
      if (options.distanceDisplayCondition) {
        expect(attributes.distanceDisplayCondition.value).toEqual(
          DistanceDisplayConditionGeometryInstanceAttribute_default.toValue(
            options.distanceDisplayCondition
          )
        );
      }
    }
