describe("DataSources/PolylineVolumeGraphics", function() {
  it("creates expected instance from raw assignment and construction", function() {
    const options = {
      material: Color_default.BLUE,
      positions: [],
      shape: [],
      show: true,
      granularity: 1,
      fill: false,
      outline: false,
      outlineColor: Color_default.RED,
      outlineWidth: 2,
      cornerType: CornerType_default.BEVELED,
      shadows: ShadowMode_default.DISABLED,
      distanceDisplayCondition: new DistanceDisplayCondition_default()
    };
    const polylineVolume = new PolylineVolumeGraphics_default(options);
    expect(polylineVolume.material).toBeInstanceOf(ColorMaterialProperty_default);
    expect(polylineVolume.positions).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.show).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.shape).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.granularity).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.fill).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.outline).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.outlineColor).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.outlineWidth).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.cornerType).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.shadows).toBeInstanceOf(ConstantProperty_default);
    expect(polylineVolume.distanceDisplayCondition).toBeInstanceOf(
      ConstantProperty_default
    );
    expect(polylineVolume.material.color.getValue()).toEqual(options.material);
    expect(polylineVolume.positions.getValue()).toEqual(options.positions);
    expect(polylineVolume.show.getValue()).toEqual(options.show);
    expect(polylineVolume.shape.getValue()).toEqual(options.shape);
    expect(polylineVolume.granularity.getValue()).toEqual(options.granularity);
    expect(polylineVolume.fill.getValue()).toEqual(options.fill);
    expect(polylineVolume.outline.getValue()).toEqual(options.outline);
    expect(polylineVolume.outlineColor.getValue()).toEqual(
      options.outlineColor
    );
    expect(polylineVolume.outlineWidth.getValue()).toEqual(
      options.outlineWidth
    );
    expect(polylineVolume.cornerType.getValue()).toEqual(options.cornerType);
    expect(polylineVolume.shadows.getValue()).toEqual(options.shadows);
    expect(polylineVolume.distanceDisplayCondition.getValue()).toEqual(
      options.distanceDisplayCondition
    );
  });
  it("merge assigns unassigned properties", function() {
    const source = new PolylineVolumeGraphics_default();
    source.material = new ColorMaterialProperty_default();
    source.positions = new ConstantProperty_default();
    source.show = new ConstantProperty_default();
    source.shape = new ConstantProperty_default();
    source.granularity = new ConstantProperty_default();
    source.fill = new ConstantProperty_default();
    source.outline = new ConstantProperty_default();
    source.outlineColor = new ConstantProperty_default();
    source.outlineWidth = new ConstantProperty_default();
    source.cornerType = new ConstantProperty_default();
    source.shadows = new ConstantProperty_default(ShadowMode_default.ENABLED);
    source.distanceDisplayCondition = new ConstantProperty_default(
      new DistanceDisplayCondition_default()
    );
    const target = new PolylineVolumeGraphics_default();
    target.merge(source);
    expect(target.material).toBe(source.material);
    expect(target.positions).toBe(source.positions);
    expect(target.show).toBe(source.show);
    expect(target.shape).toBe(source.shape);
    expect(target.granularity).toBe(source.granularity);
    expect(target.fill).toBe(source.fill);
    expect(target.outline).toBe(source.outline);
    expect(target.outlineColor).toBe(source.outlineColor);
    expect(target.outlineWidth).toBe(source.outlineWidth);
    expect(target.cornerType).toBe(source.cornerType);
    expect(target.shadows).toBe(source.shadows);
    expect(target.distanceDisplayCondition).toBe(
      source.distanceDisplayCondition
    );
  });
  it("merge does not assign assigned properties", function() {
    const source = new PolylineVolumeGraphics_default();
    const material4 = new ColorMaterialProperty_default();
    const positions = new ConstantProperty_default();
    const show = new ConstantProperty_default();
    const shape = new ConstantProperty_default();
    const granularity = new ConstantProperty_default();
    const fill = new ConstantProperty_default();
    const outline = new ConstantProperty_default();
    const outlineColor = new ConstantProperty_default();
    const outlineWidth = new ConstantProperty_default();
    const cornerType = new ConstantProperty_default();
    const shadows = new ConstantProperty_default();
    const distanceDisplayCondition = new ConstantProperty_default();
    const target = new PolylineVolumeGraphics_default();
    target.material = material4;
    target.positions = positions;
    target.show = show;
    target.shape = shape;
    target.granularity = granularity;
    target.fill = fill;
    target.outline = outline;
    target.outlineColor = outlineColor;
    target.outlineWidth = outlineWidth;
    target.cornerType = cornerType;
    target.shadows = shadows;
    target.distanceDisplayCondition = distanceDisplayCondition;
    target.merge(source);
    expect(target.material).toBe(material4);
    expect(target.positions).toBe(positions);
    expect(target.show).toBe(show);
    expect(target.shape).toBe(shape);
    expect(target.granularity).toBe(granularity);
    expect(target.fill).toBe(fill);
    expect(target.outline).toBe(outline);
    expect(target.outlineColor).toBe(outlineColor);
    expect(target.outlineWidth).toBe(outlineWidth);
    expect(target.cornerType).toBe(cornerType);
    expect(target.shadows).toBe(shadows);
    expect(target.distanceDisplayCondition).toBe(distanceDisplayCondition);
  });
  it("clone works", function() {
    const source = new PolylineVolumeGraphics_default();
    source.material = new ColorMaterialProperty_default();
    source.positions = new ConstantProperty_default();
    source.show = new ConstantProperty_default();
    source.shape = new ConstantProperty_default();
    source.granularity = new ConstantProperty_default();
    source.fill = new ConstantProperty_default();
    source.outline = new ConstantProperty_default();
    source.outlineColor = new ConstantProperty_default();
    source.outlineWidth = new ConstantProperty_default();
    source.cornerType = new ConstantProperty_default();
    source.shadows = new ConstantProperty_default();
    source.distanceDisplayCondition = new ConstantProperty_default();
    const result = source.clone();
    expect(result.material).toBe(source.material);
    expect(result.positions).toBe(source.positions);
    expect(result.show).toBe(source.show);
    expect(result.shape).toBe(source.shape);
    expect(result.granularity).toBe(source.granularity);
    expect(result.fill).toBe(source.fill);
    expect(result.outline).toBe(source.outline);
    expect(result.outlineColor).toBe(source.outlineColor);
    expect(result.outlineWidth).toBe(source.outlineWidth);
    expect(result.cornerType).toBe(source.cornerType);
    expect(result.shadows).toBe(source.shadows);
    expect(result.distanceDisplayCondition).toBe(
      source.distanceDisplayCondition
    );
  });
  it("merge throws if source undefined", function() {
    const target = new PolylineVolumeGraphics_default();
    expect(function() {
      target.merge(void 0);
    }).toThrowDeveloperError();
  });
  it("raises definitionChanged when a property is assigned or modified", function() {
    const property = new PolylineVolumeGraphics_default();
    testMaterialDefinitionChanged_default(property, "material", Color_default.RED, Color_default.BLUE);
    testDefinitionChanged_default(property, "positions", [], []);
    testDefinitionChanged_default(property, "shape", [], []);
    testDefinitionChanged_default(property, "show", true, false);
    testDefinitionChanged_default(property, "granularity", 1, 2);
    testDefinitionChanged_default(property, "fill", false, true);
    testDefinitionChanged_default(property, "outline", true, false);
    testDefinitionChanged_default(property, "outlineColor", Color_default.RED, Color_default.BLUE);
    testDefinitionChanged_default(property, "outlineWidth", 2, 3);
    testDefinitionChanged_default(
      property,
      "cornerType",
      CornerType_default.BEVELED,
      CornerType_default.MITERED
    );
    testDefinitionChanged_default(
      property,
      "shadows",
      ShadowMode_default.ENABLED,
      ShadowMode_default.DISABLED
    );
    testDefinitionChanged_default(
      property,
      "distanceDisplayCondition",
      new DistanceDisplayCondition_default(),
      new DistanceDisplayCondition_default(10, 100)
    );
  });
});

// packages/engine/Specs/DataSources/PositionPropertyArraySpec.js
describe("DataSources/PositionPropertyArray", function() {
  const time2 = JulianDate_default.now();
  it("default constructor sets expected values", function() {
    const property = new PositionPropertyArray_default();
    expect(property.isConstant).toBe(true);
    expect(property.getValue(time2)).toBeUndefined();
  });
  it("constructor sets expected values", function() {
    const expected = [Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Z];
    const value = [
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_X),
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_Z)
    ];
    const property = new PositionPropertyArray_default(value);
    expect(property.getValue(time2)).toEqual(expected);
  });
  it("setValue raises definitionChanged event", function() {
    const property = new PositionPropertyArray_default();
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    property.setValue([]);
    expect(listener).toHaveBeenCalledWith(property);
  });
  it("changing array member raises definitionChanged event", function() {
    const property = new PositionPropertyArray_default();
    const item = new ConstantPositionProperty_default(Cartesian3_default.UNIT_X);
    property.setValue([item]);
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    item.setValue(Cartesian3_default.UNIT_Z);
    expect(listener).toHaveBeenCalledWith(property);
  });
  it("works with result parameter", function() {
    const expected = [Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Z];
    const expectedResult = [];
    const value = [
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_X),
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_Z)
    ];
    const property = new PositionPropertyArray_default(value);
    const result = property.getValue(time2, expectedResult);
    expect(result).toEqual(expected);
    expect(result).toBe(expectedResult);
  });
  it("works with  reference frame parameter", function() {
    const value = [
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_X, ReferenceFrame_default.INERTIAL),
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_Z, ReferenceFrame_default.FIXED)
    ];
    const expected = [
      value[0].getValueInReferenceFrame(time2, ReferenceFrame_default.INERTIAL),
      value[1].getValueInReferenceFrame(time2, ReferenceFrame_default.INERTIAL)
    ];
    const property = new PositionPropertyArray_default(value);
    const result = property.getValueInReferenceFrame(
      time2,
      ReferenceFrame_default.INERTIAL
    );
    expect(result).toEqual(expected);
  });
  it("works with undefined value", function() {
    const property = new PositionPropertyArray_default();
    property.setValue(void 0);
    expect(property.getValue(time2)).toBeUndefined();
  });
  it("works with undefined propertyvalue", function() {
    const property = new PositionPropertyArray_default();
    property.setValue([new ConstantPositionProperty_default()]);
    expect(property.getValue(time2)).toEqual([]);
  });
  it("works with empty array", function() {
    const property = new PositionPropertyArray_default();
    property.setValue([]);
    expect(property.getValue(time2)).toEqual([]);
  });
  it("equals works", function() {
    let left = new PositionPropertyArray_default([
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_X)
    ]);
    let right = new PositionPropertyArray_default([
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_X)
    ]);
    expect(left.equals(right)).toEqual(true);
    right = new PositionPropertyArray_default([
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_Z)
    ]);
    expect(left.equals(right)).toEqual(false);
    left = new PositionPropertyArray_default();
    right = new PositionPropertyArray_default();
    expect(left.equals(right)).toEqual(true);
  });
  it("isConstant is true only if all members are constant", function() {
    const property = new PositionPropertyArray_default();
    property.setValue([new ConstantPositionProperty_default(Cartesian3_default.UNIT_X)]);
    expect(property.isConstant).toBe(true);
    const sampledProperty = new SampledPositionProperty_default();
    sampledProperty.addSample(time2, Cartesian3_default.UNIT_X);
    property.setValue([
      new ConstantPositionProperty_default(Cartesian3_default.UNIT_Z),
      sampledProperty
    ]);
    expect(property.isConstant).toBe(false);
  });
});

