  it("works with material properties", function() {
    const testObject = new Entity_default({
      id: "testId"
    });
    testObject.addProperty("testMaterial");
    testObject.testMaterial = new ColorMaterialProperty_default(Color_default.WHITE);
    const collection = new EntityCollection_default();
    collection.add(testObject);
    let property = ReferenceProperty_default.fromString(
      collection,
      "testId#testMaterial"
    );
    expect(property.isConstant).toEqual(true);
    expect(property.getType(time2)).toEqual(
      testObject.testMaterial.getType(time2)
    );
    expect(property.getValue(time2)).toEqual(
      testObject.testMaterial.getValue(time2)
    );
    property = ReferenceProperty_default.fromString(
      collection,
      "nonExistent#testMaterial"
    );
    expect(property.isConstant).toEqual(true);
    expect(property.referenceFrame).toBeUndefined();
    expect(property.getType(time2)).toBeUndefined();
    expect(property.getValue(time2)).toBeUndefined();
  });
  it("equals works", function() {
    const entityCollection = new EntityCollection_default();
    const left = ReferenceProperty_default.fromString(
      entityCollection,
      "objectId#foo.bar"
    );
    let right = ReferenceProperty_default.fromString(
      entityCollection,
      "objectId#foo.bar"
    );
    expect(left.equals(right)).toEqual(true);
    right = ReferenceProperty_default.fromString(
      new EntityCollection_default(),
      "objectId#foo.bar"
    );
    expect(left.equals(right)).toEqual(false);
    right = ReferenceProperty_default.fromString(
      entityCollection,
      "otherObjectId#foo.bar"
    );
    expect(left.equals(right)).toEqual(false);
    right = ReferenceProperty_default.fromString(entityCollection, "objectId#foo");
    expect(left.equals(right)).toEqual(false);
    right = ReferenceProperty_default.fromString(entityCollection, "objectId#foo.baz");
    expect(left.equals(right)).toEqual(false);
  });
  it("does not raise definition changed when target entity has not changed.", function() {
    const testObject = new Entity_default({
      id: "testId"
    });
    testObject.billboard = new BillboardGraphics_default();
    testObject.billboard.scale = new ConstantProperty_default(5);
    const otherObject = new Entity_default({
      id: "other"
    });
    const collection = new EntityCollection_default();
    collection.add(testObject);
    collection.add(otherObject);
    const property = ReferenceProperty_default.fromString(
      collection,
      "testId#billboard.scale"
    );
    expect(property.resolvedProperty).toBe(testObject.billboard.scale);
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    collection.remove(otherObject);
    expect(listener).not.toHaveBeenCalled();
    collection.remove(testObject);
    expect(listener).not.toHaveBeenCalled();
  });
  it("attaches to a target entity created later", function() {
    const collection = new EntityCollection_default();
    const property = ReferenceProperty_default.fromString(
      collection,
      "testId#billboard.scale"
    );
    expect(property.resolvedProperty).toBeUndefined();
    const listener = jasmine.createSpy("listener");
    property.definitionChanged.addEventListener(listener);
    const otherObject = new Entity_default({
      id: "other"
    });
    collection.add(otherObject);
    expect(listener).not.toHaveBeenCalled();
    expect(property.resolvedProperty).toBeUndefined();
    const testObject = new Entity_default({
      id: "testId"
    });
    testObject.billboard = new BillboardGraphics_default();
    testObject.billboard.scale = new ConstantProperty_default(5);
    collection.add(testObject);
    expect(listener).toHaveBeenCalledWith(property);
    expect(property.resolvedProperty).toBe(testObject.billboard.scale);
  });
