// packages/engine/Specs/DataSources/RotationSpec.js
describe("DataSources/Rotation", function() {
  it("Interpolates towards the closest angle.", function() {
    const time1 = JulianDate_default.fromIso8601("2010-05-07T00:00:00");
    const time2 = JulianDate_default.fromIso8601("2010-05-07T00:01:00");
    const time3 = JulianDate_default.fromIso8601("2010-05-07T00:02:00");
    const time4 = JulianDate_default.fromIso8601("2010-05-07T00:03:00");
    const time5 = JulianDate_default.fromIso8601("2010-05-07T00:04:00");
    const property = new SampledProperty_default(Rotation_default);
    property.addSample(time1, 0);
    property.addSample(time3, Math_default.toRadians(350));
    property.addSample(time5, Math_default.toRadians(10));
    expect(property.getValue(time2)).toEqual(Math_default.toRadians(355));
    expect(property.getValue(time4)).toEqual(0);
  });
  createPackableSpecs_default(Rotation_default, 1, [1]);
});

