    listener.calls.reset();
    property.backwardExtrapolationDuration = 1;
    expect(listener).toHaveBeenCalledWith(property);
    listener.calls.reset();
    property.forwardExtrapolationType = ExtrapolationType_default.EXTRAPOLATE;
    expect(listener).not.toHaveBeenCalled();
    property.forwardExtrapolationDuration = 1;
    expect(listener).not.toHaveBeenCalled();
    property.backwardExtrapolationType = ExtrapolationType_default.HOLD;
