    it("draws with additive blending", function() {
      const cxt = createContext_default({
        webgl: {
          alpha: true
        }
      });
      const vs = "in vec4 position; void main() { gl_PointSize = 1.0; gl_Position = position; }";
      const fs = "void main() { out_FragColor = vec4(0.5); }";
      const sp2 = ShaderProgram_default.fromCache({
        context: cxt,
        vertexShaderSource: vs,
        fragmentShaderSource: fs,
        attributeLocations: {
          position: 0
        }
      });
      const va2 = new VertexArray_default({
        context: cxt,
        attributes: [
          {
            index: 0,
            vertexBuffer: Buffer_default.createVertexBuffer({
              context: cxt,
              typedArray: new Float32Array([0, 0, 0, 1]),
              usage: BufferUsage_default.STATIC_DRAW
            }),
            componentsPerAttribute: 4
          }
        ]
      });
      ClearCommand_default.ALL.execute(cxt);
      expect(cxt).toReadPixels([0, 0, 0, 0]);
      const command = new DrawCommand_default({
        primitiveType: PrimitiveType_default.POINTS,
        shaderProgram: sp2,
        vertexArray: va2,
        renderState: RenderState_default.fromCache({
          blending: {
            enabled: true,
            equationRgb: WebGLConstants_default.FUNC_ADD,
            // Optional, default
            equationAlpha: WebGLConstants_default.FUNC_ADD,
            // Optional, default
            functionSourceRgb: WebGLConstants_default.ONE,
            // Optional, default
            functionSourceAlpha: WebGLConstants_default.ONE,
            // Optional, default
            functionDestinationRgb: WebGLConstants_default.ONE,
            functionDestinationAlpha: WebGLConstants_default.ONE
          }
        })
      });
      command.execute(cxt);
      expect({
        context: cxt,
        epsilon: 1
      }).toReadPixels([127, 127, 127, 127]);
      command.execute(cxt);
      expect({
        context: cxt,
        epsilon: 1
      }).toReadPixels([254, 254, 254, 254]);
      sp2.destroy();
      va2.destroy();
      cxt.destroyForSpecs();
    });
