// packages/engine/Specs/Renderer/MultisampleFramebufferSpec.js
describe(
  "Renderer/MultisampleFramebuffer",
  function() {
    let context;
    let sp;
    let va;
    let framebuffer2;
    beforeAll(function() {
      context = createContext_default();
    });
    afterAll(function() {
      context.destroyForSpecs();
    });
    afterEach(function() {
      sp = sp && sp.destroy();
      va = va && va.destroy();
      framebuffer2 = framebuffer2 && framebuffer2.destroy();
    });
    it("throws when missing a color attachment", function() {
      expect(function() {
        framebuffer2 = new MultisampleFramebuffer_default({
          context,
          width: 1,
          height: 1,
          colorTextures: []
        });
      }).toThrowDeveloperError();
      expect(function() {
        framebuffer2 = new MultisampleFramebuffer_default({
          context,
          width: 1,
          height: 1,
          colorRenderbuffers: []
        });
      }).toThrowDeveloperError();
    });
    it("throws when missing a depth-stencil attachment", function() {
      expect(function() {
        framebuffer2 = new MultisampleFramebuffer_default({
          context,
          width: 1,
          height: 1,
          depthStencilTexture: []
        });
      }).toThrowDeveloperError();
      expect(function() {
        framebuffer2 = new MultisampleFramebuffer_default({
          context,
          width: 1,
          height: 1,
          depthStencilRenderbuffer: []
        });
      }).toThrowDeveloperError();
    });
    it("creates read and draw framebuffers", function() {
      if (!context.depthTexture) {
        return;
      }
      framebuffer2 = new MultisampleFramebuffer_default({
        context,
        width: 1,
        height: 1,
        colorTextures: [
          new Texture_default({
            context,
            width: 1,
            height: 1
          })
        ],
        colorRenderbuffers: [
          new Renderbuffer_default({
            context,
            format: RenderbufferFormat_default.RGBA8
          })
        ],
        depthStencilTexture: new Texture_default({
          context,
          width: 1,
          height: 1,
          pixelFormat: PixelFormat_default.DEPTH_STENCIL,
          pixelDatatype: PixelDatatype_default.UNSIGNED_INT_24_8
        }),
        depthStencilRenderbuffer: new Renderbuffer_default({
          context,
          format: RenderbufferFormat_default.DEPTH_STENCIL
        })
      });
      const readFB = framebuffer2.getRenderFramebuffer();
      const drawFB = framebuffer2.getColorFramebuffer();
      expect(readFB).toBeDefined();
      expect(readFB.getColorRenderbuffer(0)).toBeDefined();
      expect(readFB.depthStencilRenderbuffer).toBeDefined();
      expect(drawFB).toBeDefined();
      expect(drawFB.getColorTexture(0)).toBeDefined();
      expect(drawFB.depthStencilTexture).toBeDefined();
    });
    function renderColor(framebuffer3, color) {
      const vs = "in vec4 position; void main() { gl_PointSize = 1.0; gl_Position = position; }";
      const fs = "uniform vec4 color; void main() { out_FragColor = color; }";
      sp = ShaderProgram_default.fromCache({
        context,
        vertexShaderSource: vs,
        fragmentShaderSource: fs,
        attributeLocations: {
          position: 0
        }
      });
      va = new VertexArray_default({
        context,
        attributes: [
          {
            index: 0,
            vertexBuffer: Buffer_default.createVertexBuffer({
              context,
              typedArray: new Float32Array([0, 0, 0, 1]),
              usage: BufferUsage_default.STATIC_DRAW
            }),
            componentsPerAttribute: 4
          }
        ]
      });
      const uniformMap2 = {
        color: function() {
          return color;
        }
      };
      const command = new DrawCommand_default({
        primitiveType: PrimitiveType_default.POINTS,
        shaderProgram: sp,
        vertexArray: va,
        uniformMap: uniformMap2,
        framebuffer: framebuffer3
      });
      command.execute(context);
    }
    it("blits color attachments", function() {
      if (!context.webgl2) {
        return;
      }
      framebuffer2 = new MultisampleFramebuffer_default({
        context,
        width: 1,
        height: 1,
        colorTextures: [
          new Texture_default({
            context,
            width: 1,
            height: 1
          })
        ],
        colorRenderbuffers: [
          new Renderbuffer_default({
            context,
            format: RenderbufferFormat_default.RGBA8,
            numSamples: 2
          })
        ]
      });
      const renderFB = framebuffer2.getRenderFramebuffer();
      renderColor(renderFB, new Color_default(0, 1, 0, 1));
      framebuffer2.blitFramebuffers(context);
      const colorFB = framebuffer2.getColorFramebuffer();
      expect({
        context,
        framebuffer: colorFB
      }).toReadPixels([0, 255, 0, 255]);
    });
    function renderAndBlitDepthAttachment(framebuffer3) {
      const renderFB = framebuffer3.getRenderFramebuffer();
      const colorFB = framebuffer3.getColorFramebuffer();
      ClearCommand_default.ALL.execute(context);
      const framebufferClear = new ClearCommand_default({
        depth: 1,
        framebuffer: renderFB
      });
      framebufferClear.execute(context);
      const vs = "in vec4 position; void main() { gl_PointSize = 1.0; gl_Position = position; }";
      const fs = "void main() { out_FragColor = vec4(0.0, 1.0, 0.0, 1.0); }";
      sp = ShaderProgram_default.fromCache({
        context,
        vertexShaderSource: vs,
        fragmentShaderSource: fs,
        attributeLocations: {
          position: 0
        }
      });
      va = new VertexArray_default({
        context,
        attributes: [
          {
            index: 0,
            vertexBuffer: Buffer_default.createVertexBuffer({
              context,
              typedArray: new Float32Array([0, 0, 0, 1]),
              usage: BufferUsage_default.STATIC_DRAW
            }),
            componentsPerAttribute: 4
          }
        ]
      });
      let command = new DrawCommand_default({
        primitiveType: PrimitiveType_default.POINTS,
        shaderProgram: sp,
        vertexArray: va,
        framebuffer: renderFB,
        renderState: RenderState_default.fromCache({
          depthTest: {
            enabled: true
          }
        })
      });
      command.execute(context);
      expect(context).toReadPixels([0, 0, 0, 255]);
      framebuffer3.blitFramebuffers(context);
      const vs2 = "in vec4 position; void main() { gl_PointSize = 1.0; gl_Position = position; }";
      const fs2 = "uniform sampler2D u_texture; void main() { out_FragColor = texture(u_texture, vec2(0.0)).rrrr; }";
      const sp2 = ShaderProgram_default.fromCache({
        context,
        vertexShaderSource: vs2,
        fragmentShaderSource: fs2,
        attributeLocations: {
          position: 0
        }
      });
      const uniformMap2 = {
        u_texture: function() {
          return colorFB.depthStencilTexture;
        }
      };
      command = new DrawCommand_default({
        primitiveType: PrimitiveType_default.POINTS,
        shaderProgram: sp2,
        vertexArray: va,
        uniformMap: uniformMap2
      });
      command.execute(context);
      sp2.destroy();
      return context.readPixels();
    }
    it("blits depth-stencil attachments", function() {
      if (!context.webgl2 || !context.depthTexture) {
        return;
      }
      framebuffer2 = new MultisampleFramebuffer_default({
        context,
        width: 1,
        height: 1,
        colorTextures: [
          new Texture_default({
            context,
            width: 1,
            height: 1
          })
        ],
        colorRenderbuffers: [
          new Renderbuffer_default({
            context,
            format: RenderbufferFormat_default.RGBA8,
            numSamples: 2
          })
        ],
        depthStencilTexture: new Texture_default({
          context,
          width: 1,
          height: 1,
          pixelFormat: PixelFormat_default.DEPTH_STENCIL,
          pixelDatatype: PixelDatatype_default.UNSIGNED_INT_24_8
        }),
        depthStencilRenderbuffer: new Renderbuffer_default({
          context,
          width: 1,
          height: 1,
          format: RenderbufferFormat_default.DEPTH24_STENCIL8,
          numSamples: 2
        })
      });
      expect(renderAndBlitDepthAttachment(framebuffer2)).toEqualEpsilon(
        [128, 128, 128, 255],
        1
      );
    });
    it("destroys", function() {
      const f2 = new MultisampleFramebuffer_default({
        context,
        width: 1,
        height: 1
      });
      expect(f2.isDestroyed()).toEqual(false);
      f2.destroy();
      expect(f2.isDestroyed()).toEqual(true);
    });
    it("fails to destroy", function() {
      const f2 = new MultisampleFramebuffer_default({
        context,
        width: 1,
        height: 1
      });
      f2.destroy();
      expect(function() {
        f2.destroy();
      }).toThrowDeveloperError();
    });
    it("throws when there is no context", function() {
      expect(function() {
        return new MultisampleFramebuffer_default();
      }).toThrowDeveloperError();
    });
    it("throws when there is no width or height", function() {
      expect(function() {
        return new MultisampleFramebuffer_default({
          context,
          height: 1
        });
      }).toThrowDeveloperError();
      expect(function() {
        return new MultisampleFramebuffer_default({
          context,
          width: 1
        });
      }).toThrowDeveloperError();
    });
  },
  "WebGL"
);

