      function createRenderResources(texture, textureCoordinates) {
        const x = textureCoordinates.x + textureCoordinates.width / 2;
        const y = textureCoordinates.y + textureCoordinates.height / 2;
        const fs = `${"uniform sampler2D u_texture;void main() {  out_FragColor = texture(u_texture, vec2("}${x}, ${y}));}`;
        const uniformMap2 = {
          u_texture: function() {
            return texture;
          }
        };
        return {
          context: scene2.context,
          fragmentShader: fs,
          uniformMap: uniformMap2
        };
      }
