        dataSource.clock.currentTime = JulianDate_default.fromIso8601("2014-08-02T00:00Z");
        dataSource.clock.clockRange = ClockRange_default.UNBOUNDED;
        dataSource.clock.clockStep = ClockStep_default.SYSTEM_CLOCK_MULTIPLIER;
        dataSource.clock.multiplier = 10;
