    async function loadTimeDynamicPointCloud(widget2) {
      const scene2 = widget2.scene;
      const clock = widget2.clock;
      const uri = "./Data/Cesium3DTiles/PointCloud/PointCloudTimeDynamic/0.pnts";
      const dates = ["2018-07-19T15:18:00Z", "2018-07-19T15:18:00.5Z"];
      function dataCallback() {
        return {
          uri
        };
      }
      const timeIntervalCollection = TimeIntervalCollection_default.fromIso8601DateArray({
        iso8601Dates: dates,
        dataCallback
      });
      const pointCloud = new TimeDynamicPointCloud_default({
        intervals: timeIntervalCollection,
        clock
      });
      const start = JulianDate_default.fromIso8601(dates[0]);
      clock.startTime = start;
      clock.currentTime = start;
      clock.multiplier = 0;
      scene2.primitives.add(pointCloud);
      await pollToPromise_default(function() {
        scene2.render();
        return defined_default(pointCloud.boundingSphere);
      });
      return pointCloud;
    }
