// packages/engine/Specs/Scene/B3dmParserSpec.js
describe(
  "Scene/B3dmParser",
  function() {
    let scene2;
    const centerLongitude = -1.31968;
    const centerLatitude = 0.698874;
    const deprecated1Url = "./Data/Cesium3DTiles/Batched/BatchedDeprecated1/tileset.json";
    const deprecated2Url = "./Data/Cesium3DTiles/Batched/BatchedDeprecated2/tileset.json";
    function setCamera2(longitude, latitude) {
      const center = Cartesian3_default.fromRadians(longitude, latitude);
      scene2.camera.lookAt(center, new HeadingPitchRange_default(0, -1.57, 15));
    }
    beforeAll(function() {
      scene2 = createScene_default();
      spyOn(B3dmParser_default, "_deprecationWarning");
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    beforeEach(function() {
      setCamera2(centerLongitude, centerLatitude);
    });
    afterEach(function() {
      scene2.primitives.removeAll();
    });
    it("throws with invalid version", function() {
      const arrayBuffer = Cesium3DTilesTester_default.generateBatchedTileBuffer({
        version: 2
      });
      expect(function() {
        B3dmParser_default.parse(arrayBuffer);
      }).toThrowError(RuntimeError_default);
    });
    it("throws with empty gltf", function() {
      const arrayBuffer = Cesium3DTilesTester_default.generateBatchedTileBuffer();
      expect(function() {
        B3dmParser_default.parse(arrayBuffer);
      }).toThrowError(RuntimeError_default);
    });
    it("throws on undefined arrayBuffer", function() {
      expect(function() {
        B3dmParser_default.parse(void 0);
      }).toThrowDeveloperError();
    });
    it("recognizes the legacy 20-byte header", function() {
      return Cesium3DTilesTester_default.loadTileset(scene2, deprecated1Url).then(
        function(tileset) {
          expect(B3dmParser_default._deprecationWarning).toHaveBeenCalled();
          Cesium3DTilesTester_default.expectRenderTileset(scene2, tileset);
          const batchTable = tileset.root.content.batchTable;
          expect(batchTable.featuresLength).toBe(10);
        }
      );
    });
    it("recognizes the legacy 24-byte header", function() {
      return Cesium3DTilesTester_default.loadTileset(scene2, deprecated2Url).then(
        function(tileset) {
          expect(B3dmParser_default._deprecationWarning).toHaveBeenCalled();
          Cesium3DTilesTester_default.expectRenderTileset(scene2, tileset);
          const batchTable = tileset.root.content.batchTable;
          expect(batchTable.featuresLength).toBe(10);
        }
      );
    });
    it("logs deprecation warning for use of BATCHID without prefixed underscore", function() {
      return Cesium3DTilesTester_default.loadTileset(scene2, deprecated1Url).then(
        function(tileset) {
          expect(B3dmParser_default._deprecationWarning).toHaveBeenCalled();
          Cesium3DTilesTester_default.expectRenderTileset(scene2, tileset);
        }
      );
    });
  },
  "WebGL"
);

