      it("computes bounding sphere in Columbus view", async function() {
        const projection = scene2.mapProjection;
        const ellipsoid = projection.ellipsoid;
        const one = billboards.add({
          image: greenImage,
          position: Cartesian3_default.fromDegrees(-50, -50)
        });
        const two = billboards.add({
          image: greenImage,
          position: Cartesian3_default.fromDegrees(-50, 50)
        });
        scene2.morphToColumbusView(0);
        await pollToPromise_default(function() {
          scene2.renderForSpecs();
          return one.ready && two.ready;
        });
        billboards.update(scene2.frameState);
        const actual = scene2.frameState.commandList[0].boundingVolume;
        const projectedPositions = [
          projection.project(ellipsoid.cartesianToCartographic(one.position)),
          projection.project(ellipsoid.cartesianToCartographic(two.position))
        ];
        const expected = BoundingSphere_default.fromPoints(projectedPositions);
        expected.center = new Cartesian3_default(
          0,
          expected.center.x,
          expected.center.y
        );
        expect(actual.center).toEqualEpsilon(
          expected.center,
          Math_default.EPSILON8
        );
        expect(actual.radius).toBeGreaterThanOrEqual(expected.radius);
      });
      it("computes bounding sphere in 2D", async function() {
        const projection = scene2.mapProjection;
        const ellipsoid = projection.ellipsoid;
        const one = billboards.add({
          image: greenImage,
          position: Cartesian3_default.fromDegrees(-50, -50)
        });
        const two = billboards.add({
          image: greenImage,
          position: Cartesian3_default.fromDegrees(-50, 50)
        });
        const maxRadii = ellipsoid.maximumRadius;
        const orthoFrustum = new OrthographicOffCenterFrustum_default();
        orthoFrustum.right = maxRadii * Math.PI;
        orthoFrustum.left = -orthoFrustum.right;
        orthoFrustum.top = orthoFrustum.right;
        orthoFrustum.bottom = -orthoFrustum.top;
        orthoFrustum.near = 0.01 * maxRadii;
        orthoFrustum.far = 60 * maxRadii;
        camera.setView({
          destination: Rectangle_default.fromDegrees(-60, -60, -40, 60)
        });
        scene2.morphTo2D(0);
        camera.frustum = orthoFrustum;
        await pollToPromise_default(function() {
          scene2.renderForSpecs();
          return one.ready && two.ready;
        });
        billboards.update(scene2.frameState);
        const actual = scene2.frameState.commandList[0].boundingVolume;
        const projectedPositions = [
          projection.project(ellipsoid.cartesianToCartographic(one.position)),
          projection.project(ellipsoid.cartesianToCartographic(two.position))
        ];
        const expected = BoundingSphere_default.fromPoints(projectedPositions);
        expected.center = new Cartesian3_default(
          0,
          expected.center.x,
          expected.center.y
        );
        expect(actual.center).toEqualEpsilon(
          expected.center,
          Math_default.EPSILON8
        );
        expect(actual.radius).toBeGreaterThan(expected.radius);
      });
      it("computes bounding sphere with pixel offset", async function() {
        const one = billboards.add({
          image: greenImage,
          position: Cartesian3_default.fromDegrees(-50, -50),
          pixelOffset: new Cartesian2_default(0, 200)
        });
        const two = billboards.add({
          image: greenImage,
          position: Cartesian3_default.fromDegrees(-50, 50),
          pixelOffset: new Cartesian2_default(0, 200)
        });
        await pollToPromise_default(function() {
          scene2.renderForSpecs();
          return one.ready && two.ready;
        });
        billboards.update(scene2.frameState);
        const actual = scene2.frameState.commandList[0].boundingVolume;
        const positions = [one.position, two.position];
        const bs = BoundingSphere_default.fromPoints(positions);
        const dimensions = new Cartesian2_default(1, 1);
        const diff = Cartesian3_default.subtract(
          actual.center,
          camera.position,
          new Cartesian3_default()
        );
        const vectorProjection = Cartesian3_default.multiplyByScalar(
          camera.direction,
          Cartesian3_default.dot(diff, camera.direction),
          new Cartesian3_default()
        );
        const distance2 = Math.max(
          0,
          Cartesian3_default.magnitude(vectorProjection) - bs.radius
        );
        const pixelSize = camera.frustum.getPixelDimensions(
          dimensions.x,
          dimensions.y,
          distance2,
          scene2.pixelRatio,
          new Cartesian2_default()
        );
        bs.radius += pixelSize.y * 0.25 * Math.max(greenImage.width, greenImage.height) + pixelSize.y * one.pixelOffset.y;
        expect(actual.center).toEqual(bs.center);
        expect(actual.radius).toEqual(bs.radius);
      });
