      const position = new Cartographic_default();
      camera.position = Cartesian3_default.fromDegrees(10, 45, 1e3);
      const endPosition = Cartesian3_default.fromDegrees(20, 45, 1e3);
      const overLonFlight = CameraFlightPath_default.createTween(scene2, {
        destination: endPosition,
        duration: 1,
        flyOverLongitude: Math_default.toRadians(0)
      });
      const directFlight = CameraFlightPath_default.createTween(scene2, {
        destination: endPosition,
        duration: 1
      });
      expect(typeof overLonFlight.update).toEqual("function");
      expect(typeof directFlight.update).toEqual("function");
      overLonFlight.update({ time: 0.3 });
      projection.ellipsoid.cartesianToCartographic(camera.position, position);
      let lon = Math_default.toDegrees(position.longitude);
      expect(lon).toBeLessThan(10);
      directFlight.update({ time: 0.3 });
      projection.ellipsoid.cartesianToCartographic(camera.position, position);
      lon = Math_default.toDegrees(position.longitude);
      expect(lon).toBeGreaterThan(10);
