  it("get view matrix", function() {
    const viewMatrix = camera.viewMatrix;
    const position2 = camera.position;
    const up2 = camera.up;
    const dir2 = camera.direction;
    const right2 = camera.right;
    const rotation = new Matrix4_default(
      right2.x,
      right2.y,
      right2.z,
      0,
      up2.x,
      up2.y,
      up2.z,
      0,
      -dir2.x,
      -dir2.y,
      -dir2.z,
      0,
      0,
      0,
      0,
      1
    );
    const translation3 = new Matrix4_default(
      1,
      0,
      0,
      -position2.x,
      0,
      1,
      0,
      -position2.y,
      0,
      0,
      1,
      -position2.z,
      0,
      0,
      0,
      1
    );
    const expected = Matrix4_default.multiply(rotation, translation3, new Matrix4_default());
    expect(viewMatrix).toEqual(expected);
  });
