  it("move clamps position in 2D", function() {
    const frustum = new OrthographicOffCenterFrustum_default();
    frustum.near = 1;
    frustum.far = 2;
    frustum.left = -2;
    frustum.right = 2;
    frustum.top = 1;
    frustum.bottom = -1;
    camera.frustum = frustum;
    camera.update(SceneMode_default.SCENE2D);
    const max3 = scene2.mapProjection.project(
      new Cartographic_default(Math.PI, Math_default.toRadians(85.05112878))
    );
    const factor2 = 1e3;
    const dx = max3.x * factor2;
    const dy = max3.y * factor2;
    camera.moveUp(dy);
    camera.moveRight(dx);
    expect(camera.position.x).toBeLessThan(dx);
    expect(camera.position.y).toBeLessThan(dy);
    camera.moveDown(dy);
    camera.moveLeft(dx);
    expect(camera.position.x).toBeGreaterThan(-dx);
    expect(camera.position.y).toBeGreaterThan(-dy);
  });
