  it("lookAtTransform in 2D mode", function() {
    const frustum = new OrthographicOffCenterFrustum_default();
    frustum.near = 1;
    frustum.far = 2;
    frustum.left = -2;
    frustum.right = 2;
    frustum.top = 1;
    frustum.bottom = -1;
    const tempCamera = Camera_default.clone(camera);
    tempCamera.frustum = frustum;
    tempCamera.update(SceneMode_default.SCENE2D);
    const transform3 = FixedFrameTransforms_default.eastNorthUpToFixedFrame(
      Cartesian3_default.fromDegrees(0, 0)
    );
    const offset = new Cartesian3_default(1e4, 1e4, 3e4);
    tempCamera.lookAtTransform(transform3, offset);
    expect(Cartesian2_default.clone(tempCamera.position)).toEqual(Cartesian2_default.ZERO);
    expect(tempCamera.direction).toEqual(
      Cartesian3_default.negate(Cartesian3_default.UNIT_Z, new Cartesian3_default())
    );
    expect(tempCamera.up).toEqualEpsilon(
      Cartesian3_default.normalize(
        Cartesian3_default.fromElements(-offset.x, -offset.y, 0),
        new Cartesian3_default()
      ),
      Math_default.EPSILON11
    );
    expect(tempCamera.right).toEqualEpsilon(
      Cartesian3_default.cross(tempCamera.direction, tempCamera.up, new Cartesian3_default()),
      Math_default.EPSILON11
    );
    expect(tempCamera.frustum.right).toEqual(
      Cartesian3_default.magnitude(offset) * 0.5
    );
    expect(tempCamera.frustum.left).toEqual(
      -Cartesian3_default.magnitude(offset) * 0.5
    );
  });
