  it("setView rectangle in 2D with larger longitude", function() {
    const frustum = new OrthographicOffCenterFrustum_default();
    frustum.left = -10;
    frustum.right = 10;
    frustum.bottom = -10;
    frustum.top = 10;
    frustum.near = 1;
    frustum.far = 21;
    camera.frustum = frustum;
    const rectangle = new Rectangle_default(
      -Math_default.PI_OVER_TWO,
      -Math_default.PI_OVER_FOUR,
      Math_default.PI_OVER_TWO,
      Math_default.PI_OVER_FOUR
    );
    const projection = new GeographicProjection_default();
    const edge = projection.project(
      new Cartographic_default(Math_default.PI_OVER_TWO, Math_default.PI_OVER_FOUR)
    );
    const expected = Math.max(edge.x, edge.y);
    camera._mode = SceneMode_default.SCENE2D;
    camera._projection = projection;
    camera.setView({ destination: rectangle });
    expect(camera.position.x).toEqual(0);
    expect(camera.position.y).toEqual(0);
    expect(frustum.right - expected <= Math_default.EPSILON14).toEqual(true);
    expect(frustum.left + expected <= Math_default.EPSILON14).toEqual(true);
    expect(frustum.top - expected <= Math_default.EPSILON14).toEqual(true);
    expect(frustum.bottom + expected <= Math_default.EPSILON14).toEqual(true);
  });
