  it("pick ellipsoid", function() {
    const ellipsoid = Ellipsoid_default.WGS84;
    const maxRadii = ellipsoid.maximumRadius;
    camera.position = Cartesian3_default.multiplyByScalar(
      Cartesian3_default.UNIT_X,
      2 * maxRadii,
      new Cartesian3_default()
    );
    camera.direction = Cartesian3_default.normalize(
      Cartesian3_default.negate(camera.position, new Cartesian3_default()),
      new Cartesian3_default()
    );
    camera.up = Cartesian3_default.clone(Cartesian3_default.UNIT_Z);
    camera.right = Cartesian3_default.cross(
      camera.direction,
      camera.up,
      new Cartesian3_default()
    );
    const frustum = new PerspectiveFrustum_default();
    frustum.fov = Math_default.toRadians(60);
    frustum.aspectRatio = scene2.drawingBufferWidth / scene2.drawingBufferHeight;
    frustum.near = 100;
    frustum.far = 60 * maxRadii;
    camera.frustum = frustum;
    const windowCoord = new Cartesian2_default(
      scene2.canvas.clientWidth * 0.5,
      scene2.canvas.clientHeight * 0.5
    );
    let p2 = camera.pickEllipsoid(windowCoord, ellipsoid);
    const c = ellipsoid.cartesianToCartographic(p2);
    expect(c).toEqual(new Cartographic_default(0, 0, 0));
    p2 = camera.pickEllipsoid(Cartesian2_default.ZERO, ellipsoid);
    expect(p2).toBeUndefined();
  });
