  it("animates position to visible map in Columbus view", function() {
    const maxRadii = Ellipsoid_default.WGS84.maximumRadius;
    const frustum = new PerspectiveFrustum_default();
    frustum.fov = Math_default.toRadians(60);
    frustum.aspectRatio = scene2.drawingBufferWidth / scene2.drawingBufferHeight;
    frustum.near = 100;
    frustum.far = 60 * maxRadii;
    camera.frustum = frustum;
    camera.position = Cartesian3_default.multiplyByScalar(
      Cartesian3_default.UNIT_Z,
      maxRadii * 5,
      new Cartesian3_default()
    );
    camera.update(SceneMode_default.COLUMBUS_VIEW);
    const max3 = scene2.mapProjection.project(
      new Cartographic_default(Math.PI, Math_default.PI_OVER_TWO)
    );
    const factor2 = 1e3;
    const dx = max3.x * factor2;
    const dy = max3.y * factor2;
    const tweens = new TweenCollection_default();
    camera.moveUp(dy);
    camera.moveRight(dx);
    let correctAnimation = camera.createCorrectPositionTween(0.05);
    expect(correctAnimation).toBeDefined();
    let animation = tweens.add(correctAnimation);
    while (tweens.contains(animation)) {
      tweens.update();
    }
    expect(camera.position.x).toEqualEpsilon(max3.x, Math_default.EPSILON6);
    expect(camera.position.y).toEqualEpsilon(max3.y, Math_default.EPSILON6);
    camera.moveDown(dy);
    camera.moveLeft(dx);
    correctAnimation = camera.createCorrectPositionTween(0.05);
    expect(correctAnimation).toBeDefined();
    animation = tweens.add(correctAnimation);
    while (tweens.contains(animation)) {
      tweens.update();
    }
    expect(camera.position.x).toEqualEpsilon(-max3.x, Math_default.EPSILON6);
    expect(camera.position.y).toEqualEpsilon(-max3.y, Math_default.EPSILON6);
  });
