// Specs/concatTypedArrays.js
function concatTypedArrays(arrays) {
  let i;
  const length3 = arrays.length;
  let byteLength = 0;
  for (i = 0; i < length3; ++i) {
    byteLength += arrays[i].byteLength;
  }
  const buffer3 = new Uint8Array(byteLength);
  let byteOffset = 0;
  for (i = 0; i < length3; ++i) {
    const array = arrays[i];
    const data = new Uint8Array(
      array.buffer,
      array.byteOffset,
      array.byteLength
    );
    buffer3.set(data, byteOffset);
    byteOffset += data.length;
  }
  return buffer3;
}
var concatTypedArrays_default = concatTypedArrays;

