// packages/engine/Specs/Scene/Cesium3DTileFeatureTableSpec.js
describe("Scene/Cesium3DTileFeatureTable", function() {
  it("loads from JSON", function() {
    const featureTable = new Cesium3DTileFeatureTable_default({
      TEST: [0, 1, 2, 3, 4, 5]
    });
    featureTable.featuresLength = 3;
    expect(featureTable.hasProperty("TEST")).toBe(true);
    const all = featureTable.getGlobalProperty(
      "TEST",
      ComponentDatatype_default.UNSIGNED_BYTE
    );
    expect(all).toEqual([0, 1, 2, 3, 4, 5]);
    const feature2 = featureTable.getProperty(
      "TEST",
      ComponentDatatype_default.UNSIGNED_BYTE,
      2,
      1,
      new Array(2)
    );
    expect(feature2).toEqual([2, 3]);
    const properties = featureTable.getPropertyArray(
      "TEST",
      ComponentDatatype_default.UNSIGNED_BYTE,
      2
    );
    expect(properties).toEqual([0, 1, 2, 3, 4, 5]);
  });
  it("loads from binary", function() {
    const featureTable = new Cesium3DTileFeatureTable_default(
      {
        TEST: {
          byteOffset: 4
        }
      },
      new Uint8Array([0, 0, 0, 0, 0, 1, 2, 3, 4, 5])
    );
    featureTable.featuresLength = 3;
    expect(featureTable.hasProperty("TEST")).toBe(true);
    const all = featureTable.getGlobalProperty(
      "TEST",
      ComponentDatatype_default.UNSIGNED_BYTE,
      6
    );
    expect(all).toEqual([0, 1, 2, 3, 4, 5]);
    const feature2 = featureTable.getProperty(
      "TEST",
      ComponentDatatype_default.UNSIGNED_BYTE,
      2,
      1,
      new Array(2)
    );
    expect(feature2).toEqual([2, 3]);
    const properties = featureTable.getPropertyArray(
      "TEST",
      ComponentDatatype_default.UNSIGNED_BYTE,
      2
    );
    expect(properties).toEqual([0, 1, 2, 3, 4, 5]);
  });
});

// packages/engine/Specs/Scene/Cesium3DTilePassStateSpec.js
describe("Scene/Cesium3DTilePassState", function() {
  it("sets default values", function() {
    const passState = new Cesium3DTilePassState_default({
      pass: Cesium3DTilePass_default.RENDER
    });
    expect(passState.pass).toBe(Cesium3DTilePass_default.RENDER);
    expect(passState.commandList).toBeUndefined();
    expect(passState.camera).toBeUndefined();
    expect(passState.cullingVolume).toBeUndefined();
    expect(passState.ready).toBe(false);
  });
  it("constructed with options", function() {
    const mockCommandList = [];
    const mockCamera = {};
    const mockCullingVolume = {};
    const passState = new Cesium3DTilePassState_default({
      pass: Cesium3DTilePass_default.RENDER,
      commandList: mockCommandList,
      camera: mockCamera,
      cullingVolume: mockCullingVolume
    });
    expect(passState.pass).toBe(Cesium3DTilePass_default.RENDER);
    expect(passState.commandList).toBe(mockCommandList);
    expect(passState.camera).toBe(mockCamera);
    expect(passState.cullingVolume).toBe(mockCullingVolume);
  });
  it("throws if options is undefined", function() {
    expect(function() {
      return new Cesium3DTilePassState_default();
    }).toThrowDeveloperError();
  });
  it("throws if options.pass is undefined", function() {
    expect(function() {
      return new Cesium3DTilePassState_default({});
    }).toThrowDeveloperError();
  });
});

