// Specs/generateJsonBuffer.js
function generateJsonBuffer(json, byteOffset, boundary) {
  let i;
  const jsonString = JSON.stringify(json);
  byteOffset = byteOffset ?? 0;
  boundary = boundary ?? 1;
  const byteLength = jsonString.length;
  const remainder = (byteOffset + byteLength) % boundary;
  const padding = remainder === 0 ? 0 : boundary - remainder;
  const buffer3 = new Uint8Array(byteLength + padding);
  for (i = 0; i < byteLength; ++i) {
    buffer3[i] = jsonString.charCodeAt(i);
  }
  for (i = 0; i < padding; ++i) {
    buffer3[byteLength + i] = 32;
  }
  return buffer3;
}
var generateJsonBuffer_default = generateJsonBuffer;

