    it("verify memory usage statistics", async function() {
      const singleTileGeometryMemory = 7440;
      const singleTileTextureMemory = 0;
      const singleTileBatchTextureMemory = 40;
      const singleTilePickTextureMemory = 40;
      const tilesLength = 5;
      viewNothing();
      const tileset = await Cesium3DTilesTester_default.loadTileset(scene2, tilesetUrl);
      const statistics2 = tileset._statistics;
      expect(statistics2.geometryByteLength).toEqual(0);
      expect(statistics2.texturesByteLength).toEqual(0);
      expect(statistics2.batchTableByteLength).toEqual(0);
      viewRootOnly();
      await Cesium3DTilesTester_default.waitForTilesLoaded(scene2, tileset);
      expect(statistics2.geometryByteLength).toEqual(singleTileGeometryMemory);
      expect(statistics2.texturesByteLength).toEqual(singleTileTextureMemory);
      expect(statistics2.batchTableByteLength).toEqual(0);
      viewAllTiles();
      await Cesium3DTilesTester_default.waitForTilesLoaded(scene2, tileset);
      expect(statistics2.geometryByteLength).toEqual(
        singleTileGeometryMemory * tilesLength
      );
      expect(statistics2.texturesByteLength).toEqual(
        singleTileTextureMemory * tilesLength
      );
      expect(statistics2.batchTableByteLength).toEqual(0);
      tileset.root.content.getFeature(0).color = Color_default.RED;
      scene2.renderForSpecs();
      expect(statistics2.geometryByteLength).toEqual(
        singleTileGeometryMemory * tilesLength
      );
      expect(statistics2.texturesByteLength).toEqual(
        singleTileTextureMemory * tilesLength
      );
      expect(statistics2.batchTableByteLength).toEqual(
        singleTileBatchTextureMemory
      );
      scene2.pickForSpecs();
      expect(statistics2.geometryByteLength).toEqual(
        singleTileGeometryMemory * tilesLength
      );
      expect(statistics2.texturesByteLength).toEqual(
        singleTileTextureMemory * tilesLength
      );
      expect(statistics2.batchTableByteLength).toEqual(
        singleTileBatchTextureMemory + singleTilePickTextureMemory * tilesLength
      );
      viewNothing();
      scene2.renderForSpecs();
      expect(statistics2.geometryByteLength).toEqual(
        singleTileGeometryMemory * tilesLength
      );
      expect(statistics2.texturesByteLength).toEqual(
        singleTileTextureMemory * tilesLength
      );
      expect(statistics2.batchTableByteLength).toEqual(
        singleTileBatchTextureMemory + singleTilePickTextureMemory * tilesLength
      );
      tileset.trimLoadedTiles();
      scene2.renderForSpecs();
      expect(statistics2.geometryByteLength).toEqual(0);
      expect(statistics2.texturesByteLength).toEqual(0);
      expect(statistics2.batchTableByteLength).toEqual(0);
    });
