    function numberOfChildrenWithoutContent(tile) {
      const children = tile.children;
      const length3 = children.length;
      let count = 0;
      for (let i = 0; i < length3; ++i) {
        const child = children[i];
        if (!child.contentReady) {
          ++count;
        }
      }
      return count;
    }
