    it("propagates tile transform down the tree", async function() {
      const b3dmCommands = 1;
      const i3dmCommands = scene2.context.instancedArrays ? 1 : 25;
      const totalCommands = b3dmCommands + i3dmCommands;
      const tileset = await Cesium3DTilesTester_default.loadTileset(
        scene2,
        tilesetWithTransformsUrl
      );
      const statistics2 = tileset._statistics;
      const root = tileset.root;
      const rootTransform = Matrix4_default.unpack(root._header.transform);
      const child = root.children[0];
      const childTransform = Matrix4_default.unpack(child._header.transform);
      let computedTransform = Matrix4_default.multiply(
        rootTransform,
        childTransform,
        new Matrix4_default()
      );
      expect(statistics2.numberOfCommands).toBe(totalCommands);
      expect(root.computedTransform).toEqual(rootTransform);
      expect(child.computedTransform).toEqual(computedTransform);
      const tilesetTransform = Matrix4_default.fromTranslation(
        new Cartesian3_default(0, 1, 0)
      );
      tileset.modelMatrix = tilesetTransform;
      computedTransform = Matrix4_default.multiply(
        tilesetTransform,
        computedTransform,
        computedTransform
      );
      scene2.renderForSpecs();
      expect(child.computedTransform).toEqual(computedTransform);
      tileset.modelMatrix = Matrix4_default.fromTranslation(
        new Cartesian3_default(0, 1e5, 0)
      );
      scene2.renderForSpecs();
      expect(statistics2.numberOfCommands).toBe(0);
      tileset.modelMatrix = Matrix4_default.IDENTITY;
      scene2.renderForSpecs();
      expect(statistics2.numberOfCommands).toBe(totalCommands);
      child.transform = Matrix4_default.fromTranslation(
        new Cartesian3_default(0, 1e5, 0)
      );
      scene2.renderForSpecs();
      expect(statistics2.numberOfCommands).toBe(1);
      child.transform = Matrix4_default.IDENTITY;
      scene2.renderForSpecs();
      expect(statistics2.numberOfCommands).toBe(totalCommands);
    });
