        expect(statistics2.numberOfAttemptedRequests).toBe(0);
        expect(statistics2.numberOfPendingRequests).toBe(3);
        expect(statistics2.numberOfTilesProcessing).toBe(0);
        expect(statistics2.numberOfTilesWithContentReady).toBe(0);
        await pollToPromise_default(() => {
          scene2.renderForSpecs();
          return tileset.root._contentState === Cesium3DTileContentState_default.PROCESSING;
        });
        expect(statistics2.numberOfAttemptedRequests).toBe(0);
        expect(statistics2.numberOfPendingRequests).toBe(0);
        expect(statistics2.numberOfTilesProcessing).toBe(1);
        expect(statistics2.numberOfTilesWithContentReady).toBe(0);
        await Cesium3DTilesTester_default.waitForTilesLoaded(scene2, tileset);
        expect(statistics2.numberOfAttemptedRequests).toBe(0);
        expect(statistics2.numberOfPendingRequests).toBe(0);
        expect(statistics2.numberOfTilesProcessing).toBe(0);
        expect(statistics2.numberOfTilesWithContentReady).toBe(1);
