    expect(intersect2).toEqual(Intersect_default.INSIDE);
    clippingPlanes.add(new ClippingPlane_default(Cartesian3_default.UNIT_Z, 1));
    intersect2 = clippingPlanes.computeIntersectionWithBoundingVolume(boundingVolume);
    expect(intersect2).toEqual(Intersect_default.INSIDE);
    const temp = new ClippingPlane_default(Cartesian3_default.UNIT_Y, -2);
    clippingPlanes.add(temp);
    intersect2 = clippingPlanes.computeIntersectionWithBoundingVolume(boundingVolume);
    expect(intersect2).toEqual(Intersect_default.OUTSIDE);
    clippingPlanes.add(new ClippingPlane_default(Cartesian3_default.UNIT_X, 0));
    intersect2 = clippingPlanes.computeIntersectionWithBoundingVolume(boundingVolume);
    expect(intersect2).toEqual(Intersect_default.OUTSIDE);
    clippingPlanes.remove(temp);
    intersect2 = clippingPlanes.computeIntersectionWithBoundingVolume(boundingVolume);
    expect(intersect2).toEqual(Intersect_default.INTERSECTING);
