// packages/engine/Specs/Scene/DebugCameraPrimitiveSpec.js
describe(
  "Scene/DebugCameraPrimitive",
  function() {
    let scene2;
    let camera;
    beforeAll(function() {
      scene2 = createScene_default({
        scene3DOnly: true
      });
      scene2.camera.position = new Cartesian3_default(0, 0, 0);
      scene2.camera.direction = Cartesian3_default.negate(
        Cartesian3_default.UNIT_X,
        new Cartesian3_default()
      );
      scene2.camera.up = Cartesian3_default.clone(Cartesian3_default.UNIT_Z);
      scene2.camera.frustum.near = 1;
      scene2.camera.frustum.far = 500;
      camera = Camera_default.clone(scene2.camera);
      scene2.camera.zoomOut(1);
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    afterEach(function() {
      scene2.primitives.removeAll();
    });
    it("throws if options.camera is undefined", function() {
      expect(function() {
        return new DebugCameraPrimitive_default();
      }).toThrowDeveloperError();
    });
    it("gets the default properties", function() {
      const p2 = new DebugCameraPrimitive_default({
        camera
      });
      expect(p2.show).toEqual(true);
      expect(p2.id).not.toBeDefined();
      p2.destroy();
    });
    it("constructs with options", function() {
      const p2 = new DebugCameraPrimitive_default({
        camera,
        frustumSplits: [0.1, 1e3],
        color: Color_default.YELLOW,
        updateOnChange: false,
        show: false,
        id: "id"
      });
      expect(p2.show).toEqual(false);
      expect(p2.id).toEqual("id");
      p2.destroy();
    });
    it("renders", function() {
      scene2.primitives.add(
        new DebugCameraPrimitive_default({
          camera
        })
      );
      expect(scene2).notToRender([0, 0, 0, 255]);
    });
    it("does not render when show is false", function() {
      scene2.primitives.add(
        new DebugCameraPrimitive_default({
          camera,
          show: false
        })
      );
      expect(scene2).toRender([0, 0, 0, 255]);
    });
    it("updates when underlying camera changes", function() {
      const p2 = scene2.primitives.add(
        new DebugCameraPrimitive_default({
          camera
        })
      );
      scene2.renderForSpecs();
      const primitive = p2._outlinePrimitives[0];
      scene2.renderForSpecs();
      expect(p2._outlinePrimitives[0]).not.toBe(primitive);
    });
    it("does not update when updateOnChange is false", function() {
      const p2 = scene2.primitives.add(
        new DebugCameraPrimitive_default({
          camera,
          updateOnChange: false
        })
      );
      scene2.renderForSpecs();
      const primitive = p2._primitive;
      scene2.renderForSpecs();
      expect(p2._primitive).toBe(primitive);
    });
    it("is picked", function() {
      const p2 = scene2.primitives.add(
        new DebugCameraPrimitive_default({
          camera,
          id: "id"
        })
      );
      expect(scene2).toPickAndCall(function(result) {
        expect(result.primitive).toBe(p2);
        expect(result.id).toBe("id");
      });
    });
    it("isDestroyed", function() {
      const p2 = scene2.primitives.add(
        new DebugCameraPrimitive_default({
          camera
        })
      );
      expect(p2.isDestroyed()).toEqual(false);
      scene2.primitives.remove(p2);
      expect(p2.isDestroyed()).toEqual(true);
    });
  },
  "WebGL"
);

