// packages/engine/Specs/Scene/DeviceOrientationCameraControllerSpec.js
describe("Scene/DeviceOrientationCameraController", function() {
  let scene2;
  let canvas;
  let camera;
  let controller;
  function MockScene2(canvas2, camera2) {
    this.canvas = canvas2;
    this.camera = camera2;
  }
  beforeAll(function() {
    canvas = createCanvas_default();
  });
  afterAll(function() {
    document.body.removeChild(canvas);
  });
  beforeEach(function() {
    camera = createCamera_default({
      canvas,
      offset: new Cartesian3_default(-1, 0, 0)
    });
    scene2 = new MockScene2(canvas, camera);
    controller = new DeviceOrientationCameraController_default(scene2);
  });
  afterEach(function() {
    controller = controller && !controller.isDestroyed() && controller.destroy();
  });
  function fireEvent(options) {
    DomEventSimulator_default.fireDeviceOrientation(window);
    controller.update();
    DomEventSimulator_default.fireDeviceOrientation(window, options);
    controller.update();
  }
  it("throws without scene", function() {
    expect(function() {
      return new DeviceOrientationCameraController_default();
    }).toThrowDeveloperError();
  });
  it("rotates for alpha", function() {
    const position = Cartesian3_default.clone(camera.position);
    const up = Cartesian3_default.clone(camera.up);
    fireEvent({
      alpha: 90
    });
    expect(camera.position).toEqual(position);
    expect(camera.direction).toEqualEpsilon(
      Cartesian3_default.UNIT_Y,
      Math_default.EPSILON14
    );
    expect(camera.up).toEqualEpsilon(up, Math_default.EPSILON14);
    expect(camera.right).toEqualEpsilon(
      Cartesian3_default.UNIT_X,
      Math_default.EPSILON14
    );
  });
  it("rotates for beta", function() {
    const position = Cartesian3_default.clone(camera.position);
    const direction2 = Cartesian3_default.clone(camera.direction);
    fireEvent({
      beta: 90
    });
    expect(camera.position).toEqual(position);
    expect(camera.direction).toEqualEpsilon(direction2, Math_default.EPSILON14);
    expect(camera.up).toEqualEpsilon(Cartesian3_default.UNIT_Y, Math_default.EPSILON14);
    expect(camera.right).toEqualEpsilon(
      Cartesian3_default.UNIT_Z,
      Math_default.EPSILON14
    );
  });
  it("rotates for gamma", function() {
    const position = Cartesian3_default.clone(camera.position);
    const right = Cartesian3_default.clone(camera.right);
    fireEvent({
      gamma: 90
    });
    expect(camera.position).toEqual(position);
    expect(camera.direction).toEqualEpsilon(
      Cartesian3_default.negate(Cartesian3_default.UNIT_Z, new Cartesian3_default()),
      Math_default.EPSILON14
    );
    expect(camera.up).toEqualEpsilon(Cartesian3_default.UNIT_X, Math_default.EPSILON14);
    expect(camera.right).toEqualEpsilon(right, Math_default.EPSILON14);
  });
  it("is destroyed", function() {
    expect(controller.isDestroyed()).toEqual(false);
    controller.destroy();
    expect(controller.isDestroyed()).toEqual(true);
  });
});

