// packages/engine/Specs/Scene/FogSpec.js
describe("Fog", () => {
  describe("update", () => {
    let scene2;
    let fog;
    beforeEach(() => {
      fog = new Fog_default();
      scene2 = createScene_default();
    });
    afterEach(function() {
      scene2.destroyForSpecs();
    });
    it("disabled when above max height", () => {
      fog.maxHeight = 8e5;
      const frameState2 = scene2.frameState;
      frameState2.camera.positionCartographic.height = 800001;
      fog.update(frameState2);
      expect(frameState2.fog.enabled).withContext(`at height 800001`).toBeFalse();
      frameState2.camera.positionCartographic.height = 5e3;
      fog.update(frameState2);
      expect(frameState2.fog.enabled).withContext(`at height 5000`).toBeTrue();
      fog.maxHeight = 5e3;
      frameState2.camera.positionCartographic.height = 5001;
      fog.update(frameState2);
      expect(frameState2.fog.enabled).withContext(`at height 5001`).toBeFalse();
      frameState2.camera.positionCartographic.height = 4e3;
      fog.update(frameState2);
      expect(frameState2.fog.enabled).withContext(`at height 4000`).toBeTrue();
    });
    it("passes through expected values unaltered", () => {
      fog.screenSpaceErrorFactor = 11;
      fog.visualDensityScalar = 12;
      fog.minimumBrightness = 13;
      const frameState2 = scene2.frameState;
      frameState2.camera.positionCartographic.height = 1e4;
      fog.update(frameState2);
      console.log(frameState2);
      expect(frameState2.fog.enabled).toBeTrue();
      expect(frameState2.fog.density).toBeGreaterThan(0);
      expect(frameState2.fog.sse).toEqual(11);
      expect(frameState2.fog.visualDensityScalar).toEqual(12);
      expect(frameState2.fog.minimumBrightness).toEqual(13);
    });
    it("density is 0 when not in 3D", () => {
      const frameState2 = scene2.frameState;
      frameState2.mode = SceneMode_default.SCENE2D;
      fog.update(frameState2);
      expect(frameState2.fog.density).toEqual(0);
    });
    describe("density function", () => {
      beforeEach(() => {
        fog = new Fog_default();
      });
      it("density is 0 above max height", () => {
        fog.maxHeight = 8e5;
        const frameState2 = scene2.frameState;
        frameState2.camera.positionCartographic.height = 800001;
        fog.update(frameState2);
        expect(frameState2.fog.density).withContext(`at height 800001`).toEqual(0);
        frameState2.camera.positionCartographic.height = 5e3;
        fog.update(frameState2);
        expect(frameState2.fog.density).withContext(`at height 5000`).not.toEqual(0);
        fog.maxHeight = 5e3;
        frameState2.camera.positionCartographic.height = 5001;
        fog.update(frameState2);
        expect(frameState2.fog.density).withContext(`at height 5001`).toEqual(0);
        frameState2.camera.positionCartographic.height = 4e3;
        fog.update(frameState2);
        expect(frameState2.fog.density).withContext(`at height 4000`).not.toEqual(0);
      });
      function testDensityAtHeight(height, expectedDensity, epsilon = Math_default.EPSILON5) {
        const frameState2 = scene2.frameState;
        frameState2.camera.positionCartographic.height = height;
        fog.update(frameState2);
        expect(frameState2.fog.density).withContext(`at height ${height}`).toEqualEpsilon(expectedDensity, epsilon);
      }
      it("default density, underground", () => {
        testDensityAtHeight(-1, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(-10, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(-100, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(-1e3, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(-1e4, 17e-11, Math_default.EPSILON11);
      });
      it("default density, close to the ground", () => {
        testDensityAtHeight(1, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(10, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(20, 17e-11, Math_default.EPSILON11);
        testDensityAtHeight(50, 17e-11, Math_default.EPSILON11);
      });
      it("default density, mid heights", () => {
        testDensityAtHeight(100, 15e-11, Math_default.EPSILON11);
        testDensityAtHeight(1e3, 39e-12, Math_default.EPSILON12);
        testDensityAtHeight(2e3, 25e-12, Math_default.EPSILON12);
        testDensityAtHeight(5e3, 15e-12, Math_default.EPSILON12);
      });
      it("default density, high heights", () => {
        testDensityAtHeight(1e4, 1e-11, Math_default.EPSILON12);
        testDensityAtHeight(1e5, 25e-13, Math_default.EPSILON13);
        testDensityAtHeight(2e5, 17e-13, Math_default.EPSILON13);
        testDensityAtHeight(5e5, 99e-14, Math_default.EPSILON14);
      });
      it("higher density, close to the ground", () => {
        fog.density = 5e-3;
        testDensityAtHeight(1, 14e-10, Math_default.EPSILON10);
        testDensityAtHeight(10, 14e-10, Math_default.EPSILON10);
        testDensityAtHeight(20, 14e-10, Math_default.EPSILON10);
        testDensityAtHeight(50, 14e-10, Math_default.EPSILON10);
      });
      it("higher density, mid heights", () => {
        fog.density = 5e-3;
        testDensityAtHeight(100, 12e-10, Math_default.EPSILON10);
        testDensityAtHeight(1e3, 32e-11, Math_default.EPSILON11);
        testDensityAtHeight(2e3, 21e-11, Math_default.EPSILON11);
        testDensityAtHeight(5e3, 12e-11, Math_default.EPSILON11);
      });
      it("higher density, high heights", () => {
        fog.density = 5e-3;
        testDensityAtHeight(1e4, 83e-12, Math_default.EPSILON12);
        testDensityAtHeight(1e5, 21e-12, Math_default.EPSILON12);
        testDensityAtHeight(2e5, 14e-12, Math_default.EPSILON12);
        testDensityAtHeight(5e5, 83e-13, Math_default.EPSILON13);
      });
      it("heightScalar directly affects density", () => {
        fog.heightScalar = 1;
        testDensityAtHeight(1e3, 39e-9, Math_default.EPSILON9);
        fog.heightScalar = 2;
        testDensityAtHeight(1e3, 39e-9 * 2, Math_default.EPSILON9);
      });
    });
  });
});

// packages/engine/Specs/Scene/FrameRateMonitorSpec.js
describe(
  "Scene/FrameRateMonitor",
  function() {
    let scene2;
    beforeAll(function() {
      scene2 = createScene_default();
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    let monitor;
    afterEach(function() {
      if (defined_default(monitor)) {
        monitor.destroy();
        monitor = void 0;
      }
    });
    function spinWait(milliseconds) {
      const endTime = getTimestamp_default() + milliseconds;
      while (getTimestamp_default() < endTime) {
      }
    }
    it("throws when constructed without a scene", function() {
      expect(function() {
        monitor = new FrameRateMonitor_default();
      }).toThrowDeveloperError();
      expect(function() {
        monitor = new FrameRateMonitor_default({});
      }).toThrowDeveloperError();
    });
    it("can be constructed with just a scene", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2
      });
      expect(monitor.samplingWindow).toBe(5);
      expect(monitor.quietPeriod).toBe(2);
      expect(monitor.warmupPeriod).toBe(5);
      expect(monitor.minimumFrameRateDuringWarmup).toBe(4);
      expect(monitor.minimumFrameRateAfterWarmup).toBe(8);
      expect(monitor.scene).toBe(scene2);
      expect(monitor.lowFrameRate.numberOfListeners).toBe(0);
      expect(monitor.nominalFrameRate.numberOfListeners).toBe(0);
    });
    it("honors parameters to the constructor", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2,
        samplingWindow: 3,
        quietPeriod: 1,
        warmupPeriod: 6,
        minimumFrameRateDuringWarmup: 1,
        minimumFrameRateAfterWarmup: 2
      });
      expect(monitor.samplingWindow).toBe(3);
      expect(monitor.quietPeriod).toBe(1);
      expect(monitor.warmupPeriod).toBe(6);
      expect(monitor.minimumFrameRateDuringWarmup).toBe(1);
      expect(monitor.minimumFrameRateAfterWarmup).toBe(2);
      expect(monitor.scene).toBe(scene2);
    });
    it("raises the lowFrameRate event on low frame rate", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2,
        quietPeriod: 1e-3,
        warmupPeriod: 1e-3,
        samplingWindow: 1e-3,
        minimumFrameRateDuringWarmup: 1e3,
        minimumFrameRateAfterWarmup: 1e3
      });
      const spyListener = jasmine.createSpy("listener");
      monitor.lowFrameRate.addEventListener(spyListener);
      scene2.render();
      spinWait(2);
      scene2.render();
      spinWait(2);
      scene2.render();
      expect(monitor.lastFramesPerSecond).toBeLessThan(1e3);
      expect(spyListener).toHaveBeenCalled();
    });
    it("does not monitor frame rate while paused", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2,
        quietPeriod: 1e-3,
        warmupPeriod: 1e-3,
        samplingWindow: 1e-3,
        minimumFrameRateDuringWarmup: 1e3,
        minimumFrameRateAfterWarmup: 1e3
      });
      const spyListener = jasmine.createSpy("listener");
      monitor.lowFrameRate.addEventListener(spyListener);
      scene2.render();
      spinWait(2);
      scene2.render();
      monitor.pause();
      spinWait(2);
      scene2.render();
      monitor.unpause();
      scene2.render();
      expect(spyListener).not.toHaveBeenCalled();
    });
    it("pausing multiple times requires unpausing multiple times", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2,
        quietPeriod: 1e-3,
        warmupPeriod: 1e-3,
        samplingWindow: 1e-3,
        minimumFrameRateDuringWarmup: 1e3,
        minimumFrameRateAfterWarmup: 1e3
      });
      const spyListener = jasmine.createSpy("listener");
      monitor.lowFrameRate.addEventListener(spyListener);
      monitor.pause();
      monitor.pause();
      monitor.unpause();
      scene2.render();
      spinWait(2);
      scene2.render();
      spinWait(2);
      scene2.render();
      monitor.unpause();
      scene2.render();
      expect(spyListener).not.toHaveBeenCalled();
    });
    it("does not report a low frame rate during the quiet period", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2,
        quietPeriod: 1,
        warmupPeriod: 1e-3,
        samplingWindow: 1e-3,
        minimumFrameRateDuringWarmup: 1e3,
        minimumFrameRateAfterWarmup: 1e3
      });
      const spyListener = jasmine.createSpy("listener");
      monitor.lowFrameRate.addEventListener(spyListener);
      scene2.render();
      spinWait(2);
      scene2.render();
      expect(spyListener).not.toHaveBeenCalled();
    });
    it("the nominalFrameRate event is raised after the warmup period if the frame rate returns to nominal", function() {
      monitor = new FrameRateMonitor_default({
        scene: scene2,
        quietPeriod: 1e-3,
        warmupPeriod: 1e-3,
        samplingWindow: 1e-3,
        minimumFrameRateDuringWarmup: 10,
        minimumFrameRateAfterWarmup: 10
      });
      const lowListener = jasmine.createSpy("lowFrameRate");
      monitor.lowFrameRate.addEventListener(lowListener);
      const nominalListener = jasmine.createSpy("nominalFrameRate");
      monitor.nominalFrameRate.addEventListener(nominalListener);
      scene2.render();
      spinWait(2);
      scene2.render();
      spinWait(120);
      scene2.render();
      expect(monitor.lastFramesPerSecond).toBeLessThan(10);
      expect(lowListener).toHaveBeenCalled();
      const endTime = getTimestamp_default() + 50;
      while (getTimestamp_default() < endTime) {
        scene2.render();
      }
      expect(monitor.lastFramesPerSecond).toBeGreaterThanOrEqual(10);
      expect(nominalListener).toHaveBeenCalled();
    });
  },
  "WebGL"
);

