// Specs/loaderProcess.js
function loaderProcess(loader, scene2) {
  scene2.jobScheduler.resetBudgets();
  const ready = loader.process(scene2.frameState);
  scene2.jobScheduler.resetBudgets();
  return ready;
}
var loaderProcess_default = loaderProcess;

// Specs/waitForLoaderProcess.js
function waitForLoaderProcess(loader, scene2) {
  return pollToPromise_default(function() {
    if (loader.isDestroyed()) {
      return true;
    }
    return loaderProcess_default(loader, scene2);
  });
}
var waitForLoaderProcess_default = waitForLoaderProcess;

