    function resolveGltfJsonAfterDestroy(rejectPromise) {
      const gltf = {
        asset: {
          version: "2.0"
        }
      };
      const arrayBuffer = generateJsonBuffer_default(gltf).buffer;
      const fetchPromise = new Promise(function(resolve2, reject) {
        if (rejectPromise) {
          reject(new Error());
        } else {
          resolve2(arrayBuffer);
        }
      });
      spyOn(GltfJsonLoader_default.prototype, "_fetchGltf").and.returnValue(
        fetchPromise
      );
      const gltfUri = "https://example.com/model.glb";
      const gltfResource = new Resource_default({
        url: gltfUri
      });
      const gltfLoader = new GltfLoader_default({
        gltfResource
      });
      expect(gltfLoader.components).not.toBeDefined();
      const promise = gltfLoader.load();
      gltfLoader.destroy();
      return promise.then(function() {
        expect(gltfLoader.components).not.toBeDefined();
        expect(gltfLoader.isDestroyed()).toBe(true);
      });
    }
    it("handles resolving glTF JSON after destroy", function() {
      return resolveGltfJsonAfterDestroy(false);
    });
    it("handles rejecting glTF JSON after destroy", function() {
      return resolveGltfJsonAfterDestroy(true);
    });
