    function coordinateOfPixelColor(rgba, color) {
      for (let y = 0; y < canvasHeight; y++) {
        for (let x = 0; x < canvasWidth; x++) {
          const i = (y * canvasWidth + x) * 4;
          if (color[0] === rgba[i] && color[1] === rgba[i + 1] && color[2] === rgba[i + 2] && color[3] === rgba[i + 3]) {
            return new Cartesian2_default(x, canvasHeight - y);
          }
        }
      }
    }
    function verifyGroundPolylinePrimitiveRender(lookPosition2, primitive, color) {
      scene2.camera.lookAt(lookPosition2, Cartesian3_default.UNIT_Z);
      scene2.groundPrimitives.add(depthRectanglePrimitive);
      expect(scene2).toRenderAndCall(function(rgba) {
        expect(coordinateOfPixelColor(rgba, depthColor)).toBeDefined();
      });
      scene2.groundPrimitives.add(primitive);
      let coordinate;
      expect(scene2).toRenderAndCall(function(rgba) {
        coordinate = coordinateOfPixelColor(rgba, color);
        expect(coordinate).toBeDefined();
      });
      return coordinate;
    }
