// packages/engine/Specs/Scene/hasExtensionSpec.js
describe("Scene/hasExtension", function() {
  it("detects the presence of an extension", function() {
    const tile = {
      extensions: {
        "3DTILES_extension": {}
      }
    };
    expect(hasExtension_default(tile, "3DTILES_extension")).toEqual(true);
  });
  it("detects the absence of an extension", function() {
    let tile = {};
    expect(hasExtension_default(tile, "3DTILES_extension")).toEqual(false);
    tile = {
      extensions: {}
    };
    expect(hasExtension_default(tile, "3DTILES_extension")).toEqual(false);
    tile = {
      extensions: {
        "3DTILES_other_extension": {}
      }
    };
    expect(hasExtension_default(tile, "3DTILES_extension")).toEqual(false);
  });
});

// packages/engine/Specs/Scene/HeightmapTessellatorSpec.js
describe("Scene/HeightmapTessellator", function() {
  it("throws when heightmap is not provided", function() {
    expect(function() {
      HeightmapTessellator_default.computeVertices();
    }).toThrowDeveloperError();
    expect(function() {
      HeightmapTessellator_default.computeVertices({
        width: 2,
        height: 2,
        vertices: [],
        nativeRectangle: {
          west: 10,
          south: 20,
          east: 20,
          north: 30
        },
        skirtHeight: 10
      });
    }).toThrowDeveloperError();
  });
  it("throws when width or height is not provided", function() {
    expect(function() {
      HeightmapTessellator_default.computeVertices({
        heightmap: [1, 2, 3, 4],
        height: 2,
        vertices: [],
        nativeRectangle: {
          west: 10,
          south: 20,
          east: 20,
          north: 30
        },
        skirtHeight: 10
      });
    }).toThrowDeveloperError();
    expect(function() {
      HeightmapTessellator_default.computeVertices({
        heightmap: [1, 2, 3, 4],
        width: 2,
        vertices: [],
        nativeRectangle: {
          west: 10,
          south: 20,
          east: 20,
          north: 30
        },
        skirtHeight: 10
      });
    }).toThrowDeveloperError();
  });
  it("throws when nativeRectangle is not provided", function() {
    expect(function() {
      HeightmapTessellator_default.computeVertices({
        heightmap: [1, 2, 3, 4],
        width: 2,
        height: 2,
        vertices: [],
        skirtHeight: 10
      });
    }).toThrowDeveloperError();
  });
  it("throws when skirtHeight is not provided", function() {
    expect(function() {
      HeightmapTessellator_default.computeVertices({
        heightmap: [1, 2, 3, 4],
        width: 2,
        height: 2,
        vertices: [],
        nativeRectangle: {
          west: 10,
          south: 20,
          east: 20,
          north: 30
        }
      });
    }).toThrowDeveloperError();
  });
  function checkExpectedVertex(nativeRectangle, i, j, width, height, index, isEdge2, vertices, heightmap, ellipsoid, skirtHeight) {
    let latitude = Math_default.lerp(
      nativeRectangle.north,
      nativeRectangle.south,
      j / (height - 1)
    );
    latitude = Math_default.toRadians(latitude);
    let longitude = Math_default.lerp(
      nativeRectangle.west,
      nativeRectangle.east,
      i / (width - 1)
    );
    longitude = Math_default.toRadians(longitude);
    let heightSample = heightmap[j * width + i];
    if (isEdge2) {
      heightSample -= skirtHeight;
    }
    const expectedVertexPosition = ellipsoid.cartographicToCartesian({
      longitude,
      latitude,
      height: heightSample
    });
    index = index * 6;
    const vertexPosition = new Cartesian3_default(
      vertices[index],
      vertices[index + 1],
      vertices[index + 2]
    );
    expect(vertexPosition).toEqualEpsilon(expectedVertexPosition, 1);
    expect(vertices[index + 3]).toEqual(heightSample);
    expect(vertices[index + 4]).toEqualEpsilon(
      i / (width - 1),
      Math_default.EPSILON7
    );
    expect(vertices[index + 5]).toEqualEpsilon(
      1 - j / (height - 1),
      Math_default.EPSILON7
    );
  }
  function checkExpectedQuantizedVertex(nativeRectangle, i, j, width, height, index, isEdge2, vertices, heightmap, ellipsoid, skirtHeight, encoding) {
    let latitude = Math_default.lerp(
      nativeRectangle.north,
      nativeRectangle.south,
      j / (height - 1)
    );
    latitude = Math_default.toRadians(latitude);
    let longitude = Math_default.lerp(
      nativeRectangle.west,
      nativeRectangle.east,
      i / (width - 1)
    );
    longitude = Math_default.toRadians(longitude);
    let heightSample = heightmap[j * width + i];
    if (isEdge2) {
      heightSample -= skirtHeight;
    }
    const expectedVertexPosition = ellipsoid.cartographicToCartesian({
      longitude,
      latitude,
      height: heightSample
    });
    expect(encoding.decodePosition(vertices, index)).toEqualEpsilon(
      expectedVertexPosition,
      1
    );
  }
  it("creates mesh without skirt", function() {
    const width = 3;
    const height = 3;
    const options = {
      heightmap: [1, 2, 3, 4, 5, 6, 7, 8, 9],
      width,
      height,
      skirtHeight: 0,
      nativeRectangle: {
        west: 10,
        south: 30,
        east: 20,
        north: 40
      },
      rectangle: new Rectangle_default(
        Math_default.toRadians(10),
        Math_default.toRadians(30),
        Math_default.toRadians(20),
        Math_default.toRadians(40)
      )
    };
    const results = HeightmapTessellator_default.computeVertices(options);
    const vertices = results.vertices;
    const ellipsoid = Ellipsoid_default.WGS84;
    const nativeRectangle = options.nativeRectangle;
    let index = 0;
    for (let j = 0; j < height; ++j) {
      for (let i = 0; i < width; ++i) {
        checkExpectedVertex(
          nativeRectangle,
          i,
          j,
          width,
          height,
          index++,
          false,
          vertices,
          options.heightmap,
          ellipsoid,
          options.skirtHeight
        );
      }
    }
  });
  it("creates mesh with skirt", function() {
    const width = 3;
    const height = 3;
    const options = {
      heightmap: [1, 2, 3, 4, 5, 6, 7, 8, 9],
      width,
      height,
      skirtHeight: 10,
      nativeRectangle: {
        west: 10,
        east: 20,
        south: 30,
        north: 40
      }
    };
    const results = HeightmapTessellator_default.computeVertices(options);
    const vertices = results.vertices;
    const ellipsoid = Ellipsoid_default.WGS84;
    const nativeRectangle = options.nativeRectangle;
    let i, j;
    let index = 0;
    for (j = 0; j < height; ++j) {
      for (i = 0; i < width; ++i) {
        checkExpectedVertex(
          nativeRectangle,
          i,
          j,
          width,
          height,
          index++,
          false,
          vertices,
          options.heightmap,
          ellipsoid,
          options.skirtHeight
        );
      }
    }
    for (j = 0; j < height; ++j) {
      checkExpectedVertex(
        nativeRectangle,
        0,
        height - 1 - j,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight
      );
    }
    for (i = 0; i < height; ++i) {
      checkExpectedVertex(
        nativeRectangle,
        width - 1 - i,
        height - 1,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight
      );
    }
    for (j = 0; j < height; ++j) {
      checkExpectedVertex(
        nativeRectangle,
        width - 1,
        j,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight
      );
    }
    for (i = 0; i < height; ++i) {
      checkExpectedVertex(
        nativeRectangle,
        i,
        0,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight
      );
    }
  });
  it("creates quantized mesh", function() {
    const width = 3;
    const height = 3;
    const options = {
      heightmap: [1, 2, 3, 4, 5, 6, 7, 8, 9],
      width,
      height,
      skirtHeight: 10,
      nativeRectangle: {
        west: 0.01,
        east: 0.02,
        south: 0.01,
        north: 0.02
      }
    };
    const results = HeightmapTessellator_default.computeVertices(options);
    const vertices = results.vertices;
    const ellipsoid = Ellipsoid_default.WGS84;
    const nativeRectangle = options.nativeRectangle;
    let i, j;
    let index = 0;
    for (j = 0; j < height; ++j) {
      for (i = 0; i < width; ++i) {
        checkExpectedQuantizedVertex(
          nativeRectangle,
          i,
          j,
          width,
          height,
          index++,
          false,
          vertices,
          options.heightmap,
          ellipsoid,
          options.skirtHeight,
          results.encoding
        );
      }
    }
    for (j = 0; j < height; ++j) {
      checkExpectedQuantizedVertex(
        nativeRectangle,
        0,
        height - 1 - j,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight,
        results.encoding
      );
    }
    for (i = 0; i < height; ++i) {
      checkExpectedQuantizedVertex(
        nativeRectangle,
        width - 1 - i,
        height - 1,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight,
        results.encoding
      );
    }
    for (j = 0; j < height; ++j) {
      checkExpectedQuantizedVertex(
        nativeRectangle,
        width - 1,
        j,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight,
        results.encoding
      );
    }
    for (i = 0; i < height; ++i) {
      checkExpectedQuantizedVertex(
        nativeRectangle,
        i,
        0,
        width,
        height,
        index++,
        true,
        vertices,
        options.heightmap,
        ellipsoid,
        options.skirtHeight,
        results.encoding
      );
    }
  });
  it("tessellates web mercator heightmaps", function() {
    const width = 3;
    const height = 3;
    const options = {
      heightmap: [1, 2, 3, 4, 5, 6, 7, 8, 9],
      width,
      height,
      skirtHeight: 0,
      nativeRectangle: {
        west: 1e6,
        east: 2e6,
        south: 3e6,
        north: 4e6
      },
      isGeographic: false
    };
    const results = HeightmapTessellator_default.computeVertices(options);
    const vertices = results.vertices;
    const ellipsoid = Ellipsoid_default.WGS84;
    const projection = new WebMercatorProjection_default(ellipsoid);
    const nativeRectangle = options.nativeRectangle;
    const geographicSouthwest = projection.unproject(
      new Cartesian2_default(nativeRectangle.west, nativeRectangle.south)
    );
    const geographicNortheast = projection.unproject(
      new Cartesian2_default(nativeRectangle.east, nativeRectangle.north)
    );
    for (let j = 0; j < height; ++j) {
      const y = Math_default.lerp(
        nativeRectangle.north,
        nativeRectangle.south,
        j / (height - 1)
      );
      for (let i = 0; i < width; ++i) {
        const x = Math_default.lerp(
          nativeRectangle.west,
          nativeRectangle.east,
          i / (width - 1)
        );
        const latLon = projection.unproject(new Cartesian2_default(x, y));
        const longitude = latLon.longitude;
        const latitude = latLon.latitude;
        const heightSample = options.heightmap[j * width + i];
        const expectedVertexPosition = ellipsoid.cartographicToCartesian({
          longitude,
          latitude,
          height: heightSample
        });
        const index = (j * width + i) * 6;
        const vertexPosition = new Cartesian3_default(
          vertices[index],
          vertices[index + 1],
          vertices[index + 2]
        );
        const expectedU = (longitude - geographicSouthwest.longitude) / (geographicNortheast.longitude - geographicSouthwest.longitude);
        const expectedV = (latitude - geographicSouthwest.latitude) / (geographicNortheast.latitude - geographicSouthwest.latitude);
        expect(vertexPosition).toEqualEpsilon(expectedVertexPosition, 1);
        expect(vertices[index + 3]).toEqual(heightSample);
        expect(vertices[index + 4]).toEqualEpsilon(
          expectedU,
          Math_default.EPSILON7
        );
        expect(vertices[index + 5]).toEqualEpsilon(
          expectedV,
          Math_default.EPSILON7
        );
      }
    }
  });
  it("supports multi-element little endian heights", function() {
    const width = 3;
    const height = 3;
    const options = {
      heightmap: [
        1,
        2,
        100,
        3,
        4,
        100,
        5,
        6,
        100,
        7,
        8,
        100,
        9,
        10,
        100,
        11,
        12,
        100,
        13,
        14,
        100,
        15,
        16,
        100,
        17,
        18,
        100
      ],
      width,
      height,
      skirtHeight: 0,
      nativeRectangle: {
        west: 10,
        south: 30,
        east: 20,
        north: 40
      },
      rectangle: new Rectangle_default(
        Math_default.toRadians(10),
        Math_default.toRadians(30),
        Math_default.toRadians(20),
        Math_default.toRadians(40)
      ),
      structure: {
        stride: 3,
        elementsPerHeight: 2,
        elementMultiplier: 10
      }
    };
    const results = HeightmapTessellator_default.computeVertices(options);
    const vertices = results.vertices;
    const ellipsoid = Ellipsoid_default.WGS84;
    const nativeRectangle = options.nativeRectangle;
    for (let j = 0; j < height; ++j) {
      let latitude = Math_default.lerp(
        nativeRectangle.north,
        nativeRectangle.south,
        j / (height - 1)
      );
      latitude = Math_default.toRadians(latitude);
      for (let i = 0; i < width; ++i) {
        let longitude = Math_default.lerp(
          nativeRectangle.west,
          nativeRectangle.east,
          i / (width - 1)
        );
        longitude = Math_default.toRadians(longitude);
        const heightSampleIndex = (j * width + i) * options.structure.stride;
        const heightSample = options.heightmap[heightSampleIndex] + options.heightmap[heightSampleIndex + 1] * 10;
        const expectedVertexPosition = ellipsoid.cartographicToCartesian({
          longitude,
          latitude,
          height: heightSample
        });
        const index = (j * width + i) * 6;
        const vertexPosition = new Cartesian3_default(
          vertices[index],
          vertices[index + 1],
          vertices[index + 2]
        );
        expect(vertexPosition).toEqualEpsilon(expectedVertexPosition, 1);
        expect(vertices[index + 3]).toEqual(heightSample);
        expect(vertices[index + 4]).toEqualEpsilon(
          i / (width - 1),
          Math_default.EPSILON7
        );
        expect(vertices[index + 5]).toEqualEpsilon(
          1 - j / (height - 1),
          Math_default.EPSILON7
        );
      }
    }
  });
  it("supports multi-element big endian heights", function() {
    const width = 3;
    const height = 3;
    const options = {
      heightmap: [
        1,
        2,
        100,
        3,
        4,
        100,
        5,
        6,
        100,
        7,
        8,
        100,
        9,
        10,
        100,
        11,
        12,
        100,
        13,
        14,
        100,
        15,
        16,
        100,
        17,
        18,
        100
      ],
      width,
      height,
      skirtHeight: 0,
      nativeRectangle: {
        west: 10,
        south: 30,
        east: 20,
        north: 40
      },
      rectangle: new Rectangle_default(
        Math_default.toRadians(10),
        Math_default.toRadians(30),
        Math_default.toRadians(20),
        Math_default.toRadians(40)
      ),
      structure: {
        stride: 3,
        elementsPerHeight: 2,
        elementMultiplier: 10,
        isBigEndian: true
      }
    };
    const results = HeightmapTessellator_default.computeVertices(options);
    const vertices = results.vertices;
    const ellipsoid = Ellipsoid_default.WGS84;
    const nativeRectangle = options.nativeRectangle;
    for (let j = 0; j < height; ++j) {
      let latitude = Math_default.lerp(
        nativeRectangle.north,
        nativeRectangle.south,
        j / (height - 1)
      );
      latitude = Math_default.toRadians(latitude);
      for (let i = 0; i < width; ++i) {
        let longitude = Math_default.lerp(
          nativeRectangle.west,
          nativeRectangle.east,
          i / (width - 1)
        );
        longitude = Math_default.toRadians(longitude);
        const heightSampleIndex = (j * width + i) * options.structure.stride;
        const heightSample = options.heightmap[heightSampleIndex] * 10 + options.heightmap[heightSampleIndex + 1];
        const expectedVertexPosition = ellipsoid.cartographicToCartesian({
          longitude,
          latitude,
          height: heightSample
        });
        const index = (j * width + i) * 6;
        const vertexPosition = new Cartesian3_default(
          vertices[index],
          vertices[index + 1],
          vertices[index + 2]
        );
        expect(vertexPosition).toEqualEpsilon(expectedVertexPosition, 1);
        expect(vertices[index + 3]).toEqual(heightSample);
        expect(vertices[index + 4]).toEqualEpsilon(
          i / (width - 1),
          Math_default.EPSILON7
        );
        expect(vertices[index + 5]).toEqualEpsilon(
          1 - j / (height - 1),
          Math_default.EPSILON7
        );
      }
    }
  });
});

// packages/engine/Specs/Scene/I3dmParserSpec.js
describe(
  "Scene/I3dmParser",
  function() {
    it("throws with undefined arrayBuffer", function() {
      expect(function() {
        I3dmParser_default.parse(void 0);
      }).toThrowDeveloperError();
    });
    it("throws with invalid version", function() {
      const arrayBuffer = Cesium3DTilesTester_default.generateInstancedTileBuffer({
        version: 2
      });
      expect(function() {
        I3dmParser_default.parse(arrayBuffer);
      }).toThrowError(RuntimeError_default);
    });
    it("throws if there is no feature table json", function() {
      const arrayBuffer = Cesium3DTilesTester_default.generateInstancedTileBuffer({
        featureTableJson: {}
      });
      expect(function() {
        I3dmParser_default.parse(arrayBuffer);
      }).toThrowError(RuntimeError_default);
    });
    it("throws with invalid glTF format", function() {
      const arrayBuffer = Cesium3DTilesTester_default.generateInstancedTileBuffer({
        gltfFormat: 2
      });
      expect(function() {
        I3dmParser_default.parse(arrayBuffer);
      }).toThrowError(RuntimeError_default);
    });
    it("throws if there is no glTF", function() {
      const arrayBuffer = Cesium3DTilesTester_default.generateInstancedTileBuffer({
        gltfUri: ""
      });
      expect(function() {
        I3dmParser_default.parse(arrayBuffer);
      }).toThrowError(RuntimeError_default);
    });
    it("prints deprecation warning if glTF is not 4-byte aligned", function() {
      spyOn(I3dmParser_default, "_deprecationWarning");
      const arrayBuffer = Cesium3DTilesTester_default.generateInstancedTileBuffer({
        featureTableBinary: new Uint8Array(1)
      });
      I3dmParser_default.parse(arrayBuffer);
      expect(I3dmParser_default._deprecationWarning).toHaveBeenCalled();
    });
    it("parses i3dm", function() {
      const instancesLength = 10;
      const positions = new Float32Array(instancesLength * 3);
      const heights = new Float32Array(instancesLength);
      for (let i = 0; i < instancesLength; ++i) {
        positions[i * 3] = i;
        positions[i * 3 + 1] = i;
        positions[i * 3 + 2] = i;
        heights[i] = i;
      }
      const featureTableJson = {
        INSTANCES_LENGTH: instancesLength,
        POSITION: {
          byteOffset: 0
        }
      };
      const featureTableBinary = positions;
      const batchTableJson = {
        height: {
          byteOffset: 0,
          componentType: "FLOAT",
          type: "SCALAR"
        }
      };
      const batchTableBinary = heights;
      const gltfUri = "model.gltf";
      const arrayBuffer = Cesium3DTilesTester_default.generateInstancedTileBuffer({
        featureTableJson,
        featureTableBinary,
        batchTableJson,
        batchTableBinary,
        gltfUri
      });
      const results = I3dmParser_default.parse(arrayBuffer);
      expect(results.gltfFormat).toBe(1);
      expect(results.featureTableJson).toEqual(featureTableJson);
      expect(results.featureTableBinary).toEqual(featureTableBinary);
      expect(results.batchTableJson).toEqual(batchTableJson);
      expect(results.batchTableBinary).toEqual(batchTableBinary);
      expect(getStringFromTypedArray_default(results.gltf)).toEqual(gltfUri);
    });
  },
  "WebGL"
);

