      it("should reuse canvases for letters, but only if other settings are the same", async function() {
        labels.add({
          text: "a"
        });
        const cache = labels._glyphBillboardCollection.billboardTextureCache;
        await allLabelsReady();
        expect(cache.size).toEqual(1);
        labels.add({
          text: "a"
        });
        await allLabelsReady();
        expect(cache.size).toEqual(1);
        labels.add({
          text: "abcd"
        });
        await allLabelsReady();
        expect(cache.size).toEqual(4);
        labels.add({
          text: "abc"
        });
        await allLabelsReady();
        expect(cache.size).toEqual(4);
        const label = labels.add({
          text: "de"
        });
        await allLabelsReady();
        expect(cache.size).toEqual(5);
        const originalFont = label.font;
        label.font = '30px "Open Sans"';
        expect(label.font).not.toEqual(originalFont);
        scene2.renderForSpecs();
        expect(cache.size).toEqual(7);
        label.style = LabelStyle_default.OUTLINE;
        scene2.renderForSpecs();
        expect(cache.size).toEqual(7);
        label.fillColor = new Color_default(1, 165 / 255, 0, 1);
        scene2.renderForSpecs();
        expect(cache.size).toEqual(7);
        label.outlineColor = new Color_default(1, 1, 1, 1);
        scene2.renderForSpecs();
        expect(cache.size).toEqual(7);
        label.verticalOrigin = VerticalOrigin_default.CENTER;
        scene2.renderForSpecs();
        expect(cache.size).toEqual(7);
        label.verticalOrigin = VerticalOrigin_default.TOP;
        scene2.renderForSpecs();
        expect(cache.size).toEqual(7);
        label.font = originalFont;
        scene2.renderForSpecs();
        expect(cache.size).toEqual(9);
        label.outlineWidth = 3;
        scene2.renderForSpecs();
        expect(cache.size).toEqual(9);
      });
