  describe("handleNoData", function() {
    let properties;
    beforeAll(function() {
      properties = {
        float: {
          type: "SCALAR",
          componentType: "FLOAT64",
          noData: -1
        },
        array: {
          array: true,
          count: 4,
          type: "SCALAR",
          componentType: "UINT8",
          noData: [255, 255, 255, 255]
        },
        variableLengthArray: {
          array: true,
          type: "STRING",
          noData: []
        },
        arrayOfVector: {
          array: true,
          count: 2,
          type: "VEC2",
          componentType: "FLOAT32",
          noData: [
            [0, 0],
            [0, 0]
          ]
        }
      };
    });
    it("passes through valid values unchanged", function() {
      const propertyValues = {
        float: 1,
        array: [0, 0, 0, 255],
        variableLengthArray: ["Hello", "World"],
        arrayOfVector: [
          [1, 1],
          [2, -1]
        ]
      };
      for (const propertyId in properties) {
        if (properties.hasOwnProperty(propertyId)) {
          const property = MetadataClassProperty_default.fromJson({
            id: propertyId,
            property: properties[propertyId]
          });
          const expected = propertyValues[propertyId];
          const actual = property.handleNoData(expected);
          expect(actual).toBe(expected);
        }
      }
    });
    it("converts noData values to undefined", function() {
      const propertyValues = {
        float: -1,
        array: [255, 255, 255, 255],
        variableLengthArray: [],
        arrayOfVector: [
          [0, 0],
          [0, 0]
        ]
      };
      for (const propertyId in properties) {
        if (properties.hasOwnProperty(propertyId)) {
          const property = MetadataClassProperty_default.fromJson({
            id: propertyId,
            property: properties[propertyId]
          });
          const value = propertyValues[propertyId];
          const actual = property.handleNoData(value);
          expect(actual).not.toBeDefined();
        }
      }
    });
  });
