      const classProperty = {
        type: MetadataType_default.SCALAR,
        componentType: MetadataComponentType_default.INT8,
        normalized: false
      };
      const offset = 100;
      const scale = 2;
      const metadataProperty = {
        hasValueTransform: true,
        offset,
        scale
      };
      const rawPixelValues = new Uint8Array([12, 23, 34, 45]);
