// packages/engine/Specs/Scene/MetadataSchemaLoaderSpec.js
describe("Scene/MetadataSchemaLoader", function() {
  const schemaJson = {
    classes: {
      tree: {
        properties: {
          height: {
            type: "SCALAR",
            componentType: "FLOAT32"
          },
          type: {
            type: "ENUM",
            enumType: "treeType"
          }
        }
      }
    },
    enums: {
      treeType: {
        values: [
          {
            name: "Coniferous",
            value: 0
          },
          {
            name: "Deciduous",
            value: 1
          }
        ]
      }
    }
  };
  const resource = new Resource_default({ url: "https://example.com/schema.json" });
  afterEach(function() {
    ResourceCache_default.clearForSpecs();
  });
  it("throws if neither options.schema nor options.resource are defined", function() {
    expect(function() {
      return new MetadataSchemaLoader_default({
        schema: void 0,
        resource: void 0
      });
    }).toThrowDeveloperError();
  });
  it("throws if both options.schema and options.resource are defined", function() {
    expect(function() {
      return new MetadataSchemaLoader_default({
        resource,
        schema: schemaJson
      });
    }).toThrowDeveloperError();
  });
  it("load throws if schema cannot be fetched", async function() {
    spyOn(Resource_default.prototype, "fetchJson").and.callFake(function() {
      const error = new Error("404 Not Found");
      return Promise.reject(error);
    });
    const schemaLoader = new MetadataSchemaLoader_default({
      resource
    });
    await expectAsync(schemaLoader.load()).toBeRejectedWithError(
      RuntimeError_default,
      "Failed to load schema: https://example.com/schema.json\n404 Not Found"
    );
  });
  it("loads schema from JSON", async function() {
    const schemaLoader = new MetadataSchemaLoader_default({
      schema: schemaJson
    });
    await schemaLoader.load();
    const schema = schemaLoader.schema;
    expect(schema).toBeDefined();
    const enums = schema.enums;
    expect(enums.treeType).toBeDefined();
    const classes = schema.classes;
    expect(classes.tree).toBeDefined();
  });
  it("loads external schema", async function() {
    const fetchJson = spyOn(Resource_default.prototype, "fetchJson").and.returnValue(
      Promise.resolve(schemaJson)
    );
    const schemaLoader = new MetadataSchemaLoader_default({
      resource
    });
    await schemaLoader.load();
    expect(fetchJson).toHaveBeenCalled();
    const schema = schemaLoader.schema;
    expect(schema).toBeDefined();
    const enums = schema.enums;
    expect(enums.treeType).toBeDefined();
    const classes = schema.classes;
    expect(classes.tree).toBeDefined();
  });
  it("destroys schema", async function() {
    spyOn(Resource_default.prototype, "fetchJson").and.returnValue(
      Promise.resolve(schemaJson)
    );
    const schemaLoader = new MetadataSchemaLoader_default({
      resource
    });
    expect(schemaLoader.schema).not.toBeDefined();
    await schemaLoader.load();
    expect(schemaLoader.schema).toBeDefined();
    expect(schemaLoader.isDestroyed()).toBe(false);
    schemaLoader.destroy();
    expect(schemaLoader.schema).not.toBeDefined();
    expect(schemaLoader.isDestroyed()).toBe(true);
  });
  async function resolveJsonAfterDestroy(rejectPromise) {
    spyOn(Resource_default.prototype, "fetchJson").and.callFake(
      () => rejectPromise ? Promise.reject(new Error()) : Promise.resolve(schemaJson)
    );
    const schemaLoader = new MetadataSchemaLoader_default({
      resource
    });
    expect(schemaLoader.schema).not.toBeDefined();
    const promise = schemaLoader.load();
    expect(schemaLoader._state).toBe(ResourceLoaderState_default.LOADING);
    schemaLoader.destroy();
    await expectAsync(promise).toBeResolved();
    expect(schemaLoader.schema).not.toBeDefined();
    expect(schemaLoader.isDestroyed()).toBe(true);
  }
  it("handles resolving json after destroy", function() {
    return resolveJsonAfterDestroy(false);
  });
  it("handles rejecting json after destroy", function() {
    return resolveJsonAfterDestroy(true);
  });
});

// packages/engine/Specs/Scene/MetadataSchemaSpec.js
describe("Scene/MetadataSchema", function() {
  it("creates schema with default values", function() {
    const schema = MetadataSchema_default.fromJson({});
    expect(schema.classes).toEqual({});
    expect(schema.enums).toEqual({});
    expect(schema.name).toBeUndefined();
    expect(schema.description).toBeUndefined();
    expect(schema.version).toBeUndefined();
    expect(schema.extras).toBeUndefined();
  });
  it("creates schema", function() {
    const extras = {
      description: "Extra"
    };
    const extensions = {
      EXT_other_extension: {}
    };
    const schema = MetadataSchema_default.fromJson({
      enums: {
        color: {
          values: [
            {
              name: "RED",
              value: 0
            },
            {
              name: "GREEN",
              value: 1
            },
            {
              name: "BLUE",
              value: 2
            }
          ]
        },
        species: {
          values: [
            {
              name: "Oak",
              value: 0
            },
            {
              name: "Pine",
              value: 1
            },
            {
              name: "Other",
              value: -1
            }
          ]
        }
      },
      classes: {
        city: {
          properties: {
            name: {
              type: "STRING"
            }
          }
        },
        neighborhood: {
          properties: {
            color: {
              type: "ENUM",
              enumType: "color"
            },
            coordinates: {
              type: "SCALAR",
              componentType: "FLOAT64",
              array: true,
              count: 2
            }
          }
        },
        tree: {
          properties: {
            species: {
              type: "ENUM",
              array: true,
              enumType: "species"
            },
            height: {
              type: "SCALAR",
              componentType: "FLOAT32"
            }
          }
        }
      },
      id: "mySchema",
      name: "My Schema",
      description: "My Schema Description",
      version: "3.1.0",
      extras,
      extensions
    });
    const cityClass = schema.classes.city;
    const neighborhoodClass = schema.classes.neighborhood;
    const treeClass = schema.classes.tree;
    const cityProperties = cityClass.properties;
    const neighborhoodProperties = neighborhoodClass.properties;
    const treeProperties = treeClass.properties;
    expect(cityClass.id).toBe("city");
    expect(neighborhoodClass.id).toBe("neighborhood");
    expect(treeClass.id).toBe("tree");
    expect(cityProperties.name.id).toBe("name");
    expect(neighborhoodProperties.color.enumType.id).toBe("color");
    expect(neighborhoodProperties.coordinates.id).toBe("coordinates");
    expect(treeProperties.species.enumType.id).toBe("species");
    expect(treeProperties.height.id).toBe("height");
    expect(schema.id).toBe("mySchema");
    expect(schema.name).toBe("My Schema");
    expect(schema.description).toBe("My Schema Description");
    expect(schema.version).toBe("3.1.0");
    expect(schema.extras).toEqual(extras);
    expect(schema.extensions).toEqual(extensions);
  });
  it("constructor throws without schema", function() {
    expect(function() {
      return MetadataSchema_default.fromJson();
    }).toThrowDeveloperError();
  });
});

