  it("get handles noData correctly", function() {
    const properties = {
      noDefault: {
        type: "SCALAR",
        componentType: "INT32",
        required: false,
        noData: -1
      },
      hasDefault: {
        type: "SCALAR",
        componentType: "INT32",
        required: false,
        noData: -1,
        default: 100
      },
      noDefaultVector: {
        type: "VEC2",
        componentType: "FLOAT32",
        required: false,
        noData: [0, 0]
      },
      hasDefaultVector: {
        type: "VEC2",
        componentType: "FLOAT32",
        required: false,
        noData: [0, 0],
        default: [100, 100]
      },
      noDefaultArray: {
        array: true,
        type: "SCALAR",
        componentType: "UINT8",
        count: 3,
        required: false,
        noData: [0, 0, 0]
      },
      hasDefaultArray: {
        array: true,
        type: "SCALAR",
        componentType: "UINT8",
        required: false,
        noData: [],
        default: [1, 1, 1]
      },
      noDefaultArrayOfVector: {
        array: true,
        type: "VEC2",
        componentType: "FLOAT32",
        count: 3,
        required: false,
        noData: [
          [0, 0],
          [0, 0]
        ]
      },
      hasDefaultArrayOfVector: {
        array: true,
        type: "VEC2",
        componentType: "FLOAT32",
        required: false,
        noData: [],
        default: [
          [1, 1],
          [1, 1]
        ]
      }
    };
    const propertyValues = {
      noDefault: [-1, 0],
      hasDefault: [-1, 0],
      noDefaultVector: [
        [0, 0],
        [0, 1]
      ],
      hasDefaultVector: [
        [0, 0],
        [0, 1]
      ],
      noDefaultArray: [
        [0, 0, 0],
        [1, 0, 0]
      ],
      hasDefaultArray: [[], [1, 2]],
      noDefaultArrayOfVector: [
        [0, 0, 0, 0, 0, 0],
        [1, 0, 1, 1, 0, 0]
      ],
      hasDefaultArrayOfVector: [[], [1, 0]]
    };
    const expectedValues = {
      noDefault: [void 0, 0],
      hasDefault: [100, 0],
      noDefaultVector: [void 0, new Cartesian2_default(0, 1)],
      hasDefaultVector: [
        new Cartesian2_default(100, 100),
        new Cartesian2_default(0, 1)
      ],
      noDefaultArray: [void 0, [1, 0, 0]],
      hasDefaultArray: [
        [1, 1, 1],
        [1, 2]
      ],
      noDefaultArrayOfVector: [
        void 0,
        [
          [1, 0],
          [1, 1],
          [0, 0]
        ]
      ],
      hasDefaultArrayOfVector: [
        [new Cartesian2_default(1, 1), new Cartesian2_default(1, 1)],
        [new Cartesian2_default(1, 0)]
      ]
    };
    for (const propertyId in properties) {
      if (properties.hasOwnProperty(propertyId)) {
        const property = MetadataTester_default.createProperty({
          property: properties[propertyId],
          values: propertyValues[propertyId]
        });
        const length3 = expectedValues.length;
        for (let i = 0; i < length3; ++i) {
          const value = property.get(i);
          expect(value).toEqual(expectedValues[propertyId][i]);
        }
      }
    }
  });
