// packages/engine/Specs/Scene/OpenStreetMapImageryProviderSpec.js
describe("Scene/OpenStreetMapImageryProvider", function() {
  beforeEach(function() {
    RequestScheduler_default.clearForSpecs();
  });
  afterEach(function() {
    Resource_default._Implementations.createImage = Resource_default._DefaultImplementations.createImage;
  });
  it("return a UrlTemplateImageryProvider", function() {
    const provider = new OpenStreetMapImageryProvider_default();
    expect(provider).toBeInstanceOf(UrlTemplateImageryProvider_default);
  });
  it("returns valid value for hasAlphaChannel", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server/"
    });
    expect(typeof provider.hasAlphaChannel).toBe("boolean");
  });
  it("supports a Resource for the url", function() {
    const resource = new Resource_default({
      url: "made/up/osm/server/"
    });
    const provider = new OpenStreetMapImageryProvider_default({
      url: resource
    });
    spyOn(Resource_default._Implementations, "createImage").and.callFake(
      function(request, crossOrigin, deferred) {
        expect(request.url).not.toContain("//");
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      }
    );
    return provider.requestImage(0, 0, 0).then(function(image) {
      expect(Resource_default._Implementations.createImage).toHaveBeenCalled();
      expect(image).toBeImageOrImageBitmap();
    });
  });
  it("supports a slash at the end of the URL", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server/"
    });
    spyOn(Resource_default._Implementations, "createImage").and.callFake(
      function(request, crossOrigin, deferred) {
        expect(request.url).not.toContain("//");
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      }
    );
    return provider.requestImage(0, 0, 0).then(function(image) {
      expect(Resource_default._Implementations.createImage).toHaveBeenCalled();
      expect(image).toBeImageOrImageBitmap();
    });
  });
  it("supports no slash at the endof the URL", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server"
    });
    spyOn(Resource_default._Implementations, "createImage").and.callFake(
      function(request, crossOrigin, deferred) {
        expect(request.url).toContain("made/up/osm/server/");
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      }
    );
    return provider.requestImage(0, 0, 0).then(function(image) {
      expect(Resource_default._Implementations.createImage).toHaveBeenCalled();
      expect(image).toBeImageOrImageBitmap();
    });
  });
  it("requestImage returns a promise for an image and loads it for cross-origin use", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server/"
    });
    expect(provider.url).toContain("made/up/osm/server/");
    expect(provider.tileWidth).toEqual(256);
    expect(provider.tileHeight).toEqual(256);
    expect(provider.maximumLevel).toBeUndefined();
    expect(provider.tilingScheme).toBeInstanceOf(WebMercatorTilingScheme_default);
    expect(provider.rectangle).toEqual(new WebMercatorTilingScheme_default().rectangle);
    spyOn(Resource_default._Implementations, "createImage").and.callFake(
      function(request, crossOrigin, deferred) {
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      }
    );
    return provider.requestImage(0, 0, 0).then(function(image) {
      expect(Resource_default._Implementations.createImage).toHaveBeenCalled();
      expect(image).toBeImageOrImageBitmap();
    });
  });
  it("when no credit is supplied, a default one is used", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server"
    });
    expect(provider.credit).toBeDefined();
  });
  it("turns the supplied credit into a logo", function() {
    const providerWithCredit = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server",
      credit: "Thanks to our awesome made up source of this imagery!"
    });
    expect(providerWithCredit.credit).toBeDefined();
  });
  it("rectangle passed to constructor does not affect tile numbering", function() {
    const rectangle = new Rectangle_default(0.1, 0.2, 0.3, 0.4);
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server",
      rectangle
    });
    expect(provider.tileWidth).toEqual(256);
    expect(provider.tileHeight).toEqual(256);
    expect(provider.maximumLevel).toBeUndefined();
    expect(provider.tilingScheme).toBeInstanceOf(WebMercatorTilingScheme_default);
    expect(provider.rectangle.west).toEqualEpsilon(
      rectangle.west,
      Math_default.EPSILON10
    );
    expect(provider.rectangle.south).toEqualEpsilon(
      rectangle.south,
      Math_default.EPSILON10
    );
    expect(provider.rectangle.east).toEqualEpsilon(
      rectangle.east,
      Math_default.EPSILON10
    );
    expect(provider.rectangle.north).toEqualEpsilon(
      rectangle.north,
      Math_default.EPSILON10
    );
    expect(provider.tileDiscardPolicy).toBeUndefined();
    spyOn(Resource_default._Implementations, "createImage").and.callFake(
      function(request, crossOrigin, deferred) {
        expect(request.url).toContain("/0/0/0");
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      }
    );
    return provider.requestImage(0, 0, 0).then(function(image) {
      expect(Resource_default._Implementations.createImage).toHaveBeenCalled();
      expect(image).toBeImageOrImageBitmap();
    });
  });
  it("uses maximumLevel passed to constructor", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server",
      maximumLevel: 5
    });
    expect(provider.maximumLevel).toEqual(5);
  });
  it("uses minimumLevel passed to constructor", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server",
      minimumLevel: 1
    });
    expect(provider.minimumLevel).toEqual(1);
  });
  it("uses retinaTiles passed to constructor", async function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server",
      retinaTiles: true
    });
    spyOn(Resource_default._Implementations, "createImage").and.callFake(
      function(request, crossOrigin, deferred) {
        expect(request.url).toContain("0/0/0@2x.png");
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      }
    );
    const image = await provider.requestImage(0, 0, 0);
    expect(Resource_default._Implementations.createImage).toHaveBeenCalled();
    expect(image).toBeImageOrImageBitmap();
  });
  it("raises error event when image cannot be loaded", function() {
    const provider = new OpenStreetMapImageryProvider_default({
      url: "made/up/osm/server"
    });
    const layer = new ImageryLayer_default(provider);
    let tries = 0;
    provider.errorEvent.addEventListener(function(error) {
      expect(error.timesRetried).toEqual(tries);
      ++tries;
      if (tries < 3) {
        error.retry = true;
      }
      setTimeout(function() {
        RequestScheduler_default.update();
      }, 1);
    });
    Resource_default._Implementations.createImage = function(request, crossOrigin, deferred) {
      if (tries === 2) {
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      } else {
        setTimeout(function() {
          deferred.reject();
        }, 1);
      }
    };
    const imagery = new Imagery_default(layer, 0, 0, 0);
    imagery.addReference();
    layer._requestImagery(imagery);
    RequestScheduler_default.update();
    return pollToPromise_default(function() {
      return imagery.state === ImageryState_default.RECEIVED;
    }).then(function() {
      expect(imagery.image).toBeImageOrImageBitmap();
      expect(tries).toEqual(2);
      imagery.releaseReference();
    });
  });
  it("throws with more than four tiles at the minimum", function() {
    const rectangle = new Rectangle_default(
      0,
      0,
      Math_default.toRadians(1),
      Math_default.toRadians(1)
    );
    expect(function() {
      return new OpenStreetMapImageryProvider_default({
        minimumLevel: 9,
        rectangle
      });
    }).toThrowDeveloperError();
  });
});

// packages/engine/Specs/Scene/OrderedGroundPrimitiveCollectionSpec.js
describe("Scene/OrderedGroundPrimitiveCollection", function() {
  let updateCallOrder;
  beforeEach(function() {
    updateCallOrder = [];
  });
  function MockPrimitive() {
  }
  MockPrimitive.prototype.update = function() {
    updateCallOrder.push(this);
  };
  MockPrimitive.prototype.isDestroyed = function() {
    return false;
  };
  MockPrimitive.prototype.destroy = function() {
    return destroyObject_default(this);
  };
  it("constructs", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    expect(collection.length).toBe(0);
    expect(collection.show).toBe(true);
  });
  it("add throws without primitive", function() {
    expect(function() {
      const collection = new OrderedGroundPrimitiveCollection_default();
      collection.add();
    }).toThrowDeveloperError();
  });
  it("add throws if zIndex is not a number", function() {
    expect(function() {
      const collection = new OrderedGroundPrimitiveCollection_default();
      collection.add(new MockPrimitive(), "3");
    }).toThrowDeveloperError();
  });
  it("adds a primitive", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    collection.add(new MockPrimitive());
    expect(collection.length).toBe(1);
  });
  it("add handles multiple zIndexes", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive());
    const p2 = collection.add(new MockPrimitive(), 0);
    const p3 = collection.add(new MockPrimitive(), 2);
    const p4 = collection.add(new MockPrimitive(), 1);
    expect(collection.length).toBe(4);
    const array = collection._collectionsArray;
    expect(array.length).toBe(3);
    expect(array[0].length).toBe(2);
    expect(array[0].get(0)).toBe(p1);
    expect(array[0].get(1)).toBe(p2);
    expect(array[1].length).toBe(1);
    expect(array[1].get(0)).toBe(p4);
    expect(array[2].length).toBe(1);
    expect(array[2].get(0)).toBe(p3);
  });
  it("add works with negative zIndexes", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive(), 0);
    const p2 = collection.add(new MockPrimitive(), -3);
    const p3 = collection.add(new MockPrimitive(), -1);
    const p4 = collection.add(new MockPrimitive(), -3);
    expect(collection.length).toBe(4);
    const array = collection._collectionsArray;
    expect(array.length).toBe(3);
    expect(array[0].length).toBe(2);
    expect(array[0].get(0)).toBe(p2);
    expect(array[0].get(1)).toBe(p4);
    expect(array[1].length).toBe(1);
    expect(array[1].get(0)).toBe(p3);
    expect(array[2].length).toBe(1);
    expect(array[2].get(0)).toBe(p1);
  });
  it("set throws without primitive", function() {
    expect(function() {
      const collection = new OrderedGroundPrimitiveCollection_default();
      collection.set(void 0, 3);
    }).toThrowDeveloperError();
  });
  it("set throws without zIndex", function() {
    expect(function() {
      const collection = new OrderedGroundPrimitiveCollection_default();
      collection.set(new MockPrimitive(), void 0);
    }).toThrowDeveloperError();
  });
  it("set throws if zIndex is not a number", function() {
    expect(function() {
      const collection = new OrderedGroundPrimitiveCollection_default();
      collection.set(new MockPrimitive(), "3");
    }).toThrowDeveloperError();
  });
  it("set adds primitive if it is not in the collection", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    collection.set(new MockPrimitive(), 3);
    expect(collection.length).toBe(1);
  });
  it("set changes a primitives index", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive(), 0);
    const p2 = collection.add(new MockPrimitive(), 0);
    const p3 = collection.add(new MockPrimitive(), 2);
    const p4 = collection.add(new MockPrimitive(), 1);
    expect(collection.length).toBe(4);
    collection.set(p4, 2);
    expect(collection.length).toBe(4);
    const array = collection._collectionsArray;
    expect(array.length).toBe(2);
    expect(array[0].length).toBe(2);
    expect(array[0].get(0)).toBe(p1);
    expect(array[0].get(1)).toBe(p2);
    expect(array[1].length).toBe(2);
    expect(array[1].get(0)).toBe(p3);
    expect(array[1].get(1)).toBe(p4);
  });
  it("set works with negative indexes", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive(), 0);
    const p2 = collection.add(new MockPrimitive(), 0);
    expect(collection.length).toBe(2);
    collection.set(p2, -1);
    const array = collection._collectionsArray;
    expect(array.length).toBe(2);
    expect(array[0].length).toBe(1);
    expect(array[0].get(0)).toBe(p2);
    expect(array[1].length).toBe(1);
    expect(array[1].get(0)).toBe(p1);
  });
  it("set throws without primitive", function() {
    expect(function() {
      const collection = new OrderedGroundPrimitiveCollection_default();
      collection.set(void 0, 3);
    }).toThrowDeveloperError();
  });
  it("removes a primitive", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p2 = collection.add(new MockPrimitive());
    const result = collection.remove(p2);
    expect(result).toBe(true);
    expect(collection.length).toBe(0);
    expect(collection._collectionsArray.length).toBe(0);
    expect(p2.isDestroyed()).toBe(true);
  });
  it("removes handles multiple zIndexes", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive(), 0);
    const p2 = collection.add(new MockPrimitive(), 2);
    const p3 = collection.add(new MockPrimitive(), 2);
    const p4 = collection.add(new MockPrimitive(), 1);
    expect(collection.length).toBe(4);
    const array = collection._collectionsArray;
    expect(array.length).toBe(3);
    collection.remove(p3);
    expect(array.length).toBe(3);
    collection.remove(p2);
    expect(array.length).toBe(2);
    expect(array[0].get(0)).toBe(p1);
    expect(array[1].get(0)).toBe(p4);
  });
  it("removes null", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    expect(collection.remove()).toEqual(false);
  });
  it("removeAll removes and destroys all primitives", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive(), 0);
    const p2 = collection.add(new MockPrimitive(), 0);
    const p3 = collection.add(new MockPrimitive(), 2);
    const p4 = collection.add(new MockPrimitive(), 1);
    expect(collection.length).toBe(4);
    collection.removeAll();
    expect(collection.length).toBe(0);
    expect(p1.isDestroyed()).toBe(true);
    expect(p2.isDestroyed()).toBe(true);
    expect(p3.isDestroyed()).toBe(true);
    expect(p4.isDestroyed()).toBe(true);
  });
  it("contains primitive", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive());
    expect(collection.contains(p1)).toBe(true);
  });
  it("does not contain primitive", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = new MockPrimitive();
    expect(collection.contains(p1)).toBe(false);
  });
  it("does not contain undefined", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    expect(collection.contains()).toEqual(false);
  });
  it("update is called in the correct order", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    const p1 = collection.add(new MockPrimitive(), 0);
    const p2 = collection.add(new MockPrimitive(), 3);
    const p3 = collection.add(new MockPrimitive(), 1);
    const p4 = collection.add(new MockPrimitive(), 2);
    collection.update();
    expect(updateCallOrder).toEqual([p1, p3, p4, p2]);
    updateCallOrder = [];
    collection.set(p1, 4);
    collection.update();
    expect(updateCallOrder).toEqual([p3, p4, p2, p1]);
    updateCallOrder = [];
    collection.set(p2, 0);
    collection.update();
    expect(updateCallOrder).toEqual([p2, p3, p4, p1]);
    updateCallOrder = [];
    collection.set(p4, -1);
    collection.update();
    expect(updateCallOrder).toEqual([p4, p2, p3, p1]);
  });
  it("update is not called when show is false", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    collection.add(new MockPrimitive(), 0);
    collection.add(new MockPrimitive(), 3);
    collection.show = false;
    collection.update();
    expect(updateCallOrder).toEqual([]);
  });
  it("destroys", function() {
    const collection = new OrderedGroundPrimitiveCollection_default();
    expect(collection.isDestroyed()).toBe(false);
    collection.destroy();
    expect(collection.isDestroyed()).toBe(true);
  });
});

// packages/engine/Specs/Scene/PanoramaSpec.js
