    it("renders with distance display condition per instance attribute", function() {
      if (!context.floatingPointTexture) {
        return;
      }
      const near = 1e4;
      const far = 1e6;
      const rect = Rectangle_default.fromDegrees(-1, -1, 1, 1);
      const translation3 = Cartesian3_default.multiplyByScalar(
        Cartesian3_default.normalize(
          ellipsoid.cartographicToCartesian(Rectangle_default.center(rect)),
          new Cartesian3_default()
        ),
        2,
        new Cartesian3_default()
      );
      const rectInstance = new GeometryInstance_default({
        geometry: new RectangleGeometry_default({
          vertexFormat: PerInstanceColorAppearance_default.VERTEX_FORMAT,
          ellipsoid,
          rectangle: rect
        }),
        modelMatrix: Matrix4_default.fromTranslation(translation3, new Matrix4_default()),
        id: "rect",
        attributes: {
          color: new ColorGeometryInstanceAttribute_default(1, 1, 0, 1),
          distanceDisplayCondition: new DistanceDisplayConditionGeometryInstanceAttribute_default(near, far)
        }
      });
      primitive = new Primitive_default({
        geometryInstances: rectInstance,
        appearance: new PerInstanceColorAppearance_default(),
        asynchronous: false
      });
      scene2.primitives.add(primitive);
      scene2.camera.setView({ destination: rect });
      scene2.renderForSpecs();
      const boundingSphere = primitive.getGeometryInstanceAttributes("rect").boundingSphere;
      const center = boundingSphere.center;
      const radius = boundingSphere.radius;
      scene2.camera.lookAt(
        center,
        new HeadingPitchRange_default(0, -Math_default.PI_OVER_TWO, radius)
      );
      expect(scene2).toRender([0, 0, 0, 255]);
      scene2.camera.lookAt(
        center,
        new HeadingPitchRange_default(
          0,
          -Math_default.PI_OVER_TWO,
          radius + near + 1
        )
      );
      expect(scene2).notToRender([0, 0, 0, 255]);
      scene2.camera.lookAt(
        center,
        new HeadingPitchRange_default(0, -Math_default.PI_OVER_TWO, radius + far + 1)
      );
      expect(scene2).toRender([0, 0, 0, 255]);
    });
