describe("Scene/processVoxelProperties", function() {
  let scene2;
  let provider;
  beforeAll(async function() {
    scene2 = createScene_default();
    provider = await Cesium3DTilesVoxelProvider_default.fromUrl(
      "./Data/Cesium3DTiles/Voxel/VoxelEllipsoid3DTiles/tileset.json"
    );
  });
  afterAll(function() {
    scene2.destroyForSpecs();
  });
  it("adds shader defines and structs", async function() {
    const primitive = new VoxelPrimitive_default({ provider });
    primitive.update(scene2.frameState);
    const renderResources = new VoxelRenderResources_default(primitive);
    processVoxelProperties_default(renderResources, primitive);
    const { shaderBuilder } = renderResources;
    ShaderBuilderTester_default.expectFragmentLinesContains(shaderBuilder, [
      "#define METADATA_COUNT 1",
      "#define STATISTICS"
    ]);
    const propertyStatisticsFields = ["    float min;", "    float max;"];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "PropertyStatistics_a",
      "PropertyStatistics_a",
      propertyStatisticsFields
    );
    const metadataStatisticsFields = ["    PropertyStatistics_a a;"];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "MetadataStatistics",
      "MetadataStatistics",
      metadataStatisticsFields
    );
    const metadataFields = ["    float a;"];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "Metadata",
      "Metadata",
      metadataFields
    );
    const attributesFields = ["    vec3 positionEC;", "    vec3 normalEC;"];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "Attributes",
      "Attributes",
      attributesFields
    );
    const voxelFields = [
      "    vec3 viewDirUv;",
      "    float travelDistance;",
      "    int stepCount;",
      "    int sampleIndex;",
      "    int tileIndex;",
      "    float distanceToDepthBuffer;"
    ];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "Voxel",
      "Voxel",
      voxelFields
    );
    const fragmentInputFields = [
      "    MetadataStatistics metadataStatistics;",
      "    Metadata metadata;",
      "    Attributes attributes;",
      "    Voxel voxel;"
    ];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "FragmentInput",
      "FragmentInput",
      fragmentInputFields
    );
    const propertiesFields = ["    float a;"];
    ShaderBuilderTester_default.expectHasFragmentStruct(
      shaderBuilder,
      "Properties",
      "Properties",
      propertiesFields
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "clearProperties",
      "Properties clearProperties()",
      [
        "    Properties properties;",
        "    properties.a = float(0.0);",
        "    return properties;"
      ]
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "sumProperties",
      "Properties sumProperties(Properties propertiesA, Properties propertiesB)",
      [
        "    Properties properties;",
        "    properties.a = propertiesA.a + propertiesB.a;",
        "    return properties;"
      ]
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "scaleProperties",
      "Properties scaleProperties(Properties properties, float scale)",
      [
        "    Properties scaledProperties = properties;",
        "    scaledProperties.a *= scale;",
        "    return scaledProperties;"
      ]
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "mixProperties",
      "Properties mixProperties(Properties propertiesA, Properties propertiesB, float mixFactor)",
      [
        "    Properties properties;",
        "    properties.a = mix(propertiesA.a, propertiesB.a, mixFactor);",
        "    return properties;"
      ]
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "copyPropertiesToMetadata",
      "void copyPropertiesToMetadata(in Properties properties, inout Metadata metadata)",
      ["    metadata.a = properties.a;"]
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "setStatistics",
      "void setStatistics(inout MetadataStatistics metadataStatistics)",
      [
        "    metadataStatistics.a.min = 0.0;",
        "    metadataStatistics.a.max = 1.0;"
      ]
    );
    ShaderBuilderTester_default.expectHasFragmentFunctionUnordered(
      shaderBuilder,
      "getPropertiesFromMegatextureAtUv",
      "Properties getPropertiesFromMegatextureAtUv(vec3 texcoord)",
      [
        "    Properties properties;",
        "    properties.a = texture(u_megatextureTextures[0], texcoord).r;",
        "    return properties;"
      ]
    );
  });
});

// packages/engine/Specs/Scene/PropertyAttributePropertySpec.js
describe("Scene/PropertyAttributeProperty", function() {
  let classProperty;
  let extras;
  let extensions;
  let propertyAttributeProperty;
  beforeAll(function() {
    classProperty = MetadataClassProperty_default.fromJson({
      id: "intensity",
      property: {
        type: "SCALAR",
        componentType: "FLOAT32"
      }
    });
    extras = {
      description: "Extra"
    };
    extensions = {
      EXT_other_extension: {}
    };
    const property = {
      attribute: "_INTENSITY",
      extensions,
      extras
    };
    propertyAttributeProperty = new PropertyAttributeProperty_default({
      property,
      classProperty
    });
  });
  it("creates property attribute property", function() {
    expect(propertyAttributeProperty.attribute).toBe("_INTENSITY");
    expect(propertyAttributeProperty.hasValueTransform).toBe(false);
    expect(propertyAttributeProperty.offset).toBe(0);
    expect(propertyAttributeProperty.scale).toBe(1);
    expect(propertyAttributeProperty.extras).toBe(extras);
    expect(propertyAttributeProperty.extensions).toBe(extensions);
    expect(propertyAttributeProperty.classProperty).toBe(classProperty);
  });
  it("constructor throws without property", function() {
    expect(function() {
      return new PropertyAttributeProperty_default({
        property: void 0,
        classProperty
      });
    }).toThrowDeveloperError();
  });
  it("constructor throws without classProperty", function() {
    expect(function() {
      return new PropertyAttributeProperty_default({
        property: {},
        classProperty: void 0
      });
    }).toThrowDeveloperError();
  });
  it("creates property with value transform from class definition", function() {
    const classProperty2 = MetadataClassProperty_default.fromJson({
      id: "transformed",
      property: {
        type: "SCALAR",
        componentType: "UINT8",
        normalized: true,
        offset: 1,
        scale: 2
      }
    });
    propertyAttributeProperty = new PropertyAttributeProperty_default({
      property: {
        attribute: "_TRANSFORMED"
      },
      classProperty: classProperty2
    });
    expect(propertyAttributeProperty.attribute).toBe("_TRANSFORMED");
    expect(propertyAttributeProperty.hasValueTransform).toBe(true);
    expect(propertyAttributeProperty.offset).toBe(1);
    expect(propertyAttributeProperty.scale).toBe(2);
  });
  it("creates property with value transform override", function() {
    const classProperty2 = MetadataClassProperty_default.fromJson({
      id: "transformed",
      property: {
        type: "SCALAR",
        componentType: "UINT8",
        normalized: true,
        offset: 1,
        scale: 2
      }
    });
    propertyAttributeProperty = new PropertyAttributeProperty_default({
      property: {
        attribute: "_TRANSFORMED",
        offset: 2,
        scale: 4
      },
      classProperty: classProperty2
    });
    expect(propertyAttributeProperty.attribute).toBe("_TRANSFORMED");
    expect(propertyAttributeProperty.hasValueTransform).toBe(true);
    expect(propertyAttributeProperty.offset).toBe(2);
    expect(propertyAttributeProperty.scale).toBe(4);
  });
  it("unpacks property and scale for vectors and matrices", function() {
    let classProperty2 = MetadataClassProperty_default.fromJson({
      id: "transformed",
      property: {
        type: "VEC2",
        componentType: "UINT8",
        normalized: true,
        offset: [1, 2],
        scale: [2, 4]
      }
    });
    propertyAttributeProperty = new PropertyAttributeProperty_default({
      property: {
        attribute: "_TRANSFORMED"
      },
      classProperty: classProperty2
    });
    expect(propertyAttributeProperty.attribute).toBe("_TRANSFORMED");
    expect(propertyAttributeProperty.hasValueTransform).toBe(true);
    expect(propertyAttributeProperty.offset).toEqual(new Cartesian2_default(1, 2));
    expect(propertyAttributeProperty.scale).toEqual(new Cartesian2_default(2, 4));
    classProperty2 = MetadataClassProperty_default.fromJson({
      id: "transformed",
      property: {
        type: "MAT2",
        componentType: "UINT8",
        normalized: true,
        offset: [1, 2, 2, 1],
        scale: [2, 4, 4, 1]
      }
    });
    propertyAttributeProperty = new PropertyAttributeProperty_default({
      property: {
        attribute: "_TRANSFORMED"
      },
      classProperty: classProperty2
    });
    expect(propertyAttributeProperty.attribute).toBe("_TRANSFORMED");
    expect(propertyAttributeProperty.hasValueTransform).toBe(true);
    expect(propertyAttributeProperty.offset).toEqual(new Matrix2_default(1, 2, 2, 1));
    expect(propertyAttributeProperty.scale).toEqual(new Matrix2_default(2, 4, 4, 1));
  });
});

