// packages/engine/Specs/Scene/ResourceCacheStatisticsSpec.js
describe("Scene/ResourceCacheStatistics", function() {
  it("constructs", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2._geometrySizes).toEqual({});
    expect(statistics2._textureSizes).toEqual({});
  });
  function mockLoader(cacheKey, data) {
    return combine_default(data, {
      cacheKey
    });
  }
  it("clears", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const geometryLoader = mockLoader("vertices", {
      buffer: {
        sizeInBytes: 100
      }
    });
    const textureLoader = mockLoader("texture", {
      texture: {
        sizeInBytes: 300
      }
    });
    statistics2.addGeometryLoader(geometryLoader);
    statistics2.addTextureLoader(textureLoader);
    expect(statistics2.geometryByteLength).not.toBe(0);
    expect(statistics2.texturesByteLength).not.toBe(0);
    expect(statistics2._geometrySizes).not.toEqual({});
    expect(statistics2._textureSizes).not.toEqual({});
    statistics2.clear();
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2._geometrySizes).toEqual({});
    expect(statistics2._textureSizes).toEqual({});
  });
  it("addGeometryLoader throws for undefined loader", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    expect(function() {
      statistics2.addGeometryLoader(void 0);
    }).toThrowDeveloperError();
  });
  it("addGeometryLoader counts geometry memory", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const geometryLoader = mockLoader("vertices", {
      buffer: {
        sizeInBytes: 100
      }
    });
    statistics2.addGeometryLoader(geometryLoader);
    expect(statistics2.geometryByteLength).toBe(100);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2._geometrySizes).toEqual({ vertices: 100 });
    expect(statistics2._textureSizes).toEqual({});
  });
  it("addGeometryLoader counts buffers with typed arrays", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const geometryLoader = mockLoader("vertices", {
      buffer: {
        sizeInBytes: 100
      },
      typedArray: new Uint8Array(100)
    });
    statistics2.addGeometryLoader(geometryLoader);
    expect(statistics2.geometryByteLength).toBe(200);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2._geometrySizes).toEqual({ vertices: 200 });
    expect(statistics2._textureSizes).toEqual({});
  });
  it("addGeometryLoader does not double count memory", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const geometryLoader = mockLoader("vertices", {
      buffer: {
        sizeInBytes: 100
      },
      typedArray: new Uint8Array(100)
    });
    statistics2.addGeometryLoader(geometryLoader);
    statistics2.addGeometryLoader(geometryLoader);
    expect(statistics2.geometryByteLength).toBe(200);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2._geometrySizes).toEqual({ vertices: 200 });
    expect(statistics2._textureSizes).toEqual({});
  });
  it("addTextureLoader throws for undefined loader", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    expect(function() {
      statistics2.addTextureLoader(void 0);
    }).toThrowDeveloperError();
  });
  it("addTextureLoader counts texture memory", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const textureLoader = mockLoader("texture", {
      texture: {
        sizeInBytes: 100
      }
    });
    statistics2.addTextureLoader(textureLoader);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(100);
    expect(statistics2._geometrySizes).toEqual({});
    expect(statistics2._textureSizes).toEqual({ texture: 100 });
  });
  it("addTextureLoader does not double count memory", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const textureLoader = mockLoader("texture", {
      texture: {
        sizeInBytes: 100
      }
    });
    statistics2.addTextureLoader(textureLoader);
    statistics2.addTextureLoader(textureLoader);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(100);
    expect(statistics2._geometrySizes).toEqual({});
    expect(statistics2._textureSizes).toEqual({ texture: 100 });
  });
  it("removeLoader throws for undefined loader", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    expect(function() {
      statistics2.removeLoader(void 0);
    }).toThrowDeveloperError();
  });
  it("removeLoader correctly updates memory for buffers", function() {
    const geometryLoader = mockLoader("vertices", {
      buffer: {
        sizeInBytes: 100
      }
    });
    const geometryLoader2 = mockLoader("indices", {
      buffer: {
        sizeInBytes: 200
      }
    });
    const textureLoader = mockLoader("texture", {
      texture: {
        sizeInBytes: 300
      }
    });
    const statistics2 = new ResourceCacheStatistics_default();
    statistics2.addGeometryLoader(geometryLoader);
    statistics2.addGeometryLoader(geometryLoader2);
    statistics2.addTextureLoader(textureLoader);
    expect(statistics2.geometryByteLength).toBe(300);
    expect(statistics2.texturesByteLength).toBe(300);
    expect(statistics2._geometrySizes).toEqual({
      vertices: 100,
      indices: 200
    });
    statistics2.removeLoader(geometryLoader2);
    expect(statistics2.geometryByteLength).toBe(100);
    expect(statistics2.texturesByteLength).toBe(300);
    expect(statistics2._geometrySizes).toEqual({ vertices: 100 });
    expect(statistics2._textureSizes).toEqual({ texture: 300 });
  });
  it("removeLoader correctly updates memory for textures", function() {
    const geometryLoader = mockLoader("vertices", {
      buffer: {
        sizeInBytes: 100
      }
    });
    const textureLoader = mockLoader("texture", {
      texture: {
        sizeInBytes: 300
      }
    });
    const textureLoader2 = mockLoader("texture2", {
      texture: {
        sizeInBytes: 500
      }
    });
    const statistics2 = new ResourceCacheStatistics_default();
    statistics2.addGeometryLoader(geometryLoader);
    statistics2.addTextureLoader(textureLoader);
    statistics2.addTextureLoader(textureLoader2);
    expect(statistics2.geometryByteLength).toBe(100);
    expect(statistics2.texturesByteLength).toBe(800);
    expect(statistics2._geometrySizes).toEqual({ vertices: 100 });
    expect(statistics2._textureSizes).toEqual({
      texture: 300,
      texture2: 500
    });
    statistics2.removeLoader(textureLoader2);
    expect(statistics2.geometryByteLength).toBe(100);
    expect(statistics2.texturesByteLength).toBe(300);
    expect(statistics2._geometrySizes).toEqual({ vertices: 100 });
    expect(statistics2._textureSizes).toEqual({ texture: 300 });
  });
  it("removeLoader gracefully handles loader without tracked resources", function() {
    const statistics2 = new ResourceCacheStatistics_default();
    const textureLoader = mockLoader("texture", {
      texture: {
        sizeInBytes: 300
      }
    });
    expect(function() {
      statistics2.removeLoader(textureLoader);
    }).not.toThrowDeveloperError();
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2._geometrySizes).toEqual({});
    expect(statistics2._textureSizes).toEqual({});
  });
});

// packages/engine/Specs/Scene/ResourceLoaderSpec.js
describe("Scene/ResourceLoader", function() {
  it("throws when using ResourceLoader directly", function() {
    const resourceLoader = new ResourceLoader_default();
    expect(function() {
      return resourceLoader.cacheKey;
    }).toThrowDeveloperError();
    expect(function() {
      resourceLoader.load();
    }).toThrowDeveloperError();
  });
  it("getError from error message", function() {
    const resourceLoader = new ResourceLoader_default();
    const errorMessage = "Resource failed";
    const runtimeError = resourceLoader.getError(errorMessage);
    expect(runtimeError.message).toBe(errorMessage);
  });
  it("getError from error message and error", function() {
    const resourceLoader = new ResourceLoader_default();
    const errorMessage = "Resource failed";
    const error = new Error("404 Not Found");
    const runtimeError = resourceLoader.getError(errorMessage, error);
    expect(runtimeError.message).toBe("Resource failed\n404 Not Found");
  });
  it("getError throws if errorMessage is undefined", function() {
    const resourceLoader = new ResourceLoader_default();
    expect(function() {
      resourceLoader.getError();
    }).toThrowDeveloperError();
  });
  it("destroys", function() {
    const resourceLoader = new ResourceLoader_default();
    expect(resourceLoader.isDestroyed()).toBe(false);
    resourceLoader.destroy();
    expect(resourceLoader.isDestroyed()).toBe(true);
  });
});

// Specs/render.js
function executeCommands3(frameState2, commands) {
  let commandsExecuted = 0;
  const cullingVolume = frameState2.cullingVolume;
  let occluder;
  if (frameState2.mode === SceneMode_default.SCENE3D) {
    occluder = frameState2.occluder;
  }
  const length3 = commands.length;
  for (let i = 0; i < length3; ++i) {
    const command = commands[i];
    const boundingVolume = command.boundingVolume;
    if (defined_default(boundingVolume)) {
      if (cullingVolume.computeVisibility(boundingVolume) === Intersect_default.OUTSIDE || defined_default(occluder) && !occluder.isBoundingSphereVisible(boundingVolume)) {
        continue;
      }
    }
    command.execute(frameState2.context);
    commandsExecuted++;
  }
  return commandsExecuted;
}
function render2(frameState2, primitive) {
  frameState2.commandList.length = 0;
  primitive.update(frameState2);
  let i;
  const renderCommands = new Array(Pass_default.NUMBER_OF_PASSES);
  for (i = 0; i < Pass_default.NUMBER_OF_PASSES; ++i) {
    renderCommands[i] = [];
  }
  const commands = frameState2.commandList;
  const length3 = commands.length;
  for (i = 0; i < length3; i++) {
    const command = commands[i];
    const pass = defined_default(command.pass) ? command.pass : Pass_default.OPAQUE;
    renderCommands[pass].push(command);
  }
  let commandsExecuted = 0;
  for (i = 0; i < Pass_default.NUMBER_OF_PASSES; ++i) {
    commandsExecuted += executeCommands3(frameState2, renderCommands[i]);
  }
  return commandsExecuted;
}
var render_default = render2;

