async function loadAsModel(scene2, gltf) {
  const basePath = "SPEC_BASE_PATH";
  const model = await Model_default.fromGltfAsync({
    gltf,
    basePath,
    // This is important to make sure that the property
    // texture is fully loaded when the model is rendered!
    incrementallyLoadTextures: false
  });
  scene2.primitives.add(model);
  await pollToPromise_default(
    function() {
      scene2.renderForSpecs();
      return model.ready;
    },
    { timeout: 1e4 }
  );
}
function fitCameraToUnitSquare(camera) {
  const fov = Math_default.PI_OVER_THREE;
  camera.frustum.fov = fov;
  camera.frustum.near = 0.01;
  camera.frustum.far = 100;
  const distance2 = 1 / (2 * Math.tan(fov * 0.5));
  camera.position = new Cartesian3_default(distance2, 0.5, 0.5);
  camera.direction = Cartesian3_default.negate(Cartesian3_default.UNIT_X, new Cartesian3_default());
  camera.up = Cartesian3_default.clone(Cartesian3_default.UNIT_Z);
  camera.right = Cartesian3_default.clone(Cartesian3_default.UNIT_Y);
}
function pickMetadataAt(scene2, schemaId, className, propertyName, x, y) {
  const screenX = Math.floor(x * canvasScaling + canvasScaling / 2);
  const screenY = Math.floor(y * canvasScaling + canvasScaling / 2);
  const screenPosition = new Cartesian2_default(screenX, screenY);
  const metadataValue = scene2.pickMetadata(
    screenPosition,
    schemaId,
    className,
    propertyName
  );
  return metadataValue;
}
