    it("pickAsync", async function() {
      if (webglStub) {
        return;
      }
      const rectangle = Rectangle_default.fromDegrees(-1, -1, 1, 1);
      const rectanglePrimitive = createRectangle(rectangle);
      const primitives = scene2.primitives;
      primitives.add(rectanglePrimitive);
      scene2.camera.setView({ destination: rectangle });
      const windowPosition = new Cartesian2_default(0, 0);
      let result;
      let ready = false;
      let threw = false;
      scene2.pickAsync(windowPosition).then((result0) => {
        result = result0;
        ready = true;
      }).catch((_error) => {
        threw = true;
      });
      await pollToPromise_default(function() {
        scene2.renderForSpecs();
        return ready || threw;
      });
      expect(scene2.context.webgl2).toBeTrue();
      expect(threw).toBeFalse();
      expect(ready).toBeTrue();
      expect(result).toBeDefined();
      expect(result.primitive).toEqual(rectanglePrimitive);
    });
