// packages/engine/Specs/Scene/SceneTransformsSpec.js
describe(
  "Scene/SceneTransforms",
  function() {
    let scene2;
    let defaultCamera;
    beforeAll(function() {
      scene2 = createScene_default();
      defaultCamera = Camera_default.clone(scene2.camera);
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    beforeEach(function() {
      scene2.mode = SceneMode_default.SCENE3D;
      scene2.camera.position = defaultCamera.position.clone();
      scene2.camera.direction = defaultCamera.direction.clone();
      scene2.camera.up = defaultCamera.up.clone();
      scene2.camera.right = defaultCamera.right.clone();
      scene2.camera._transform = defaultCamera.transform.clone();
      scene2.camera.frustum = defaultCamera.frustum.clone();
    });
    it("throws an exception without scene", function() {
      const position = Cartesian3_default.fromDegrees(0, 0);
      expect(function() {
        SceneTransforms_default.worldToWindowCoordinates(void 0, position);
      }).toThrowDeveloperError();
    });
    it("throws an exception without position", function() {
      expect(function() {
        SceneTransforms_default.worldToWindowCoordinates(scene2);
      }).toThrowDeveloperError();
    });
    it("returns correct window position in 3D", function() {
      const ellipsoid = Ellipsoid_default.WGS84;
      const positionCartographic = ellipsoid.cartesianToCartographic(
        scene2.camera.position
      );
      positionCartographic.height = 0;
      const position = ellipsoid.cartographicToCartesian(positionCartographic);
      scene2.renderForSpecs();
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene2,
        position
      );
      expect(windowCoordinates.x).toEqualEpsilon(0.5, Math_default.EPSILON2);
      expect(windowCoordinates.y).toEqualEpsilon(0.5, Math_default.EPSILON2);
    });
    it("returns correct drawing buffer position in 3D", function() {
      const ellipsoid = Ellipsoid_default.WGS84;
      const positionCartographic = ellipsoid.cartesianToCartographic(
        scene2.camera.position
      );
      positionCartographic.height = 0;
      const position = ellipsoid.cartographicToCartesian(positionCartographic);
      scene2.renderForSpecs();
      const drawingBufferCoordinates = SceneTransforms_default.worldToDrawingBufferCoordinates(scene2, position);
      expect(drawingBufferCoordinates.x).toEqualEpsilon(
        0.5,
        Math_default.EPSILON2
      );
      expect(drawingBufferCoordinates.y).toEqualEpsilon(
        0.5,
        Math_default.EPSILON2
      );
    });
    it("returns undefined for window position behind camera in 3D", function() {
      const ellipsoid = Ellipsoid_default.WGS84;
      const positionCartographic = ellipsoid.cartesianToCartographic(
        scene2.camera.position
      );
      positionCartographic.height *= 1.1;
      const position = ellipsoid.cartographicToCartesian(positionCartographic);
      scene2.renderForSpecs();
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene2,
        position
      );
      expect(windowCoordinates).not.toBeDefined();
    });
    it("returns undefined for drawing buffer position behind camera in 3D", function() {
      const ellipsoid = Ellipsoid_default.WGS84;
      const positionCartographic = ellipsoid.cartesianToCartographic(
        scene2.camera.position
      );
      positionCartographic.height *= 1.1;
      const position = ellipsoid.cartographicToCartesian(positionCartographic);
      scene2.renderForSpecs();
      const drawingBufferCoordinates = SceneTransforms_default.worldToDrawingBufferCoordinates(scene2, position);
      expect(drawingBufferCoordinates).not.toBeDefined();
    });
    it("returns correct window position in ColumbusView", function() {
      scene2.morphToColumbusView(0);
      scene2.renderForSpecs();
      const actualWindowCoordinates = new Cartesian2_default(0.5, 0.5);
      const position = scene2.camera.pickEllipsoid(actualWindowCoordinates);
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene2,
        position
      );
      expect(windowCoordinates).toEqualEpsilon(
        actualWindowCoordinates,
        Math_default.EPSILON2
      );
    });
    it("returns correct drawing buffer position in ColumbusView", function() {
      scene2.morphToColumbusView(0);
      scene2.renderForSpecs();
      const actualDrawingBufferCoordinates = new Cartesian2_default(0.5, 0.5);
      const position = scene2.camera.pickEllipsoid(
        actualDrawingBufferCoordinates
      );
      const drawingBufferCoordinates = SceneTransforms_default.worldToDrawingBufferCoordinates(scene2, position);
      expect(drawingBufferCoordinates).toEqualEpsilon(
        actualDrawingBufferCoordinates,
        Math_default.EPSILON2
      );
    });
    it("returns undefined for window position behind camera in ColumbusView", function() {
      scene2.morphToColumbusView(0);
      scene2.renderForSpecs();
      const position = new Cartesian3_default();
      Cartesian3_default.normalize(scene2.camera.position, position);
      Cartesian3_default.add(position, scene2.camera.direction, position);
      Cartesian3_default.multiplyByScalar(
        scene2.camera.direction,
        -1,
        scene2.camera.direction
      );
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene2,
        position
      );
      expect(windowCoordinates).not.toBeDefined();
    });
    it("returns undefined for drawing buffer position behind camera in ColumbusView", function() {
      scene2.morphToColumbusView(0);
      scene2.renderForSpecs();
      const position = new Cartesian3_default();
      Cartesian3_default.normalize(scene2.camera.position, position);
      Cartesian3_default.add(position, scene2.camera.direction, position);
      Cartesian3_default.multiplyByScalar(
        scene2.camera.direction,
        -1,
        scene2.camera.direction
      );
      const drawingBufferCoordinates = SceneTransforms_default.worldToDrawingBufferCoordinates(scene2, position);
      expect(drawingBufferCoordinates).not.toBeDefined();
    });
    it("returns correct window position in 2D", function() {
      scene2.camera.setView({
        destination: Rectangle_default.fromDegrees(
          -1e-6,
          -1e-6,
          1e-6,
          1e-6
        )
      });
      scene2.morphTo2D(0);
      scene2.renderForSpecs();
      const position = Cartesian3_default.fromDegrees(0, 0);
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene2,
        position
      );
      expect(windowCoordinates.x).toBeGreaterThan(0);
      expect(windowCoordinates.y).toBeGreaterThan(0);
      expect(windowCoordinates.x).toBeLessThan(1);
      expect(windowCoordinates.y).toBeLessThan(1);
    });
    it("returns correct window position in 3D with orthographic frustum", function() {
      const frustum = new OrthographicFrustum_default();
      frustum.aspectRatio = 1;
      frustum.width = 20;
      scene2.camera.frustum = frustum;
      scene2.renderForSpecs();
      scene2.camera.setView({
        destination: Rectangle_default.fromDegrees(
          -1e-6,
          -1e-6,
          1e-6,
          1e-6
        )
      });
      const position = Cartesian3_default.fromDegrees(0, 0);
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene2,
        position
      );
      expect(windowCoordinates.x).toBeGreaterThan(0);
      expect(windowCoordinates.y).toBeGreaterThan(0);
      expect(windowCoordinates.x).toBeLessThan(1);
      expect(windowCoordinates.y).toBeLessThan(1);
    });
    it("returns correct drawing buffer position in 2D", function() {
      scene2.camera.setView({
        destination: Rectangle_default.fromDegrees(
          -1e-6,
          -1e-6,
          1e-6,
          1e-6
        )
      });
      scene2.morphTo2D(0);
      scene2.renderForSpecs();
      const position = Cartesian3_default.fromDegrees(0, 0);
      const drawingBufferCoordinates = SceneTransforms_default.worldToDrawingBufferCoordinates(scene2, position);
      expect(drawingBufferCoordinates.x).toBeGreaterThan(0);
      expect(drawingBufferCoordinates.y).toBeGreaterThan(0);
      expect(drawingBufferCoordinates.x).toBeLessThan(1);
      expect(drawingBufferCoordinates.y).toBeLessThan(1);
    });
    it("should not error when zoomed out and in 2D", function() {
      const scene3 = createScene_default();
      scene3.camera.setView({
        destination: Cartesian3_default.fromDegrees(75, 15, 3e7)
      });
      scene3.morphTo2D(0);
      scene3.renderForSpecs();
      const position = Cartesian3_default.fromDegrees(-80, 25);
      const windowCoordinates = SceneTransforms_default.worldToWindowCoordinates(
        scene3,
        position
      );
      expect(windowCoordinates).toBeDefined();
      scene3.destroyForSpecs();
    });
    it("actualEllipsoidPositionToCartographic converts an ECEF position in 3D", function() {
      const cartographic2 = Cartographic_default.fromDegrees(-75, 40, 100);
      const position = Ellipsoid_default.WGS84.cartographicToCartesian(cartographic2);
      scene2.renderForSpecs();
      const result = SceneTransforms_default.actualEllipsoidPositionToCartographic(
        scene2.frameState,
        position
      );
      expect(result.longitude).toEqualEpsilon(
        cartographic2.longitude,
        Math_default.EPSILON8
      );
      expect(result.latitude).toEqualEpsilon(
        cartographic2.latitude,
        Math_default.EPSILON8
      );
      expect(result.height).toEqualEpsilon(
        cartographic2.height,
        Math_default.EPSILON4
      );
    });
    it("actualEllipsoidPositionToCartographic unprojects a swizzled map position in Columbus View", function() {
      scene2.morphToColumbusView(0);
      scene2.renderForSpecs();
      const projection = scene2.frameState.mapProjection;
      const cartographic2 = Cartographic_default.fromDegrees(-75, 40, 100);
      const projected = projection.project(cartographic2);
      const position = new Cartesian3_default(projected.z, projected.x, projected.y);
      const result = SceneTransforms_default.actualEllipsoidPositionToCartographic(
        scene2.frameState,
        position
      );
      expect(result.longitude).toEqualEpsilon(
        cartographic2.longitude,
        Math_default.EPSILON8
      );
      expect(result.latitude).toEqualEpsilon(
        cartographic2.latitude,
        Math_default.EPSILON8
      );
      expect(result.height).toEqualEpsilon(
        cartographic2.height,
        Math_default.EPSILON4
      );
    });
  },
  "WebGL"
);

