          negativeX: new Uint8Array([33, 32, 40, 255]),
          positiveY: new Uint8Array([255, 255, 255, 255]),
          negativeY: new Uint8Array([72, 56, 35, 255]),
          positiveZ: new Uint8Array([255, 255, 255, 255]),
