// packages/engine/Specs/Scene/SunSpec.js
describe(
  "Scene/Sun",
  function() {
    let scene2;
    const backgroundColor = [255, 0, 0, 255];
    beforeAll(function() {
      scene2 = createScene_default();
      scene2.backgroundColor = Color_default.unpack(backgroundColor);
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    beforeEach(function() {
      scene2.mode = SceneMode_default.SCENE3D;
    });
    afterEach(function() {
      scene2.sun = void 0;
    });
    function viewSun(camera, uniformState) {
      const sunPosition = uniformState.sunPositionWC;
      const bounds = new BoundingSphere_default(sunPosition, Math_default.SOLAR_RADIUS);
      camera.viewBoundingSphere(bounds);
    }
    it("draws in 3D", function() {
      expect(scene2).toRender(backgroundColor);
      scene2.sun = new Sun_default();
      scene2.sun.glowFactor = 100;
      scene2.render();
      viewSun(scene2.camera, scene2.context.uniformState);
      expect(scene2).notToRender(backgroundColor);
    });
    it("draws in Columbus view", function() {
      expect(scene2).toRender(backgroundColor);
      scene2.mode = SceneMode_default.COLUMBUS_VIEW;
      scene2.sun = new Sun_default();
      scene2.render();
      viewSun(scene2.camera, scene2.context.uniformState);
      expect(scene2).notToRender(backgroundColor);
    });
    it("does not render when show is false", function() {
      expect(scene2).toRender(backgroundColor);
      scene2.sun = new Sun_default();
      scene2.render();
      scene2.sun.show = false;
      viewSun(scene2.camera, scene2.context.uniformState);
      expect(scene2).toRender(backgroundColor);
    });
    it("does not render in 2D", function() {
      expect(scene2).toRender(backgroundColor);
      scene2.mode = SceneMode_default.SCENE2D;
      scene2.sun = new Sun_default();
      scene2.render();
      viewSun(scene2.camera, scene2.context.uniformState);
      expect(scene2).toRender(backgroundColor);
    });
    it("does not render without a render pass", function() {
      scene2.sun = new Sun_default();
      scene2.render();
      viewSun(scene2.camera, scene2.context.uniformState);
      scene2.frameState.passes.render = false;
      const command = scene2.sun.update(scene2.frameState, scene2.view.passState);
      expect(command).not.toBeDefined();
    });
    it("can set glow factor", function() {
      const sun = scene2.sun = new Sun_default();
      sun.glowFactor = 0;
      expect(sun.glowFactor).toEqual(0);
      sun.glowFactor = 2;
      expect(sun.glowFactor).toEqual(2);
    });
    it("draws without lens flare", function() {
      expect(scene2).toRender(backgroundColor);
      scene2.sun = new Sun_default();
      scene2.sun.glowFactor = 0;
      scene2.renderForSpecs();
      viewSun(scene2.camera, scene2.context.uniformState);
      expect(scene2).notToRender(backgroundColor);
    });
    it("isDestroyed", function() {
      const sun = new Sun_default();
      expect(sun.isDestroyed()).toEqual(false);
      sun.destroy();
      expect(sun.isDestroyed()).toEqual(true);
    });
  },
  "WebGL"
);

