    function markRendered(tile) {
      quadtree._lastSelectionFrameNumber = frameState2.frameNumber;
      tile._lastSelectionResultFrame = frameState2.frameNumber;
      tile._lastSelectionResult = TileSelectionResult_default.RENDERED;
      let parent = tile.parent;
      while (parent) {
        if (parent._lastSelectionResultFrame !== frameState2.frameNumber) {
          parent._lastSelectionResultFrame = frameState2.frameNumber;
          parent._lastSelectionResult = TileSelectionResult_default.REFINED;
        }
        parent = parent.parent;
      }
    }
