// packages/engine/Specs/Scene/Vector3DTilePolylinesSpec.js
describe(
  "Scene/Vector3DTilePolylines",
  function() {
    let scene2;
    let rectangle;
    let polylines;
    const ellipsoid = Ellipsoid_default.WGS84;
    beforeAll(function() {
      scene2 = createScene_default();
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    const mockTileset = {
      _statistics: {
        texturesByteLength: 0
      },
      tileset: {
        _statistics: {
          batchTableByteLength: 0
        },
        colorBlendMode: ColorBlendMode_default.HIGHLIGHT
      },
      getFeature: function(id) {
        return { batchId: id };
      }
    };
    beforeEach(function() {
      rectangle = Rectangle_default.fromDegrees(-40, -40, 40, 40);
    });
    afterEach(function() {
      scene2.primitives.removeAll();
      polylines = polylines && !polylines.isDestroyed() && polylines.destroy();
    });
    function loadPolylines(polylines2) {
      return pollToPromise_default(function() {
        polylines2.update(scene2.frameState);
        scene2.frameState.commandList.length = 0;
        return polylines2.ready;
      });
    }
    function zigZag(value) {
      return (value << 1 ^ value >> 15) & 65535;
    }
    const maxShort3 = 32767;
    function encodePositions(rectangle2, minimumHeight, maximumHeight, positions) {
      const length3 = positions.length;
      const buffer3 = new Uint16Array(length3 * 3);
      let lastU = 0;
      let lastV = 0;
      let lastH = 0;
      for (let i = 0; i < length3; ++i) {
        const position = positions[i];
        let u3 = (position.longitude - rectangle2.west) / rectangle2.width;
        let v3 = (position.latitude - rectangle2.south) / rectangle2.height;
        let h = (position.height - minimumHeight) / (maximumHeight - minimumHeight);
        u3 = Math_default.clamp(u3, 0, 1);
        v3 = Math_default.clamp(v3, 0, 1);
        h = Math_default.clamp(h, 0, 1);
        u3 = Math.floor(u3 * maxShort3);
        v3 = Math.floor(v3 * maxShort3);
        h = Math.floor(h * maxShort3);
        buffer3[i] = zigZag(u3 - lastU);
        buffer3[i + length3] = zigZag(v3 - lastV);
        buffer3[i + length3 * 2] = zigZag(h - lastH);
        lastU = u3;
        lastV = v3;
        lastH = h;
      }
      return buffer3;
    }
    it("renders a polyline", function() {
      const minHeight = 0;
      const maxHeight = 5;
      const cartoPositions = [
        Cartographic_default.fromDegrees(0, 0, 1),
        Cartographic_default.fromDegrees(1, 0, 2)
      ];
      const positions = encodePositions(
        rectangle,
        minHeight,
        maxHeight,
        cartoPositions
      );
      const batchTable = new Cesium3DTileBatchTable_default(mockTileset, 1);
      batchTable.update(mockTileset, scene2.frameState);
      const center = ellipsoid.cartographicToCartesian(
        Rectangle_default.center(rectangle)
      );
      polylines = scene2.primitives.add(
        new Vector3DTilePolylines_default({
          positions,
          widths: new Uint16Array([10]),
          counts: new Uint32Array([2]),
          batchIds: new Uint16Array([0]),
          rectangle,
          minimumHeight: minHeight,
          maximumHeight: maxHeight,
          center,
          boundingVolume: new BoundingSphere_default(center, 1e6),
          batchTable,
          keepDecodedPositions: false
        })
      );
      return loadPolylines(polylines).then(function() {
        scene2.camera.lookAt(
          Cartesian3_default.fromDegrees(0.5, 0, 1.5),
          new Cartesian3_default(0, 0, 1)
        );
        expect(scene2).toRender([255, 255, 255, 255]);
      });
    });
    it("renders multiple polylines", function() {
      const minHeight = 0;
      const maxHeight = 100;
      const cartoPositions = [
        Cartographic_default.fromDegrees(1, 0, 1),
        Cartographic_default.fromDegrees(2, 0, 2),
        Cartographic_default.fromDegrees(-6, 0, 12),
        Cartographic_default.fromDegrees(-5, 0, 15),
        Cartographic_default.fromDegrees(0, 10, 0),
        Cartographic_default.fromDegrees(0, 5, 5),
        Cartographic_default.fromDegrees(0, 0, 10),
        Cartographic_default.fromDegrees(0, -5, 15)
      ];
      const positions = encodePositions(
        rectangle,
        minHeight,
        maxHeight,
        cartoPositions
      );
      const batchTable = new Cesium3DTileBatchTable_default(mockTileset, 1);
      batchTable.update(mockTileset, scene2.frameState);
      const center = ellipsoid.cartographicToCartesian(
        Rectangle_default.center(rectangle)
      );
      polylines = scene2.primitives.add(
        new Vector3DTilePolylines_default({
          positions,
          widths: new Uint16Array([10, 10, 10]),
          counts: new Uint32Array([2, 2, 4]),
          batchIds: new Uint16Array([0, 1, 2]),
          rectangle,
          minimumHeight: minHeight,
          maximumHeight: maxHeight,
          center,
          boundingVolume: new BoundingSphere_default(center, 1e6),
          batchTable,
          keepDecodedPositions: false
        })
      );
      return loadPolylines(polylines).then(function() {
        for (let i = 0; i < cartoPositions.length; i += 2) {
          const p1 = cartoPositions[i];
          const p2 = cartoPositions[i + 1];
          const longitude = Math_default.lerp(p1.longitude, p2.longitude, 0.5);
          const latitude = Math_default.lerp(p1.latitude, p2.latitude, 0.5);
          const height = Math_default.lerp(p1.height, p2.height, 0.5);
          const target = Cartesian3_default.fromRadians(longitude, latitude, height);
          scene2.camera.lookAt(target, new Cartesian3_default(0, 0, 1));
          expect(scene2).toRender([255, 255, 255, 255]);
        }
      });
    });
    it("picks a polyline", function() {
      const minHeight = 0;
      const maxHeight = 5;
      const cartoPositions = [
        Cartographic_default.fromDegrees(0, 0, 1),
        Cartographic_default.fromDegrees(1, 0, 2)
      ];
      const positions = encodePositions(
        rectangle,
        minHeight,
        maxHeight,
        cartoPositions
      );
      const batchTable = new Cesium3DTileBatchTable_default(mockTileset, 1);
      const center = ellipsoid.cartographicToCartesian(
        Rectangle_default.center(rectangle)
      );
      polylines = scene2.primitives.add(
        new Vector3DTilePolylines_default({
          positions,
          widths: new Uint16Array([10]),
          counts: new Uint32Array([2]),
          batchIds: new Uint16Array([0]),
          rectangle,
          minimumHeight: minHeight,
          maximumHeight: maxHeight,
          center,
          boundingVolume: new BoundingSphere_default(center, 1e6),
          batchTable,
          keepDecodedPositions: false
        })
      );
      return loadPolylines(polylines).then(function() {
        scene2.camera.lookAt(
          Cartesian3_default.fromDegrees(0.5, 0, 1.5),
          new Cartesian3_default(0, 0, 1)
        );
        const features = [];
        polylines.createFeatures(mockTileset, features);
        const getFeature = mockTileset.getFeature;
        mockTileset.getFeature = function(index) {
          return features[index];
        };
        scene2.frameState.passes.pick = true;
        batchTable.update(mockTileset, scene2.frameState);
        expect(scene2).toPickAndCall(function(result) {
          expect(result).toBe(features[0]);
        });
        mockTileset.getFeature = getFeature;
      });
    });
    it("isDestroyed", function() {
      polylines = new Vector3DTilePolylines_default({});
      expect(polylines.isDestroyed()).toEqual(false);
      polylines.destroy();
      expect(polylines.isDestroyed()).toEqual(true);
    });
  },
  "WebGL"
);

