    content._featuresByTableId = /* @__PURE__ */ new Map([
      [
        100,
        /* @__PURE__ */ new Map([
          [123, mockFeature1],
          [456, mockFeature2]
        ])
      ],
      [101, /* @__PURE__ */ new Map()],
      [void 0, /* @__PURE__ */ new Map([[789, mockFeature3]])]
    ]);
    expect(content.getFeature(123, 100)).toBe(mockFeature1);
    expect(content.getFeature(456, 100)).toBe(mockFeature2);
    expect(content.getFeature(789, void 0)).toBe(mockFeature3);
