// packages/engine/Specs/Scene/VoxelTraversalSpec.js
var towardPrimitive = Cartesian3_default.fromElements(1, 1, 1);
function turnCameraAround(scene2) {
  scene2.camera.direction = Cartesian3_default.negate(towardPrimitive, new Cartesian3_default());
  scene2.renderForSpecs();
}
describe(
  "Scene/VoxelTraversal",
  function() {
    const keyframeCount = 3;
    const textureMemoryByteLength = 256;
    let scene2;
    let provider;
    let camera;
    let primitive;
    let traversal4;
    beforeEach(async function() {
      scene2 = createScene_default();
      provider = await Cesium3DTilesVoxelProvider_default.fromUrl(
        "./Data/Cesium3DTiles/Voxel/VoxelEllipsoid3DTiles/tileset.json"
      );
      camera = scene2.camera;
      camera.position = Cartesian3_default.fromElements(-6378e3, -6378e3, -6378e3);
      camera.direction = Cartesian3_default.fromElements(1, 1, 1);
      camera.frustum.fov = Math_default.PI_OVER_TWO;
      primitive = new VoxelPrimitive_default({
        provider
      });
      scene2.primitives.add(primitive);
      scene2.renderForSpecs();
      traversal4 = new VoxelTraversal_default(
        primitive,
        scene2.context,
        keyframeCount,
        textureMemoryByteLength
      );
    });
    afterEach(function() {
      scene2.destroyForSpecs();
    });
    it("constructs with arguments", function() {
      expect(traversal4._primitive).toBe(primitive);
      expect(traversal4.megatextures.length).toBe(1);
      const megatexture = traversal4.megatextures[0];
      expect(megatexture.datatype).toBe(MetadataType_default.FLOAT);
    });
    it("recomputes bounding volume when shape moves", function() {
      const rootNode = traversal4.rootNode;
      const oldOrientedBoundingBox = rootNode.orientedBoundingBox.clone();
      const shape = traversal4._primitive._shape;
      const translation3 = Cartesian3_default.fromElements(1, 1, 1);
      shape.translation = translation3;
      const modelMatrix = Matrix4_default.fromTranslation(translation3);
      shape.update(
        modelMatrix,
        VoxelEllipsoidShape_default.DefaultMinBounds,
        VoxelEllipsoidShape_default.DefaultMaxBounds
      );
      const keyFrameLocation = 0;
      const recomputeBoundingVolumes = true;
      const pauseUpdate = false;
      traversal4.update(
        scene2.frameState,
        keyFrameLocation,
        recomputeBoundingVolumes,
        pauseUpdate
      );
      const newOrientedBoundingBox = rootNode.orientedBoundingBox.clone();
      expect(
        OrientedBoundingBox_default.equals(
          oldOrientedBoundingBox,
          newOrientedBoundingBox
        )
      ).toBe(false);
      expect(newOrientedBoundingBox.center.equals(translation3)).toBe(true);
    });
    it("computes screen space error for root tile", function() {
      const { context, pixelRatio } = scene2.frameState;
      const screenHeight = context.drawingBufferHeight / pixelRatio;
      const screenSpaceErrorMultiplier = screenHeight / camera.frustum.sseDenominator;
      const rootNode = traversal4.rootNode;
      rootNode.computeScreenSpaceError(
        camera.positionWC,
        screenSpaceErrorMultiplier
      );
      let distanceToCamera = Math.sqrt(
        rootNode.orientedBoundingBox.distanceSquaredTo(camera.positionWC)
      );
      distanceToCamera = Math.max(distanceToCamera, Math_default.EPSILON7);
      const error = screenSpaceErrorMultiplier * (rootNode.approximateVoxelSize / distanceToCamera);
      expect(rootNode.screenSpaceError).toBe(error);
    });
    it("computes visibility for root tile", function() {
      const rootNode = traversal4.rootNode;
      const visibilityPlaneMask = CullingVolume_default.MASK_INDETERMINATE;
      const visibilityWhenLookingAtRoot = rootNode.visibility(
        scene2.frameState,
        visibilityPlaneMask
      );
      expect(visibilityWhenLookingAtRoot).toBe(CullingVolume_default.MASK_INSIDE);
      turnCameraAround(scene2);
      const visibilityWhenLookingAway = rootNode.visibility(
        scene2.frameState,
        visibilityPlaneMask
      );
      expect(visibilityWhenLookingAway).toBe(CullingVolume_default.MASK_OUTSIDE);
    });
    it("destroys", function() {
      expect(traversal4.isDestroyed()).toBe(false);
      traversal4.destroy();
      expect(traversal4.isDestroyed()).toBe(true);
    });
    it("shows texture memory allocation statistic", function() {
      expect(traversal4.textureMemoryByteLength).toBe(32);
      traversal4.destroy();
      expect(traversal4.textureMemoryByteLength).toBe(0);
    });
    it("loads tiles into megatexture", async function() {
      const keyFrameLocation = 0;
      const recomputeBoundingVolumes = true;
      const pauseUpdate = false;
      await pollToPromise_default(function() {
        traversal4.update(
          scene2.frameState,
          keyFrameLocation,
          recomputeBoundingVolumes,
          pauseUpdate
        );
        scene2.renderForSpecs();
        return traversal4.megatextures[0].occupiedCount > 0 && traversal4._primitive.statistics.texturesByteLength > 0;
      });
      const megatexture = traversal4.megatextures[0];
      expect(megatexture.occupiedCount).toBe(1);
      expect(traversal4.textureMemoryByteLength).toEqual(32);
    });
    it("tile failed event is raised", async function() {
      traversal4._calculateStatistics = true;
      const keyFrameLocation = 0;
      const recomputeBoundingVolumes = true;
      const pauseUpdate = false;
      const spyFailed = jasmine.createSpy("listener");
      traversal4._primitive.tileFailed.addEventListener(spyFailed);
      spyOn(traversal4._primitive._provider, "requestData").and.callFake(() => {
        return Promise.reject();
      });
      let counter = 0;
      const target = 3;
      await pollToPromise_default(function() {
        traversal4.update(
          scene2.frameState,
          keyFrameLocation,
          recomputeBoundingVolumes,
          pauseUpdate
        );
        counter++;
        return counter === target;
      });
      expect(spyFailed.calls.count()).toBeGreaterThan(1);
      expect(
        traversal4._primitive.statistics.numberOfTilesWithContentReady
      ).toEqual(0);
      expect(traversal4._primitive.statistics.visited).toEqual(3);
    });
    it("finds keyframe node with expected metadata values", async function() {
      const keyFrameLocation = 0;
      const recomputeBoundingVolumes = true;
      const pauseUpdate = false;
      await pollToPromise_default(function() {
        traversal4.update(
          scene2.frameState,
          keyFrameLocation,
          recomputeBoundingVolumes,
          pauseUpdate
        );
        scene2.renderForSpecs();
        return traversal4.megatextures[0].occupiedCount > 0;
      });
      const megatextureIndex = 0;
      const keyframeNode = traversal4.findKeyframeNode(megatextureIndex);
      expect(keyframeNode).toBeDefined();
      expect(keyframeNode.state).toBe(KeyframeNode_default.LoadState.LOADED);
      const expectedMetadata = new Float32Array([0, 0, 0, 0, 1, 1, 1, 1]);
      expect(keyframeNode.content.metadata[0]).toEqual(expectedMetadata);
    });
  },
  "WebGL"
);

