  it("raises error event when image cannot be loaded", function() {
    const provider = new WebMapServiceImageryProvider_default({
      url: "made/up/wms/server",
      layers: "someLayer"
    });
    const layer = new ImageryLayer_default(provider);
    let tries = 0;
    provider.errorEvent.addEventListener(function(error) {
      expect(error.timesRetried).toEqual(tries);
      ++tries;
      if (tries < 3) {
        error.retry = true;
      }
      setTimeout(function() {
        RequestScheduler_default.update();
      }, 1);
    });
    Resource_default._Implementations.createImage = function(request, crossOrigin, deferred) {
      if (tries === 2) {
        Resource_default._DefaultImplementations.createImage(
          new Request_default({ url: "Data/Images/Red16x16.png" }),
          crossOrigin,
          deferred
        );
      } else {
        setTimeout(function() {
          deferred.reject();
        }, 1);
      }
    };
    const imagery = new Imagery_default(layer, 0, 0, 0);
    imagery.addReference();
    layer._requestImagery(imagery);
    RequestScheduler_default.update();
    return pollToPromise_default(function() {
      return imagery.state === ImageryState_default.RECEIVED;
    }).then(function() {
      expect(imagery.image).toBeImageOrImageBitmap();
      expect(tries).toEqual(2);
      imagery.releaseReference();
    });
  });
