// packages/engine/Specs/Scene/Model/ClassificationPipelineStageSpec.js
describe("Scene/Model/ClassificationPipelineStage", function() {
  const mockFrameState = {};
  function generateFeatureIds(batchLengths) {
    const featureIds = [];
    const length3 = batchLengths.length;
    for (let id = 0; id < length3; id++) {
      const batchLength = batchLengths[id];
      const batch = new Array(batchLength);
      batch.fill(id);
      addAllToArray_default(featureIds, batch);
    }
    return featureIds;
  }
  function mockPrimitive(featureIds, indices) {
    const positionAttribute = {
      semantic: VertexAttributeSemantic_default.POSITION,
      count: featureIds.length
    };
    const featureIdAttribute = {
      semantic: VertexAttributeSemantic_default.FEATURE_ID,
      setIndex: 0,
      typedArray: featureIds,
      count: featureIds.length
    };
    const primitive = {
      primitiveType: PrimitiveType_default.TRIANGLES,
      attributes: [positionAttribute, featureIdAttribute],
      indices
    };
    return primitive;
  }
  function mockRenderResources(primitive) {
    return {
      shaderBuilder: new ShaderBuilder_default(),
      uniformMap: {},
      model: {},
      primitive,
      runtimePrimitive: {
        batchLengths: void 0,
        batchOffsets: void 0
      }
    };
  }
  it("throws for primitive with no position attribute", function() {
    const inputBatchLengths = [6];
    const featureIds = generateFeatureIds(inputBatchLengths);
    const primitive = mockPrimitive(featureIds);
    const positionAttribute = primitive.attributes[0];
    positionAttribute.semantic = VertexAttributeSemantic_default.NORMAL;
    const renderResources = mockRenderResources(primitive);
    expect(function() {
      ClassificationPipelineStage_default.process(
        renderResources,
        primitive,
        mockFrameState
      );
    }).toThrowError(RuntimeError_default);
  });
  it("adds classification define to the shader", function() {
    const inputBatchLengths = [6];
    const featureIds = generateFeatureIds(inputBatchLengths);
    const primitive = mockPrimitive(featureIds);
    const renderResources = mockRenderResources(primitive);
    ClassificationPipelineStage_default.process(
      renderResources,
      primitive,
      mockFrameState
    );
    const shaderBuilder = renderResources.shaderBuilder;
    ShaderBuilderTester_default.expectHasVertexDefines(shaderBuilder, [
      "HAS_CLASSIFICATION"
    ]);
    ShaderBuilderTester_default.expectHasFragmentDefines(shaderBuilder, [
      "HAS_CLASSIFICATION"
    ]);
  });
  it("computes single batch for primitive without feature IDs", function() {
    const inputBatchLengths = [6];
    const featureIds = generateFeatureIds(inputBatchLengths);
    const primitive = mockPrimitive(featureIds);
    primitive.attributes.length = 1;
    const renderResources = mockRenderResources(primitive);
    ClassificationPipelineStage_default.process(
      renderResources,
      primitive,
      mockFrameState
    );
    const runtimePrimitive = renderResources.runtimePrimitive;
    const batchLengths = runtimePrimitive.batchLengths;
    const batchOffsets = runtimePrimitive.batchOffsets;
    expect(batchLengths).toEqual(inputBatchLengths);
    expect(batchOffsets).toEqual([0]);
  });
  it("computes single batch for primitive with feature IDs", function() {
    const inputBatchLengths = [6];
    const featureIds = generateFeatureIds(inputBatchLengths);
    const primitive = mockPrimitive(featureIds);
    const renderResources = mockRenderResources(primitive);
    ClassificationPipelineStage_default.process(
      renderResources,
      primitive,
      mockFrameState
    );
    const runtimePrimitive = renderResources.runtimePrimitive;
    const batchLengths = runtimePrimitive.batchLengths;
    const batchOffsets = runtimePrimitive.batchOffsets;
    expect(batchLengths).toEqual(inputBatchLengths);
    expect(batchOffsets).toEqual([0]);
  });
  it("computes multiple batches for primitive with feature IDs", function() {
    const inputBatchLengths = [6, 3, 9, 12];
    const featureIds = generateFeatureIds(inputBatchLengths);
    const primitive = mockPrimitive(featureIds);
    const renderResources = mockRenderResources(primitive);
    ClassificationPipelineStage_default.process(
      renderResources,
      primitive,
      mockFrameState
    );
    const runtimePrimitive = renderResources.runtimePrimitive;
    const batchLengths = runtimePrimitive.batchLengths;
    const batchOffsets = runtimePrimitive.batchOffsets;
    expect(batchLengths).toEqual(inputBatchLengths);
    expect(batchOffsets).toEqual([0, 6, 9, 18]);
  });
  it("computes multiple batches for primitive with feature IDs and indices", function() {
    const featureIds = [2, 1, 0, 0, 1, 2, 2, 1, 0, 0, 2];
    const indices = {
      // prettier-ignore
      typedArray: [
        2,
        3,
        8,
        2,
        8,
        9,
        // Two triangles with feature ID 0
        1,
        4,
        7,
        // One triangle with feature ID 1
        0,
        5,
        6,
        0,
        6,
        10
        // Two triangles with feature ID 2
      ],
      count: 15
    };
    const primitive = mockPrimitive(featureIds, indices);
    const renderResources = mockRenderResources(primitive);
    ClassificationPipelineStage_default.process(
      renderResources,
      primitive,
      mockFrameState
    );
    const runtimePrimitive = renderResources.runtimePrimitive;
    const batchLengths = runtimePrimitive.batchLengths;
    const batchOffsets = runtimePrimitive.batchOffsets;
    expect(batchLengths).toEqual([6, 3, 6]);
    expect(batchOffsets).toEqual([0, 6, 9]);
  });
  it("doesn't recompute batches for primitive if they are already defined", function() {
    const inputBatchLengths = [6];
    const featureIds = generateFeatureIds(inputBatchLengths);
    const primitive = mockPrimitive(featureIds);
    const renderResources = mockRenderResources(primitive);
    const runtimePrimitive = renderResources.runtimePrimitive;
    runtimePrimitive.batchLengths = [];
    runtimePrimitive.batchOffsets = [];
    ClassificationPipelineStage_default.process(
      renderResources,
      primitive,
      mockFrameState
    );
    const batchLengths = runtimePrimitive.batchLengths;
    const batchOffsets = runtimePrimitive.batchOffsets;
    expect(batchLengths).toEqual([]);
    expect(batchOffsets).toEqual([]);
  });
});

// packages/engine/Specs/Scene/Model/CPUStylingPipelineStageSpec.js
describe("Scene/Model/CPUStylingPipelineStage", function() {
  const defaultRenderResources = {
    alphaOptions: new ModelAlphaOptions_default(),
    model: {
      colorBlendMode: ColorBlendMode_default.HIGHLIGHT,
      colorBlendAmount: 0.5,
      featureTableId: 0,
      featureTables: [
        {
          featuresLength: 10,
          batchTexture: {
            translucentFeaturesLength: 0
          }
        }
      ]
    },
    shaderBuilder: new ShaderBuilder_default(),
    uniformMap: {}
  };
  it("adds shader functions", function() {
    const renderResources = clone_default(defaultRenderResources, true);
    const shaderBuilder = renderResources.shaderBuilder;
    CPUStylingPipelineStage_default.process(renderResources);
    ShaderBuilderTester_default.expectFragmentLinesEqual(shaderBuilder, [
      CPUStylingStageFS_default
    ]);
    ShaderBuilderTester_default.expectVertexLinesEqual(shaderBuilder, [
      CPUStylingStageVS_default
    ]);
  });
  it("adds color blend uniform", function() {
    const renderResources = clone_default(defaultRenderResources, true);
    renderResources.model.colorBlendAmount = 0.75;
    renderResources.model.colorBlendMode = ColorBlendMode_default.MIX;
    const colorBlend = ColorBlendMode_default.getColorBlend(
      renderResources.model.colorBlendMode,
      renderResources.model.colorBlendAmount
    );
    CPUStylingPipelineStage_default.process(renderResources);
    const shaderBuilder = renderResources.shaderBuilder;
    const uniformMap2 = renderResources.uniformMap;
    ShaderBuilderTester_default.expectHasFragmentUniforms(shaderBuilder, [
      "uniform bool model_commandTranslucent;",
      "uniform float model_colorBlend;"
    ]);
    expect(uniformMap2.model_colorBlend()).toEqual(colorBlend);
    expect(uniformMap2.model_commandTranslucent()).toBe(false);
  });
  it("doesn't add color blend uniform if model color is present", function() {
    const renderResources = clone_default(defaultRenderResources, true);
    renderResources.model.color = Color_default.RED;
    renderResources.model.colorBlendAmount = 0.75;
    renderResources.model.colorBlendMode = ColorBlendMode_default.MIX;
    CPUStylingPipelineStage_default.process(renderResources);
    const shaderBuilder = renderResources.shaderBuilder;
    const uniformMap2 = renderResources.uniformMap;
    ShaderBuilderTester_default.expectHasFragmentUniforms(shaderBuilder, [
      "uniform bool model_commandTranslucent;"
    ]);
    expect(uniformMap2.model_colorBlend).toBeUndefined();
    expect(uniformMap2.model_commandTranslucent()).toBe(false);
  });
  it("adds command translucent uniform", function() {
    const renderResources = clone_default(defaultRenderResources, true);
    renderResources.alphaOptions.pass = Pass_default.TRANSLUCENT;
    CPUStylingPipelineStage_default.process(renderResources);
    const shaderBuilder = renderResources.shaderBuilder;
    const uniformMap2 = renderResources.uniformMap;
    ShaderBuilderTester_default.expectHasFragmentUniforms(shaderBuilder, [
      "uniform bool model_commandTranslucent;",
      "uniform float model_colorBlend;"
    ]);
    expect(uniformMap2.model_commandTranslucent()).toEqual(true);
  });
  it("model_commandTranslucent accounts for changes from later pipeline stages", function() {
    const renderResources = clone_default(defaultRenderResources, true);
    renderResources.model.color = Color_default.RED;
    renderResources.model.colorBlendAmount = 0.75;
    renderResources.model.colorBlendMode = ColorBlendMode_default.MIX;
    CPUStylingPipelineStage_default.process(renderResources);
    const uniformMap2 = renderResources.uniformMap;
    expect(uniformMap2.model_commandTranslucent()).toBe(false);
    renderResources.alphaOptions.pass = Pass_default.TRANSLUCENT;
    expect(uniformMap2.model_commandTranslucent()).toBe(true);
  });
});

// packages/engine/Specs/Scene/Model/createVectorTileBuffersFromModelComponentsSpec.js
function createPositionAttribute(positions) {
  const attribute = new ModelComponents_default.Attribute();
  attribute.semantic = VertexAttributeSemantic_default.POSITION;
  attribute.count = positions.length / 3;
  attribute.typedArray = positions;
  return attribute;
}
function createFeatureIdAttribute(featureIds) {
  const attribute = new ModelComponents_default.Attribute();
  attribute.semantic = VertexAttributeSemantic_default.FEATURE_ID;
  attribute.setIndex = 0;
  attribute.count = featureIds.length;
  attribute.typedArray = featureIds;
  return attribute;
}
function createFeatureIdSet(featureCount) {
  const featureIdSet = new ModelComponents_default.FeatureIdAttribute();
  featureIdSet.featureCount = featureCount;
  featureIdSet.setIndex = 0;
  featureIdSet.positionalLabel = "featureId_0";
  return featureIdSet;
}
function createIndices(typedArray) {
  const indices = new ModelComponents_default.Indices();
  indices.count = typedArray.length;
  indices.typedArray = typedArray;
  if (typedArray instanceof Uint8Array) {
    indices.indexDatatype = IndexDatatype_default.UNSIGNED_BYTE;
  } else if (typedArray instanceof Uint16Array) {
    indices.indexDatatype = IndexDatatype_default.UNSIGNED_SHORT;
  } else {
    indices.indexDatatype = IndexDatatype_default.UNSIGNED_INT;
  }
  return indices;
}
function createPrimitive3(options) {
  const primitive = new ModelComponents_default.Primitive();
  primitive.primitiveType = options.primitiveType;
  primitive.vector = options.vector;
  primitive.polygon = options.polygon;
  primitive.attributes.push(createPositionAttribute(options.positions));
  if (options.featureIds) {
    primitive.attributes.push(createFeatureIdAttribute(options.featureIds));
    primitive.featureIds.push(
      createFeatureIdSet(Math.max(...options.featureIds) + 1)
    );
  }
  if (options.indices) {
    primitive.indices = createIndices(options.indices);
  }
  return primitive;
}
function createComponents(rootNode) {
  const components = new ModelComponents_default.Components();
  components.scene = new ModelComponents_default.Scene();
  components.scene.nodes.push(rootNode);
  return components;
}
