      it("gets memory usage", function() {
        const promises = [
          Cesium3DTilesTester_default.loadTileset(scene2, pointCloudNoColorUrl),
          Cesium3DTilesTester_default.loadTileset(scene2, pointCloudRGBUrl),
          Cesium3DTilesTester_default.loadTileset(scene2, pointCloudNormalsUrl),
          Cesium3DTilesTester_default.loadTileset(
            scene2,
            pointCloudQuantizedOctEncodedUrl
          )
        ];
        const expectedGeometryMemory = [
          1e3 * 12,
          // 3 floats (xyz)
          1e3 * 15,
          // 3 floats (xyz), 3 bytes (rgb)
          1e3 * 27,
          // 3 floats (xyz), 3 bytes (rgb), 3 floats (normal)
          1e3 * 11
          // 3 shorts (quantized xyz), 3 bytes (rgb), 2 bytes (oct-encoded normal)
        ];
        return Promise.all(promises).then(function(tilesets) {
          const length3 = tilesets.length;
          for (let i = 0; i < length3; ++i) {
            const content = tilesets[i].root.content;
            expect(content.geometryByteLength).toEqual(
              expectedGeometryMemory[i]
            );
            expect(content.texturesByteLength).toEqual(0);
          }
        });
      });
