// packages/engine/Specs/Scene/Model/ModelFeatureSpec.js
describe("Scene/Model/ModelFeature", function() {
  const mockModel = {
    type: ModelType_default.GLTF
  };
  let feature2;
  let featureTable;
  beforeEach(function() {
    const properties = {
      height: {
        semantic: "HEIGHT_SEMANTIC",
        type: "SCALAR",
        componentType: "FLOAT32"
      },
      name: {
        type: "STRING"
      },
      HEIGHT_SEMANTIC: {
        type: "SCALAR",
        componentType: "FLOAT32"
      }
    };
    const propertyValues = {
      height: [1],
      name: ["A"],
      HEIGHT_SEMANTIC: [3]
    };
    const mockPropertyTable = MetadataTester_default.createPropertyTable({
      properties,
      propertyValues
    });
    featureTable = new ModelFeatureTable_default({
      propertyTable: mockPropertyTable,
      model: mockModel
    });
    feature2 = featureTable.getFeature(0);
  });
  it("constructs", function() {
    const mockFeatureTable = {};
    const feature3 = new ModelFeature_default({
      model: mockModel,
      featureTable: mockFeatureTable,
      featureId: 3
    });
    expect(feature3.primitive).toBe(mockModel);
    expect(feature3.featureTable).toBe(mockFeatureTable);
    expect(feature3.featureId).toBe(3);
  });
  it("gets and sets show", function() {
    expect(feature2.show).toBe(true);
    feature2.show = false;
    expect(feature2.show).toBe(false);
  });
  it("gets and sets color", function() {
    expect(feature2.color).toEqual(new Color_default());
    feature2.color = Color_default.RED;
    expect(feature2.color).toEqual(Color_default.RED);
  });
  it("gets primitive", function() {
    expect(feature2.primitive).toBe(mockModel);
  });
  it("gets featureTable", function() {
    expect(feature2.featureTable).toBe(featureTable);
  });
  it("gets featureId", function() {
    expect(feature2.featureId).toBe(0);
  });
  it("hasProperty works", function() {
    expect(feature2.hasProperty("height")).toBe(true);
    expect(feature2.hasProperty("width")).toBe(false);
  });
  it("getProperty works", function() {
    expect(feature2.getProperty("height")).toBe(1);
    expect(feature2.getProperty("name")).toBe("A");
    expect(feature2.getProperty("HEIGHT_SEMANTIC")).toBe(3);
  });
  it("getPropertyInherited works", function() {
    expect(feature2.getPropertyInherited("height")).toEqual(1);
    expect(feature2.getPropertyInherited("_height")).toBeUndefined();
  });
  it("getPropertyIds works", function() {
    const results = [];
    expect(feature2.getPropertyIds(results)).toEqual([
      "height",
      "name",
      "HEIGHT_SEMANTIC"
    ]);
  });
  it("setProperty works", function() {
    expect(feature2.getProperty("height")).toEqual(1);
    feature2.setProperty("height", 3);
    expect(feature2.getProperty("height")).toEqual(3);
  });
});

// packages/engine/Specs/Scene/Model/ModelFeatureTableSpec.js
describe("Scene/Model/ModelFeatureTable", function() {
  let mockPropertyTable;
  let properties;
  let propertyValues;
  beforeAll(function() {
    properties = {
      height: {
        semantic: "HEIGHT_SEMANTIC",
        type: "SCALAR",
        componentType: "FLOAT32"
      },
      name: {
        type: "STRING"
      },
      HEIGHT_SEMANTIC: {
        type: "SCALAR",
        componentType: "FLOAT32"
      }
    };
    propertyValues = {
      height: [1, 2],
      name: ["A", "B"],
      HEIGHT_SEMANTIC: [3, 4]
    };
    mockPropertyTable = MetadataTester_default.createPropertyTable({
      properties,
      propertyValues
    });
  });
  it("creates ModelFeatures when model does not have content", function() {
    const table = new ModelFeatureTable_default({
      propertyTable: mockPropertyTable,
      model: {
        type: ModelType_default.GLTF
      }
    });
    expect(table._featuresLength).toEqual(mockPropertyTable.count);
    const modelFeatures = table._features;
    for (let i = 0; i < modelFeatures.length; i++) {
      const feature2 = table.getFeature(i);
      expect(feature2).toBeInstanceOf(ModelFeature_default);
    }
  });
  it("creates ModelFeatures when model has content", function() {
    const table = new ModelFeatureTable_default({
      propertyTable: mockPropertyTable,
      model: {
        content: {
          tileset: {}
        },
        type: ModelType_default.TILE_GLTF
      }
    });
    expect(table._featuresLength).toEqual(mockPropertyTable.count);
    const modelFeatures = table._features;
    for (let i = 0; i < modelFeatures.length; i++) {
      const feature2 = table.getFeature(i);
      expect(feature2).toBeInstanceOf(Cesium3DTileFeature_default);
    }
  });
  it("hasProperty works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    const modelFeatures = table._features;
    for (let i = 0; i < modelFeatures.length; i++) {
      const feature2 = modelFeatures[i];
      expect(feature2.hasProperty("height")).toEqual(true);
      expect(feature2.hasProperty("width")).toEqual(false);
    }
  });
  it("hasPropertyBySemantic works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    const modelFeatures = table._features;
    for (let i = 0; i < modelFeatures.length; i++) {
      expect(table.hasPropertyBySemantic(i, "HEIGHT_SEMANTIC")).toEqual(true);
      expect(table.hasPropertyBySemantic(i, "WIDTH_SEMANTIC")).toEqual(false);
    }
  });
  it("getFeature works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    expect(table._featuresLength).toEqual(mockPropertyTable.count);
    const modelFeatures = table._features;
    for (let i = 0; i < modelFeatures.length; i++) {
      const feature2 = table.getFeature(i);
      expect(feature2).toEqual(modelFeatures[i]);
      expect(feature2).toBeInstanceOf(ModelFeature_default);
    }
  });
  it("getProperty works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    expect(table._featuresLength).toEqual(mockPropertyTable.count);
    const modelFeatures = table._features;
    for (const propertyName in properties) {
      if (properties.hasOwnProperty(propertyName)) {
        for (let i = 0; i < modelFeatures.length; i++) {
          const feature2 = modelFeatures[i];
          expect(feature2.getProperty(propertyName)).toEqual(
            propertyValues[propertyName][i]
          );
        }
      }
    }
  });
  it("getPropertyInherited works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    expect(table._featuresLength).toEqual(mockPropertyTable.count);
    const modelFeatures = table._features;
    let i;
    let feature2;
    for (i = 0; i < modelFeatures.length; i++) {
      feature2 = modelFeatures[i];
      expect(feature2.getPropertyInherited("height")).toEqual(
        propertyValues["height"][i]
      );
      expect(feature2.getPropertyInherited("_height")).toBeUndefined();
    }
    for (i = 0; i < modelFeatures.length; i++) {
      feature2 = modelFeatures[i];
      expect(feature2.getPropertyInherited("HEIGHT_SEMANTIC")).toEqual(
        propertyValues["height"][i]
      );
      expect(feature2.getPropertyInherited("_HEIGHT_")).toBeUndefined();
    }
  });
  it("getPropertyIds works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    const modelFeatures = table._features;
    let results;
    for (let i = 0; i < modelFeatures.length; i++) {
      results = [];
      const feature2 = modelFeatures[i];
      expect(feature2.getPropertyIds(results)).toEqual([
        "height",
        "name",
        "HEIGHT_SEMANTIC"
      ]);
    }
  });
  it("setProperty works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    const feature2 = table._features[0];
    expect(feature2.getProperty("height")).toEqual(1);
    feature2.setProperty("height", 3);
    expect(feature2.getProperty("height")).toEqual(3);
  });
  it("destroy works", function() {
    const table = new ModelFeatureTable_default({
      model: {
        type: ModelType_default.GLTF
      },
      propertyTable: mockPropertyTable
    });
    const batchTexture = table._batchTexture;
    expect(batchTexture.isDestroyed()).toEqual(false);
    expect(table.isDestroyed()).toEqual(false);
    table.destroy();
    expect(batchTexture.isDestroyed()).toEqual(true);
    expect(table.isDestroyed()).toEqual(true);
  });
});

