// packages/engine/Specs/Scene/Model/ModelMatrixUpdateStageSpec.js
describe(
  "Scene/Model/ModelMatrixUpdateStage",
  function() {
    const simpleSkin = "./Data/Models/glTF-2.0/SimpleSkin/glTF/SimpleSkin.gltf";
    function getStaticLeafNode(model) {
      return model.sceneGraph._runtimeNodes[0];
    }
    function getParentRootNode(model) {
      return model.sceneGraph._runtimeNodes[1];
    }
    function getChildLeafNode(model) {
      return model.sceneGraph._runtimeNodes[2];
    }
    function getDrawCommand(runtimeNode) {
      return runtimeNode.runtimePrimitives[0].drawCommand;
    }
    const rotation = Quaternion_default.fromAxisAngle(
      Cartesian3_default.UNIT_Y,
      Math_default.toRadians(180)
    );
    const modelMatrix = Matrix4_default.fromTranslationQuaternionRotationScale(
      new Cartesian3_default(10, 0, 0),
      rotation,
      new Cartesian3_default(1, 1, 1)
    );
    let scene2;
    beforeAll(function() {
      scene2 = createScene_default();
    });
    afterAll(function() {
      scene2.destroyForSpecs();
    });
    afterEach(function() {
      scene2.primitives.removeAll();
      ResourceCache_default.clearForSpecs();
    });
    const mockPrimitive = {
      material: {
        doubleSided: false
      },
      attributes: [
        {
          semantic: "POSITION",
          max: new Cartesian3_default(0.5, 2, 0),
          min: new Cartesian3_default(-0.5, 0, 0)
        }
      ]
    };
    function mockRenderResources(model) {
      return {
        model,
        runtimePrimitive: {
          boundingSphere: new BoundingSphere_default(),
          primitive: mockPrimitive
        }
      };
    }
    function modifyModel(model) {
      const sceneGraph = model.sceneGraph;
      sceneGraph._axisCorrectionMatrix = Matrix4_default.IDENTITY;
      const meshNode = getStaticLeafNode(model);
      const modelDrawCommand = getDrawCommand(meshNode);
      const drawCommand = modelDrawCommand.command;
      const renderResources = mockRenderResources(model);
      const rootNode = getParentRootNode(model);
      const rootDrawCommand = clone_default(drawCommand);
      rootDrawCommand.modelMatrix = Matrix4_default.clone(Matrix4_default.IDENTITY);
      rootDrawCommand.boundingVolume = new BoundingSphere_default();
      let runtimePrimitive = new ModelRuntimePrimitive_default({
        node: rootNode,
        model,
        primitive: mockPrimitive
      });
      runtimePrimitive.drawCommand = new ModelDrawCommand_default({
        command: rootDrawCommand,
        primitiveRenderResources: renderResources
      });
      spyOn(runtimePrimitive, "configurePipeline");
      rootNode.runtimePrimitives.push(runtimePrimitive);
      rootNode._transformDirty = true;
      const leafNode = getChildLeafNode(model);
      const leafDrawCommand = clone_default(drawCommand);
      leafDrawCommand.modelMatrix = Matrix4_default.clone(Matrix4_default.IDENTITY);
      leafDrawCommand.boundingVolume = new BoundingSphere_default();
      runtimePrimitive = new ModelRuntimePrimitive_default({
        node: leafNode,
        model,
        primitive: mockPrimitive
      });
      runtimePrimitive.drawCommand = new ModelDrawCommand_default({
        command: leafDrawCommand,
        primitiveRenderResources: renderResources
      });
      spyOn(runtimePrimitive, "configurePipeline");
      leafNode.runtimePrimitives.push(runtimePrimitive);
      leafNode._transformDirty = true;
    }
    function applyTransform(node, transform3) {
      const expectedOriginalTransform = Matrix4_default.clone(node.originalTransform);
      expect(node._transformDirty).toEqual(false);
      node.transform = Matrix4_default.multiplyTransformation(
        node.transform,
        transform3,
        new Matrix4_default()
      );
      expect(node._transformDirty).toEqual(true);
      expect(
        Matrix4_default.equals(node.originalTransform, expectedOriginalTransform)
      ).toBe(true);
    }
    it("updates leaf nodes using node transform setter", async function() {
      const model = await loadAndZoomToModelAsync_default(
        {
          gltf: simpleSkin
        },
        scene2
      );
      scene2.renderForSpecs();
      const sceneGraph = model.sceneGraph;
      const node = getStaticLeafNode(model);
      const primitive = node.runtimePrimitives[0];
      let drawCommand = getDrawCommand(node);
      const transform3 = Matrix4_default.fromTranslation(new Cartesian3_default(0, 5, 0));
      applyTransform(node, transform3);
      const expectedComputedTransform = Matrix4_default.multiplyTransformation(
        sceneGraph.computedModelMatrix,
        node.transform,
        new Matrix4_default()
      );
      const expectedModelMatrix = Matrix4_default.multiplyTransformation(
        drawCommand.modelMatrix,
        transform3,
        new Matrix4_default()
      );
      const expectedBoundingSphere = BoundingSphere_default.transform(
        primitive.boundingSphere,
        expectedComputedTransform,
        new BoundingSphere_default()
      );
      scene2.renderForSpecs();
      drawCommand = getDrawCommand(node);
      expect(
        Matrix4_default.equalsEpsilon(
          drawCommand.modelMatrix,
          expectedModelMatrix,
          Math_default.EPSILON15
        )
      ).toBe(true);
      expect(
        BoundingSphere_default.equals(
          drawCommand.boundingVolume,
          expectedBoundingSphere
        )
      ).toBe(true);
    });
    it("updates nodes with children using node transform setter", async function() {
      const model = await loadAndZoomToModelAsync_default(
        {
          gltf: simpleSkin
        },
        scene2
      );
      modifyModel(model);
      scene2.renderForSpecs();
      const rootNode = getParentRootNode(model);
      const staticLeafNode = getStaticLeafNode(model);
      const transformedLeafNode = getChildLeafNode(model);
      let rootDrawCommand = getDrawCommand(rootNode);
      let staticDrawCommand = getDrawCommand(staticLeafNode);
      let transformedDrawCommand = getDrawCommand(transformedLeafNode);
      const childTransformation = Matrix4_default.fromTranslation(
        new Cartesian3_default(0, 5, 0)
      );
      applyTransform(transformedLeafNode, childTransformation);
      const rootTransformation = Matrix4_default.fromTranslation(
        new Cartesian3_default(12, 5, 0)
      );
      applyTransform(rootNode, rootTransformation);
      const expectedRootModelMatrix = Matrix4_default.multiplyTransformation(
        rootTransformation,
        rootDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      const expectedStaticLeafModelMatrix = Matrix4_default.clone(
        staticDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      const finalTransform = new Matrix4_default();
      Matrix4_default.multiply(rootTransformation, childTransformation, finalTransform);
      const expectedTransformedLeafModelMatrix = Matrix4_default.multiplyTransformation(
        finalTransform,
        transformedDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      scene2.renderForSpecs();
      rootDrawCommand = getDrawCommand(rootNode);
      staticDrawCommand = getDrawCommand(staticLeafNode);
      transformedDrawCommand = getDrawCommand(transformedLeafNode);
      expect(rootDrawCommand.modelMatrix).toEqual(expectedRootModelMatrix);
      expect(staticDrawCommand.modelMatrix).toEqual(
        expectedStaticLeafModelMatrix
      );
      expect(transformedDrawCommand.modelMatrix).toEqual(
        expectedTransformedLeafModelMatrix
      );
    });
    it("updates with new model matrix", async function() {
      const model = await loadAndZoomToModelAsync_default(
        {
          gltf: simpleSkin
        },
        scene2
      );
      modifyModel(model);
      scene2.renderForSpecs();
      const rootNode = getParentRootNode(model);
      const staticLeafNode = getStaticLeafNode(model);
      const transformedLeafNode = getChildLeafNode(model);
      let rootDrawCommand = getDrawCommand(rootNode);
      let staticDrawCommand = getDrawCommand(staticLeafNode);
      let transformedDrawCommand = getDrawCommand(transformedLeafNode);
      const expectedRootModelMatrix = Matrix4_default.multiplyTransformation(
        modelMatrix,
        rootDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      const expectedStaticLeafModelMatrix = Matrix4_default.multiplyTransformation(
        modelMatrix,
        staticDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      const expectedTransformedLeafModelMatrix = Matrix4_default.multiplyTransformation(
        modelMatrix,
        transformedDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      model.modelMatrix = modelMatrix;
      scene2.renderForSpecs();
      rootDrawCommand = getDrawCommand(rootNode);
      staticDrawCommand = getDrawCommand(staticLeafNode);
      transformedDrawCommand = getDrawCommand(transformedLeafNode);
      expect(rootDrawCommand.modelMatrix).toEqual(expectedRootModelMatrix);
      expect(staticDrawCommand.modelMatrix).toEqual(
        expectedStaticLeafModelMatrix
      );
      expect(transformedDrawCommand.modelMatrix).toEqual(
        expectedTransformedLeafModelMatrix
      );
    });
    it("updates with new model matrix and model scale", async function() {
      const model = await loadAndZoomToModelAsync_default(
        {
          gltf: simpleSkin
        },
        scene2
      );
      modifyModel(model);
      scene2.renderForSpecs();
      const modelScale = 5;
      const scaledModelMatrix = Matrix4_default.multiplyByUniformScale(
        modelMatrix,
        modelScale,
        new Matrix4_default()
      );
      const rootNode = getParentRootNode(model);
      const staticLeafNode = getStaticLeafNode(model);
      const transformedLeafNode = getChildLeafNode(model);
      let rootDrawCommand = getDrawCommand(rootNode);
      let staticDrawCommand = getDrawCommand(staticLeafNode);
      let transformedDrawCommand = getDrawCommand(transformedLeafNode);
      const expectedRootModelMatrix = Matrix4_default.multiplyTransformation(
        scaledModelMatrix,
        rootDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      const expectedStaticLeafModelMatrix = Matrix4_default.multiplyTransformation(
        scaledModelMatrix,
        staticDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      const expectedTransformedLeafModelMatrix = Matrix4_default.multiplyTransformation(
        scaledModelMatrix,
        transformedDrawCommand.modelMatrix,
        new Matrix4_default()
      );
      model.modelMatrix = modelMatrix;
      model.scale = modelScale;
      scene2.renderForSpecs();
      rootDrawCommand = getDrawCommand(rootNode);
      staticDrawCommand = getDrawCommand(staticLeafNode);
      transformedDrawCommand = getDrawCommand(transformedLeafNode);
      expect(rootDrawCommand.modelMatrix).toEqual(expectedRootModelMatrix);
      expect(staticDrawCommand.modelMatrix).toEqual(
        expectedStaticLeafModelMatrix
      );
      expect(transformedDrawCommand.modelMatrix).toEqual(
        expectedTransformedLeafModelMatrix
      );
    });
    it("updates render state cull face when scale is negative", async function() {
      const model = await loadAndZoomToModelAsync_default(
        {
          gltf: simpleSkin
        },
        scene2
      );
      modifyModel(model);
      const rootNode = getParentRootNode(model);
      const childNode = getChildLeafNode(model);
      const rootPrimitive = rootNode.runtimePrimitives[0];
      const childPrimitive = childNode.runtimePrimitives[0];
      const rootDrawCommand = rootPrimitive.drawCommand;
      const childDrawCommand = childPrimitive.drawCommand;
      expect(rootDrawCommand.cullFace).toBe(CullFace_default.BACK);
      expect(childDrawCommand.cullFace).toBe(CullFace_default.BACK);
      model.modelMatrix = Matrix4_default.fromUniformScale(-1);
      scene2.renderForSpecs();
      expect(rootPrimitive.drawCommand).toBe(rootDrawCommand);
      expect(rootDrawCommand.cullFace).toBe(CullFace_default.FRONT);
      expect(childDrawCommand.cullFace).toBe(CullFace_default.FRONT);
    });
  },
  "WebGL"
);

// packages/engine/Specs/Scene/Model/ModelNodeSpec.js
describe("Scene/Model/ModelNode", function() {
  const mockNode = {
    name: "Mock Node",
    index: 0
  };
  let runtimeNode, mockModel;
  const nodeTransform = Matrix4_default.fromTranslation(new Cartesian3_default(1, 2, 3));
  beforeEach(function() {
    runtimeNode = new ModelRuntimeNode_default({
      node: mockNode,
      transform: nodeTransform,
      transformToRoot: Matrix4_default.IDENTITY,
      children: [],
      sceneGraph: {}
    });
    mockModel = {
      _userAnimationDirty: false
    };
  });
  it("throws for undefined model", function() {
    expect(function() {
      return new ModelNode_default(void 0, runtimeNode);
    }).toThrowDeveloperError();
  });
  it("throws for undefined runtimeNode", function() {
    expect(function() {
      return new ModelNode_default(mockModel, void 0);
    }).toThrowDeveloperError();
  });
  it("constructs", function() {
    const node = new ModelNode_default(mockModel, runtimeNode);
    expect(node.name).toEqual("Mock Node");
    expect(node.id).toEqual(0);
    expect(node.show).toBe(true);
    expect(node.matrix).toBe(runtimeNode.transform);
    expect(node.originalMatrix).toBe(runtimeNode.originalTransform);
  });
  it("sets show for runtime node", function() {
    const node = new ModelNode_default(mockModel, runtimeNode);
    node.show = false;
    expect(runtimeNode.show).toBe(false);
    node.show = true;
    expect(runtimeNode.show).toBe(true);
  });
  it("sets matrix for runtime node", function() {
    const node = new ModelNode_default(mockModel, runtimeNode);
    expect(node.matrix).toEqual(nodeTransform);
    expect(node.originalMatrix).toEqual(nodeTransform);
    expect(runtimeNode.userAnimated).toBe(false);
    expect(mockModel._userAnimationDirty).toBe(false);
    const matrix = Matrix4_default.fromTranslation(new Cartesian3_default(10, 10, 10));
    node.matrix = matrix;
    expect(node.matrix).toEqual(matrix);
    expect(node.originalMatrix).toEqual(nodeTransform);
    expect(runtimeNode.transform).toEqual(matrix);
    expect(runtimeNode.transform).not.toBe(matrix);
    expect(runtimeNode.originalTransform).toEqual(nodeTransform);
    expect(runtimeNode.userAnimated).toBe(true);
    expect(mockModel._userAnimationDirty).toBe(true);
  });
  it("setting matrix to undefined resets node transform", function() {
    const node = new ModelNode_default(mockModel, runtimeNode);
    const matrix = Matrix4_default.fromTranslation(new Cartesian3_default(10, 10, 10));
    node.matrix = matrix;
    expect(node.matrix).toEqual(matrix);
    expect(node.originalMatrix).toEqual(nodeTransform);
    expect(runtimeNode.transform).toEqual(matrix);
    expect(runtimeNode.transform).not.toBe(matrix);
    expect(runtimeNode.originalTransform).toEqual(nodeTransform);
    expect(runtimeNode.userAnimated).toBe(true);
    expect(mockModel._userAnimationDirty).toBe(true);
    node.matrix = void 0;
    expect(node.matrix).toEqual(node.originalMatrix);
    expect(node.originalMatrix).toEqual(nodeTransform);
    expect(runtimeNode.transform).toEqual(runtimeNode.originalTransform);
    expect(runtimeNode.transform).not.toBe(runtimeNode.originalTransform);
    expect(runtimeNode.userAnimated).toBe(false);
  });
});

