// packages/engine/Specs/Scene/Model/ModelRenderResourcesSpec.js
describe(
  "Scene/Model/ModelRenderResources",
  function() {
    const mockModel = {};
    it("throws for undefined model", function() {
      expect(function() {
        return new ModelRenderResources_default(void 0);
      }).toThrowDeveloperError();
    });
    it("constructs", function() {
      const modelResources = new ModelRenderResources_default(mockModel);
      const defaultRenderState = RenderState_default.getState(
        RenderState_default.fromCache({
          depthTest: {
            enabled: true,
            func: DepthFunction_default.LESS_OR_EQUAL
          }
        })
      );
      expect(modelResources.model).toBe(mockModel);
      expect(modelResources.shaderBuilder).toBeDefined();
      expect(modelResources.renderStateOptions).toEqual(defaultRenderState);
      expect(modelResources.hasSilhouette).toBe(false);
      expect(modelResources.hasSkipLevelOfDetail).toBe(false);
      ShaderBuilderTester_default.expectHasFragmentDefines(
        modelResources.shaderBuilder,
        []
      );
    });
  },
  "WebGL"
);

// packages/engine/Specs/Scene/Model/ModelRuntimeNodeSpec.js
describe("Scene/Model/ModelRuntimeNode", function() {
  const mockNode = {
    matrix: Matrix4_default.IDENTITY
  };
  const mockRuntimeNode = {
    transform: Matrix4_default.IDENTITY
  };
  const mockChildRuntimeNode = {
    transform: Matrix4_default.IDENTITY
  };
  const transform3 = Matrix4_default.clone(Matrix4_default.IDENTITY);
  const transformToRoot = Matrix4_default.clone(Matrix4_default.IDENTITY);
  const mockSceneGraph = {
    computedModelMatrix: Matrix4_default.clone(Matrix4_default.IDENTITY),
    _runtimeNodes: [mockChildRuntimeNode, mockRuntimeNode],
    components: {
      upAxis: Axis_default.Y,
      forwardAxis: Axis_default.Z
    }
  };
  const scratchMatrix8 = new Matrix4_default();
  function verifyTransforms(transform4, transformToRoot2, runtimeNode, originalTransform) {
    originalTransform = originalTransform ?? transform4;
    expect(runtimeNode.transform).toEqual(transform4);
    expect(runtimeNode.originalTransform).toEqual(originalTransform);
    expect(runtimeNode.transformToRoot).toEqual(transformToRoot2);
    const computedTransform = Matrix4_default.multiplyTransformation(
      transformToRoot2,
      transform4,
      scratchMatrix8
    );
    expect(runtimeNode.computedTransform).toEqual(computedTransform);
  }
  it("throws for undefined node", function() {
    expect(function() {
      return new ModelRuntimeNode_default({
        node: void 0,
        transform: transform3,
        transformToRoot,
        sceneGraph: mockSceneGraph,
        children: []
      });
    }).toThrowDeveloperError();
  });
  it("throws for undefined transform", function() {
    expect(function() {
      return new ModelRuntimeNode_default({
        node: mockNode,
        transform: void 0,
        transformToRoot,
        sceneGraph: mockSceneGraph,
        children: []
      });
    }).toThrowDeveloperError();
  });
  it("throws for undefined transform to root", function() {
    expect(function() {
      return new ModelRuntimeNode_default({
        node: mockNode,
        transform: transform3,
        transformToRoot: void 0,
        sceneGraph: mockSceneGraph,
        children: []
      });
    }).toThrowDeveloperError();
  });
  it("throws for undefined scene graph", function() {
    expect(function() {
      return new ModelRuntimeNode_default({
        node: mockNode,
        transform: transform3,
        transformToRoot,
        sceneGraph: void 0,
        children: []
      });
    }).toThrowDeveloperError();
  });
  it("throws for undefined children", function() {
    expect(function() {
      return new ModelRuntimeNode_default({
        node: mockNode,
        transform: transform3,
        sceneGraph: mockSceneGraph,
        trasnformToRoot: transformToRoot,
        children: void 0
      });
    }).toThrowDeveloperError();
  });
  it("constructs", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(node.node).toBe(mockNode);
    expect(node.sceneGraph).toBe(mockSceneGraph);
    expect(node.children.length).toEqual(0);
    verifyTransforms(transform3, transformToRoot, node);
    expect(node.show).toBe(true);
    expect(node.userAnimated).toBe(false);
    node.configurePipeline();
    expect(node.pipelineStages).toEqual([NodeStatisticsPipelineStage_default]);
    expect(node.updateStages).toEqual([ModelMatrixUpdateStage_default]);
    expect(node.runtimePrimitives).toEqual([]);
    expect(node.translation).toBeUndefined();
    expect(node.rotation).toBeUndefined();
    expect(node.scale).toBeUndefined();
    expect(node.morphWeights).toEqual([]);
  });
  it("constructs with default transform parameters", function() {
    const mockNodeWithNoMatrix = {};
    const node = new ModelRuntimeNode_default({
      node: mockNodeWithNoMatrix,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(node.node).toBe(mockNodeWithNoMatrix);
    expect(node.sceneGraph).toBe(mockSceneGraph);
    expect(node.children.length).toEqual(0);
    verifyTransforms(transform3, transformToRoot, node);
    expect(node.translation).toEqual(Cartesian3_default.ZERO);
    expect(node.rotation).toEqual(Quaternion_default.IDENTITY);
    expect(node.scale).toEqual(new Cartesian3_default(1, 1, 1));
  });
  it("constructs with given transform parameters", function() {
    const mockNodeWithParameters = {
      translation: new Cartesian3_default(1, 2, 3),
      rotation: new Quaternion_default(0.707, 0, 0.707, 0),
      scale: new Cartesian3_default(1, 1, 2)
    };
    const node = new ModelRuntimeNode_default({
      node: mockNodeWithParameters,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(node.node).toBe(mockNodeWithParameters);
    expect(node.sceneGraph).toBe(mockSceneGraph);
    expect(node.children.length).toEqual(0);
    verifyTransforms(transform3, transformToRoot, node);
    expect(node.translation).toEqual(new Cartesian3_default(1, 2, 3));
    expect(node.rotation).toEqual(new Quaternion_default(0.707, 0, 0.707, 0));
    expect(node.scale).toEqual(new Cartesian3_default(1, 1, 2));
  });
  it("setting translation throws if node was constructed with matrix", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(function() {
      node.translation = new Cartesian3_default(1, 2, 3);
    }).toThrowDeveloperError();
  });
  it("setting rotation throws if node was constructed with matrix", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(function() {
      node.rotation = Quaternion_default.IDENTITY;
    }).toThrowDeveloperError();
  });
  it("setting scale throws if node was constructed with matrix", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(function() {
      node.scale = new Cartesian3_default(1, 1, 2);
    }).toThrowDeveloperError();
  });
  it("setting morphWeights throws if given different length array", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(function() {
      node.morphWeights = [0, 1, 2];
    }).toThrowDeveloperError();
  });
  const scratchTransform2 = new Matrix4_default();
  it("sets translation", function() {
    const mockNodeWithTranslation = {
      translation: Cartesian3_default.ZERO
    };
    const node = new ModelRuntimeNode_default({
      node: mockNodeWithTranslation,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    verifyTransforms(transform3, transformToRoot, node);
    expect(node.translation).toEqual(Cartesian3_default.ZERO);
    const translation3 = new Cartesian3_default(1, 2, 3);
    node.translation = translation3;
    node.updateComputedTransform();
    const translationMatrix = Matrix4_default.fromTranslation(
      translation3,
      scratchTransform2
    );
    expect(node.translation).toEqual(translation3);
    verifyTransforms(translationMatrix, transformToRoot, node, transform3);
  });
  it("sets rotation", function() {
    const mockNodeWithRotation = {
      rotation: Quaternion_default.IDENTITY
    };
    const node = new ModelRuntimeNode_default({
      node: mockNodeWithRotation,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    verifyTransforms(transform3, transformToRoot, node);
    expect(node.rotation).toEqual(Quaternion_default.IDENTITY);
    const rotation = new Quaternion_default(0.707, 0, 0.707, 0);
    node.rotation = rotation;
    node.updateComputedTransform();
    const rotationMatrix3 = Matrix3_default.fromQuaternion(rotation, new Matrix3_default());
    const rotationMatrix = Matrix4_default.fromRotation(
      rotationMatrix3,
      scratchTransform2
    );
    expect(node.rotation).toEqual(rotation);
    verifyTransforms(rotationMatrix, transformToRoot, node, transform3);
  });
  it("sets scale", function() {
    const mockNodeWithScale = {
      scale: new Cartesian3_default(1, 1, 1)
    };
    const node = new ModelRuntimeNode_default({
      node: mockNodeWithScale,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    verifyTransforms(transform3, transformToRoot, node);
    expect(node.scale).toEqual(new Cartesian3_default(1, 1, 1));
    const scale = new Cartesian3_default(2, 3, 4);
    node.scale = scale;
    node.updateComputedTransform();
    const scaleMatrix2 = Matrix4_default.fromScale(scale, scratchTransform2);
    expect(node.scale).toEqual(scale);
    verifyTransforms(scaleMatrix2, transformToRoot, node, transform3);
  });
  it("sets morphWeights", function() {
    const mockNodeWithWeights = {
      morphWeights: [0, 0, 0]
    };
    const node = new ModelRuntimeNode_default({
      node: mockNodeWithWeights,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(node.morphWeights).not.toBe(mockNodeWithWeights.morphWeights);
    expect(node.morphWeights).toEqual(mockNodeWithWeights.morphWeights);
    const morphWeights = [1, 2, 3];
    node.morphWeights = morphWeights;
    expect(node.morphWeights).not.toBe(morphWeights);
    expect(node.morphWeights).toEqual(morphWeights);
  });
  it("adds instancing pipeline stage if node is instanced", function() {
    const instancedMockNode = {
      instances: {
        attributes: []
      }
    };
    const node = new ModelRuntimeNode_default({
      node: instancedMockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: []
    });
    expect(node.node).toBe(instancedMockNode);
    expect(node.sceneGraph).toBe(mockSceneGraph);
    expect(node.children.length).toEqual(0);
    verifyTransforms(transform3, transformToRoot, node);
    node.configurePipeline();
    expect(node.pipelineStages).toEqual([
      InstancingPipelineStage_default,
      NodeStatisticsPipelineStage_default
    ]);
    expect(node.updateStages).toEqual([ModelMatrixUpdateStage_default]);
    expect(node.runtimePrimitives).toEqual([]);
  });
  it("getChild throws for undefined index", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: [0]
    });
    expect(function() {
      node.getChild();
    }).toThrowDeveloperError();
  });
  it("getChild throws for invalid index", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: [0]
    });
    expect(function() {
      node.getChild("s");
    }).toThrowDeveloperError();
  });
  it("getChild throws for out of range index", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: [0]
    });
    expect(function() {
      node.getChild(2);
    }).toThrowDeveloperError();
    expect(function() {
      node.getChild(-1);
    }).toThrowDeveloperError();
  });
  it("getChild works", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: [0]
    });
    const child = node.getChild(0);
    expect(child).toBeDefined();
    expect(child.transform).toBeDefined();
  });
  it("sets transform without replacing original", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: [0]
    });
    const newTransform = Matrix4_default.multiplyByTranslation(
      Matrix4_default.IDENTITY,
      new Cartesian3_default(10, 0, 0),
      new Matrix4_default()
    );
    node.transform = newTransform;
    expect(node._transformDirty).toBe(true);
    expect(Matrix4_default.equals(node.transform, newTransform)).toBe(true);
    expect(Matrix4_default.equals(node.originalTransform, transform3)).toBe(true);
  });
  it("updateComputedTransform updates computedTransform matrix", function() {
    const node = new ModelRuntimeNode_default({
      node: mockNode,
      transform: transform3,
      transformToRoot,
      sceneGraph: mockSceneGraph,
      children: [0]
    });
    verifyTransforms(transform3, transformToRoot, node);
    const newTransform = Matrix4_default.multiplyByTranslation(
      Matrix4_default.IDENTITY,
      new Cartesian3_default(10, 0, 0),
      new Matrix4_default()
    );
    node.transform = newTransform;
    node.updateComputedTransform();
    const originalTransform = transform3;
    verifyTransforms(newTransform, transformToRoot, node, originalTransform);
  });
});

