    it("fails to load with Draco decoding error", async function() {
      DracoLoader_default._getDecoderTaskProcessor();
      await pollToPromise_default(function() {
        return DracoLoader_default._taskProcessorReady;
      });
      const decoder = DracoLoader_default._getDecoderTaskProcessor();
      spyOn(decoder, "scheduleTask").and.callFake(function() {
        return Promise.reject({ message: "Custom error" });
      });
      const model = scene2.primitives.add(
        await Model_default.fromGltfAsync({
          url: dracoCesiumManUrl
        })
      );
      let failed = false;
      model.errorEvent.addEventListener((e2) => {
        expect(e2).toBeInstanceOf(RuntimeError_default);
        expect(e2.message).toContain(
          `Failed to load model: ${dracoCesiumManUrl}`
        );
        expect(e2.message).toContain("Failed to load Draco");
        expect(e2.message).toContain("Custom error");
        failed = true;
      });
      await pollToPromise_default(
        function() {
          scene2.renderForSpecs();
          return failed;
        },
        { timeout: 1e4 }
      );
    });
