        verifyRender(model, true);
        expect(renderOptions).toRenderAndCall(function(rgba) {
          original2 = rgba;
        });
        model.style = new Cesium3DTileStyle_default({
          color: "color('red')"
        });
        verifyRender(model, true);
        expect(renderOptions).toRenderAndCall(function(rgba) {
          expect(rgba[0]).toEqual(original2[0]);
          expect(rgba[1]).toBeLessThan(original2[1]);
          expect(rgba[2]).toBeLessThan(original2[2]);
          expect(rgba[3]).toEqual(original2[3]);
        });
        model.style = new Cesium3DTileStyle_default({
          color: "color('red', 0.5)"
        });
        verifyRender(model, true);
        expect(renderOptions).toRenderAndCall(function(rgba) {
          expect(rgba[0]).toBeLessThan(original2[0]);
          expect(rgba[1]).toBeLessThan(original2[1]);
          expect(rgba[2]).toBeLessThan(original2[2]);
          expect(rgba[3]).toEqual(original2[3]);
        });
        model.style = new Cesium3DTileStyle_default({
          color: "color('red', 0.0)"
        });
