// packages/engine/Specs/Scene/Model/ModelStatisticsSpec.js
describe("Scene/Model/ModelStatistics", function() {
  const emptyMap = new AssociativeArray_default();
  it("constructs", function() {
    const statistics2 = new ModelStatistics_default();
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({});
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("clears", function() {
    const statistics2 = new ModelStatistics_default();
    statistics2.pointsLength = 10;
    statistics2.trianglesLength = 10;
    statistics2.geometryByteLength = 10;
    statistics2.texturesByteLength = 10;
    statistics2.propertyTablesByteLength = 10;
    statistics2._bufferIdSet = { uuid1: true, uuid2: true };
    statistics2._textureIdByteLengths = { uuid3: 1234 };
    const map = new AssociativeArray_default();
    map.set("uuid", {});
    statistics2._batchTextureIdMap = map;
    statistics2.clear();
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({});
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("addBuffer throws without buffer", function() {
    const statistics2 = new ModelStatistics_default();
    expect(function() {
      return statistics2.addBuffer(void 0, false);
    }).toThrowDeveloperError();
  });
  it("addBuffer throws without hasCpuCopy", function() {
    const statistics2 = new ModelStatistics_default();
    expect(function() {
      return statistics2.addBuffer({}, void 0);
    }).toThrowDeveloperError();
  });
  it("addBuffer counts GPU buffers", function() {
    const statistics2 = new ModelStatistics_default();
    const buffer3 = {
      _id: "uuid",
      sizeInBytes: 10
    };
    statistics2.addBuffer(buffer3, false);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(10);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({ uuid: true });
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("addBuffer counts GPU buffers with CPU copy", function() {
    const statistics2 = new ModelStatistics_default();
    const buffer3 = {
      _id: "uuid",
      sizeInBytes: 10
    };
    statistics2.addBuffer(buffer3, true);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(20);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({ uuid: true });
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("addBuffer de-duplicates buffers", function() {
    const statistics2 = new ModelStatistics_default();
    const buffer3 = {
      _id: "uuid1",
      sizeInBytes: 2
    };
    const buffer22 = {
      _id: "uuid2",
      sizeInBytes: 3
    };
    statistics2.addBuffer(buffer3, false);
    statistics2.addBuffer(buffer3, false);
    statistics2.addBuffer(buffer22, false);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(5);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({ uuid1: true, uuid2: true });
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("addTexture throws without texture", function() {
    const statistics2 = new ModelStatistics_default();
    expect(function() {
      return statistics2.addTexture(void 0);
    }).toThrowDeveloperError();
  });
  it("addTexture counts textures", function() {
    const statistics2 = new ModelStatistics_default();
    const texture = {
      _id: "uuid",
      sizeInBytes: 10
    };
    statistics2.addTexture(texture);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(10);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({});
    expect(statistics2._textureIdByteLengths).toEqual({ uuid: 10 });
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("addTexture de-duplicates textures", function() {
    const statistics2 = new ModelStatistics_default();
    const texture = {
      _id: "uuid1",
      sizeInBytes: 2
    };
    const texture2 = {
      _id: "uuid2",
      sizeInBytes: 3
    };
    statistics2.addTexture(texture);
    statistics2.addTexture(texture);
    statistics2.addTexture(texture2);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(5);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({});
    expect(statistics2._textureIdByteLengths).toEqual({ uuid1: 2, uuid2: 3 });
    expect(statistics2._batchTextureIdMap).toEqual(emptyMap);
  });
  it("addBatchTexture throws without batch texture", function() {
    const statistics2 = new ModelStatistics_default();
    expect(function() {
      return statistics2.addBatchTexture(void 0);
    }).toThrowDeveloperError();
  });
  it("addBatchTexture counts batch textures as they load", function() {
    const statistics2 = new ModelStatistics_default();
    const batchTexture = new BatchTexture_default({
      featuresLength: 10,
      owner: {}
    });
    statistics2.addBatchTexture(batchTexture);
    const expectedMap = new AssociativeArray_default();
    expectedMap.set(batchTexture._id, batchTexture);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({});
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(expectedMap);
    batchTexture._batchTexture = {
      sizeInBytes: 10
    };
    expect(statistics2.batchTexturesByteLength).toBe(10);
    batchTexture._pickTexture = {
      sizeInBytes: 15
    };
    expect(statistics2.batchTexturesByteLength).toBe(25);
  });
  it("addBatchTexture de-duplicates batch textures", function() {
    const statistics2 = new ModelStatistics_default();
    const batchTexture = new BatchTexture_default({
      featuresLength: 10,
      owner: {}
    });
    const batchTexture2 = new BatchTexture_default({
      featuresLength: 15,
      owner: {}
    });
    statistics2.addBatchTexture(batchTexture);
    statistics2.addBatchTexture(batchTexture2);
    statistics2.addBatchTexture(batchTexture);
    const expectedMap = new AssociativeArray_default();
    expectedMap.set(batchTexture._id, batchTexture);
    expectedMap.set(batchTexture2._id, batchTexture2);
    expect(statistics2.pointsLength).toBe(0);
    expect(statistics2.trianglesLength).toBe(0);
    expect(statistics2.geometryByteLength).toBe(0);
    expect(statistics2.texturesByteLength).toBe(0);
    expect(statistics2.propertyTablesByteLength).toBe(0);
    expect(statistics2.batchTexturesByteLength).toBe(0);
    expect(statistics2._bufferIdSet).toEqual({});
    expect(statistics2._textureIdByteLengths).toEqual({});
    expect(statistics2._batchTextureIdMap).toEqual(expectedMap);
    batchTexture._batchTexture = {
      sizeInBytes: 10
    };
    batchTexture._pickTexture = {
      sizeInBytes: 20
    };
    expect(statistics2.batchTexturesByteLength).toBe(30);
    batchTexture2._batchTexture = {
      sizeInBytes: 25
    };
    batchTexture2._pickTexture = {
      sizeInBytes: 45
    };
    expect(statistics2.batchTexturesByteLength).toBe(100);
  });
});

