// packages/engine/Specs/Scene/Model/TextureManagerSpec.js
describe(
  "Scene/Model/TextureManager",
  function() {
    let sceneWithWebgl1;
    let sceneWithWebgl2;
    beforeAll(function() {
      sceneWithWebgl1 = createScene_default({
        contextOptions: {
          requestWebgl1: true
        }
      });
      sceneWithWebgl2 = createScene_default();
    });
    afterAll(function() {
      sceneWithWebgl1.destroyForSpecs();
      sceneWithWebgl2.destroyForSpecs();
    });
    const textureManagers = [];
    afterEach(function() {
      for (let i = 0; i < textureManagers.length; i++) {
        const textureManager = textureManagers[i];
        if (!textureManager.isDestroyed()) {
          textureManager.destroy();
        }
      }
      textureManagers.length = 0;
    });
    function waitForTextureLoad(textureManager, textureId, webgl2) {
      const scene2 = webgl2 ? sceneWithWebgl2 : sceneWithWebgl1;
      const oldValue = textureManager.getTexture(textureId);
      return pollToPromise_default(function() {
        scene2.renderForSpecs();
        textureManager.update(scene2.frameState);
        return textureManager.getTexture(textureId) !== oldValue;
      }).then(function() {
        return textureManager.getTexture(textureId);
      });
    }
    const blueUrl = "Data/Images/Blue2x2.png";
    const greenUrl = "Data/Images/Green1x4.png";
    const redUrl = "Data/Images/Red16x16.png";
    const blue10x10Url = "Data/Images/Blue10x10.png";
    it("constructs", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      expect(textureManager._textures).toEqual({});
      expect(textureManager._loadedImages).toEqual([]);
    });
    it("loads texture from a URL", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: blueUrl
        })
      );
      return waitForTextureLoad(textureManager, id).then(function(texture) {
        expect(texture.width).toBe(2);
        expect(texture.height).toBe(2);
      });
    });
    it("loads texture from a typed array", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          typedArray: new Uint8Array([255, 0, 0, 255, 0, 255, 0, 255]),
          width: 1,
          height: 2
        })
      );
      return waitForTextureLoad(textureManager, id).then(function(texture) {
        expect(texture.width).toBe(1);
        expect(texture.height).toBe(2);
      });
    });
    it("generates mipmaps when sampler type requires them", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: redUrl,
          minificationFilter: TextureMinificationFilter_default.LINEAR_MIPMAP_LINEAR
        })
      );
      return waitForTextureLoad(textureManager, id, false).then(
        function(texture) {
          expect(texture._hasMipmap).toBe(true);
        }
      );
    });
    it("resizes image to power-of-two dimensions if needed", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: blue10x10Url,
          minificationFilter: TextureMinificationFilter_default.LINEAR_MIPMAP_NEAREST
        })
      );
      return waitForTextureLoad(textureManager, id, false).then(
        function(texture) {
          expect(texture.width).toBe(16);
          expect(texture.height).toBe(16);
          expect(texture._hasMipmap).toBe(true);
        }
      );
    });
    it("can resize a texture supplied as a Uint8Array", function() {
      const redPixels3x3 = Array(9).fill([255, 0, 0, 255]).flat();
      const uint8array3x3 = new Uint8Array(redPixels3x3);
      const textureUniform = new TextureUniform_default({
        typedArray: uint8array3x3,
        width: 3,
        height: 3,
        minificationFilter: TextureMinificationFilter_default.NEAREST_MIPMAP_LINEAR
      });
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(id, textureUniform);
      return waitForTextureLoad(textureManager, id).then(function(texture) {
        expect(texture.width).toBe(4);
        expect(texture.height).toBe(4);
        expect(texture._hasMipmap).toBe(true);
      });
    });
    it("generates mipmaps without resizing in WebGL2", function() {
      if (!sceneWithWebgl2.context.webgl2) {
        return;
      }
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: blue10x10Url,
          minificationFilter: TextureMinificationFilter_default.NEAREST_MIPMAP_NEAREST
        })
      );
      const webgl2 = true;
      return waitForTextureLoad(textureManager, id, webgl2).then(
        function(texture) {
          expect(texture.width).toBe(10);
          expect(texture.height).toBe(10);
          expect(texture._hasMipmap).toBe(true);
        }
      );
    });
    it("destroys old texture before adding a new one", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: blueUrl
        })
      );
      return waitForTextureLoad(textureManager, id).then(
        function(blueTexture) {
          expect(blueTexture.width).toBe(2);
          expect(blueTexture.height).toBe(2);
          expect(blueTexture.isDestroyed()).toBe(false);
          textureManager.loadTexture2D(
            id,
            new TextureUniform_default({
              url: greenUrl
            })
          );
          return waitForTextureLoad(textureManager, id).then(
            function(greenTexture) {
              expect(blueTexture.isDestroyed()).toBe(true);
              expect(greenTexture.width).toBe(1);
              expect(greenTexture.height).toBe(4);
              expect(greenTexture.isDestroyed()).toBe(false);
            }
          );
        }
      );
    });
    it("getTexture returns undefined for unknown texture", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const texture = textureManager.getTexture("notATexture");
      expect(texture).not.toBeDefined();
    });
    it("sets a defaultTexture on error", function() {
      spyOn(Resource_default.prototype, "fetchImage").and.callFake(function() {
        return Promise.reject();
      });
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.update(sceneWithWebgl1.frameState);
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: "https://example.com/not-a-texture.jpg"
        })
      );
      return waitForTextureLoad(textureManager, id).then(function(texture) {
        const defaultTexture = sceneWithWebgl1.frameState.context.defaultTexture;
        expect(texture).toBe(defaultTexture);
      }).catch(console.error);
    });
    it("destroys", function() {
      const textureManager = new TextureManager_default();
      textureManagers.push(textureManager);
      const id = "testTexture";
      textureManager.loadTexture2D(
        id,
        new TextureUniform_default({
          url: blueUrl
        })
      );
      return waitForTextureLoad(textureManager, id).then(function(texture) {
        expect(textureManager.isDestroyed()).toBe(false);
        expect(texture.isDestroyed()).toBe(false);
        textureManager.destroy();
        expect(textureManager.isDestroyed()).toBe(true);
        expect(texture.isDestroyed()).toBe(true);
      });
    });
  },
  "WebGL"
);

// packages/engine/Specs/Scene/Model/TextureUniformSpec.js
describe("Scene/Model/TextureUniform", function() {
  const exampleUrl = "https://example.com/url";
  const greenTexture = new Uint8Array([0, 255, 0, 255]);
  const defaultSampler = new Sampler_default({
    wrapS: TextureWrap_default.REPEAT,
    wrapT: TextureWrap_default.REPEAT,
    minificationFilter: TextureMinificationFilter_default.LINEAR,
    magnificationFilter: TextureMagnificationFilter_default.LINEAR,
    maximumAnisotropy: 1
  });
  it("throws if no texture is specified", function() {
    expect(function() {
      return new TextureUniform_default();
    }).toThrowDeveloperError();
  });
  it("throws if both url and typedArray are specified", function() {
    expect(function() {
      return new TextureUniform_default({
        url: exampleUrl,
        typedArray: greenTexture,
        width: 1,
        height: 1
      });
    }).toThrowDeveloperError();
  });
  it("constructs with a URL", function() {
    const textureUniform = new TextureUniform_default({
      url: exampleUrl
    });
    expect(textureUniform.resource).toBeDefined();
    expect(textureUniform.resource.url).toEqual(exampleUrl);
    expect(textureUniform.typedArray).not.toBeDefined();
    expect(textureUniform.width).not.toBeDefined();
    expect(textureUniform.height).not.toBeDefined();
    expect(textureUniform.sampler).toEqual(defaultSampler);
    expect(textureUniform.pixelFormat).toEqual(PixelFormat_default.RGBA);
    expect(textureUniform.pixelDatatype).toEqual(PixelDatatype_default.UNSIGNED_BYTE);
  });
  it("throws if width and height are not provided for a typed array", function() {
    expect(function() {
      return new TextureUniform_default({
        typedArray: greenTexture
      });
    }).toThrowDeveloperError();
  });
  it("constructs with a typed array", function() {
    const textureUniform = new TextureUniform_default({
      typedArray: greenTexture,
      width: 1,
      height: 1
    });
    expect(textureUniform.resource).not.toBeDefined();
    expect(textureUniform.typedArray).toBe(greenTexture);
    expect(textureUniform.width).toBe(1);
    expect(textureUniform.height).toBe(1);
    expect(textureUniform.sampler).toEqual(defaultSampler);
    expect(textureUniform.pixelFormat).toEqual(PixelFormat_default.RGBA);
    expect(textureUniform.pixelDatatype).toEqual(PixelDatatype_default.UNSIGNED_BYTE);
  });
  it("constructs with a resource", function() {
    const resource = new Resource_default({
      url: exampleUrl
    });
    const textureUniform = new TextureUniform_default({
      url: resource
    });
    expect(textureUniform.resource).toBe(resource);
    expect(textureUniform.typedArray).not.toBeDefined();
    expect(textureUniform.width).not.toBeDefined();
    expect(textureUniform.height).not.toBeDefined();
    expect(textureUniform.sampler).toEqual(defaultSampler);
    expect(textureUniform.pixelFormat).toEqual(PixelFormat_default.RGBA);
    expect(textureUniform.pixelDatatype).toEqual(PixelDatatype_default.UNSIGNED_BYTE);
  });
  it("sets sampler settings", function() {
    const textureUniform = new TextureUniform_default({
      url: exampleUrl,
      repeat: false,
      minificationFilter: TextureMinificationFilter_default.NEAREST,
      magnificationFilter: TextureMagnificationFilter_default.NEAREST,
      maximumAnisotropy: 2
    });
    expect(textureUniform.sampler).toEqual(
      new Sampler_default({
        wrapS: TextureWrap_default.CLAMP_TO_EDGE,
        wrapT: TextureWrap_default.CLAMP_TO_EDGE,
        minificationFilter: TextureMinificationFilter_default.NEAREST,
        magnificationFilter: TextureMagnificationFilter_default.NEAREST,
        maximumAnisotropy: 2
      })
    );
  });
  it("sets texture settings for typed arrays", function() {
    const textureUniform = new TextureUniform_default({
      typedArray: new Uint8Array([255, 0, 0, 0, 255, 0]),
      width: 1,
      height: 1,
      pixelFormat: PixelFormat_default.RGB,
      pixelDatatype: PixelDatatype_default.UNSIGNED_SHORT
    });
    expect(textureUniform.pixelFormat).toEqual(PixelFormat_default.RGB);
    expect(textureUniform.pixelDatatype).toEqual(PixelDatatype_default.UNSIGNED_SHORT);
  });
});

// packages/engine/Specs/Scene/Model/TilesetPipelineStageSpec.js
describe("Scene/Model/TilesetPipelineStage", function() {
  const mockFrameState = {};
  function mockRenderResources() {
    return {
      shaderBuilder: new ShaderBuilder_default(),
      uniformMap: {},
      model: {
        hasSkipLevelOfDetail: function() {
          return false;
        }
      },
      renderStateOptions: {}
    };
  }
  it("configures the render resources for skipping level of detail", function() {
    const renderResources = mockRenderResources();
    const model = renderResources.model;
    model.hasSkipLevelOfDetail = function() {
      return true;
    };
    TilesetPipelineStage_default.process(renderResources, model, mockFrameState);
    const shaderBuilder = renderResources.shaderBuilder;
    ShaderBuilderTester_default.expectHasVertexDefines(shaderBuilder, []);
    ShaderBuilderTester_default.expectHasFragmentDefines(shaderBuilder, [
      "POLYGON_OFFSET"
    ]);
    ShaderBuilderTester_default.expectHasVertexUniforms(shaderBuilder, []);
    ShaderBuilderTester_default.expectHasFragmentUniforms(shaderBuilder, []);
    const uniformMap2 = renderResources.uniformMap;
    expect(uniformMap2.u_polygonOffset()).toEqual(Cartesian2_default.ZERO);
    expect(renderResources.hasSkipLevelOfDetail).toBe(true);
  });
  it("sets stencil test and mask", function() {
    const renderResources = mockRenderResources();
    const model = renderResources.model;
    TilesetPipelineStage_default.process(renderResources, model, mockFrameState);
    const renderStateOptions = renderResources.renderStateOptions;
    expect(renderStateOptions.stencilTest).toEqual(
      StencilConstants_default.setCesium3DTileBit()
    );
    expect(renderStateOptions.stencilMask).toEqual(
      StencilConstants_default.CESIUM_3D_TILE_MASK
    );
  });
});

